/* 令和2年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r02.committeeSessions.push(...[{"id":"r02-20201130-6","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"区民委員会","time":"午前１０時００分～午後 ２時３０分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を76件整理しています。","topics":[{"id":"topic-01","title":"第６４号議案、品川区手数料条例の一部を改正する条例","agenda":"第６４号議案、品川区手数料条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"さらに、今までのコンビニ交付の実績は分かるでしょうか。そこをお知らせください。","respondent":"木村戸籍住民課長","answer":"ざっくり申しますと、全部を１００といたしますと、そのうちの８％がコンビニで交付をされておる形になっております。４年前からスタートいたしましたけれども、当初は２％程度だったのですけれども、徐々に上がって、今、８％というような形になっておるところです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"１０万円の給付とか、区独自の応援給付金等々ある中で増えてきたという部分はあると思うのですけれども、これから戸籍がコンビニ交付で取得できるようになるに当たっての普及の伸び率はどのように考えられているか尋ねました。","respondent":"木村戸籍住民課長","answer":"実際には普及も目的で１００円を減額してスタートするということなのですけれども、このことによって、例えば１０万円であるとか、ああいう形の伸びはないだろうというところではありますけれども、便利になるということで、実際に普及率の向上にはつながるものと考えております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"確かにぐっと伸びるものではないと思うのですけれども、そもそもマイナンバーの普及がそこまで伸びないという大本の理由もあると思うのですけれども、この間の委員会等々で伺ったときには、交付率２０％という感じだったのですけれども、今もその程度で変わりはないか伺いたいと思います。","respondent":"木村戸籍住民課長","answer":"現在も大きな変化はございません。今、２１％ちょっとだと思います。","id":"exchange-003"},{"speaker":"つる副委員長","kind":"質問","question":"午前８時半から午後５時までという時間帯で一定カバーできる部分があるかと思うのですが、この辺の当初からの午前８時半から午後５時という時間帯の幅ですとか、その辺を改めて教えてほしいと求めました。","respondent":"木村戸籍住民課長","answer":"見込みとしては、そこまで収支のバランスみたいなところが変わってくるところまで伸びるかなというところは、正直そういうところです。利便性みたいな部分も考えますと、時間の延長に関しまして、できるような形でこれから考えていきたいというふうに思っております。","id":"exchange-004"},{"speaker":"つる副委員長","kind":"質問・要望","question":"そうした確認はぜひしたいと思うので、その機会にぜひ出していただきたい、これは要望にしておきます。それからあとは、今、もう１つの戸籍のほうの交付については、仕組み上といいますか、確認、事務処理上の理由というのはよく分かりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"反対です。理由も述べさせていただきたいのですが、やはり立ち止まって見直すべきだというふうに思っていますので、反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"第６５号議案、品川区立創業支援施設条例の一部を改正する条例","agenda":"第６５号議案、品川区立創業支援施設条例の一部を改正する条例","exchanges":[{"speaker":"くにば委員","kind":"質問・要望","question":"2)、3)の部分、果たしてこれがどういったものなのか分からないのです。なので、ここのブースについて、もう少し補足でご説明いただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"３年間使うことができるようなところがあって、創業支援で、そういうものを試すというところが非常に大きいところです。うちのほうの考えとしても非常に合うというところで、そういうところで今回、創業者にとっては一番いい方法だというところで選ばせていただいたです。","id":"exchange-007"},{"speaker":"くにば委員","kind":"質問","question":"2)、3)のところは、きちんとそれぞれ店員という形で人がいらっしゃるというイメージなのですか。さすがに狭いような気がするのですけれども、そういった事務所機能と店員の配置についてはどういったイメージなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"こういう状態ですけれども差し支えないですかというような部分と、あと、ここで事務所としての機能は難しいと思います。ここは４階なども交流サロンがありますので、店員さんなど、その辺はお互いの店主がやり取りする形になるかと考えているところです。","id":"exchange-008"},{"speaker":"くにば委員","kind":"質問","question":"４万８,０００円だとリーズナブルで、十分定着してしまうという部分だったのかどうかというのを、もう１点だけ伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"３年間やることができるというところがあったので、それよりは多くの方がここを出て次のところというようなところが今回一番大きかったところです。ですので、今までも部屋についてはずっと埋まっているような状況で来たところです。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"今回それが１万円と３,０００円という形で、誰でも気軽に入れるようなスペースになると思うのですけれども、こちらの審査に関して伺います。","respondent":"遠藤商業・ものづくり課長","answer":"その方の創業支援をしていくのだけれども、やってみたらどうですかとか、そういう部分も含めて面接で全て対応するです。","id":"exchange-010"},{"speaker":"くにば委員","kind":"質問","question":"第２、第３と貸会議室がありまして、この貸会議室を使わずに交流スペースにしなければならない理由は何かあるのでしょうか。2)、3)というこの店舗をさらに交流スペースの部分まで広げたほうが、これをあえて交流スペースという形で使わねばならない理由を説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターの課題となっていた１つが、武蔵小山創業支援センターの認知度を高めたいという部分があったところで、ここを交流サロンという形で設けさせていただいたところです。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"こちらのスペースは、４階にある交流サロンとは、何かこれ、前も別の案件であったような気がするのですけれども、交流サロンという部分と、１階の交流スペースという部分は、これは使い分けというか、切り分けはどういった意味合いで変えていくのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"交流サロン、１階の部分につきましては、空いているときはそういうような形でいろいろな人が打合せなどもさせていただけるというふうに考えています。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問","question":"次に工房の部分に移りたいと思います。もちろん３Ｄプリンタとかが使えたりとか、この道具であるとか、ご自身で作る形が整えられるのかというふうなことを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"ＳＨＩＰにも工房を設置させていただいて、あとはラミネーターとか、そういうちょっとしたものが作れるというようなことを想定しております。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"業者に発注せずにここで作れるというのは、非常にいいサービスができるのかというふうに感じました。もう１点、申込をすれば誰でも使える、誰でも使えてしまうところという意味合いでよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"既存の方に、なかなか創業支援施設が地域と交わる点もなかったのかというところもありますので、できるだけ多くの方に使っていただければというところで、今回こういった外の方も使っていただこうというふうに考えているところです。","id":"exchange-014"},{"speaker":"くにば委員","kind":"質問","question":"今、これはもう工事中ということでよろしいのでしょうか。最後にその点だけ伺います。","respondent":"遠藤商業・ものづくり課長","answer":"今年度に入って、コロナで遅くはなってしまったのですけれども、期間に間に合うように、今、工事をしています。","id":"exchange-015"},{"speaker":"松本委員","kind":"質問","question":"１号が「第６条第２項の規定により創業居室の使用の承認を受けていること」というふうになっていて、２号が「地域産業の活性化に寄与する事業を行っていること」と、具体的にはどういうものになるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"地域といいますのは、商店を営んでいるというぐらいにうちのほうでは考えているところです。","id":"exchange-016"},{"speaker":"松本委員","kind":"意見","question":"この２号のほうに当てはまるから、６条の承認を受けないといけない、ご教示ほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"何らかの形で、当然、貸出しするときには承認行為が必要になりますので、どこかの要件に該当するということでの判断をするような形になるかと思います。","id":"exchange-017"},{"speaker":"松本委員","kind":"質問","question":"工房ということで、レイアウトを見ると、どういうふうに申請するのかというところで、１階なので、入ろうと思えば簡単に入れるところだと思うのです。実際に１階の部分に誰かセンター側の受付の人がいるのか、ほかの階に行って申請するのか、その辺りはどういうふうになっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"基本的に１階に誰かが常駐しているということではなくて、４階に事務所がありますので、そこで手続をとっていただくような形になろうかと思います。係員のものが１階、無断で使っていればといいますか、分かるのかなというふうには思っているところです。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"それも品川区との関係ではどうなのかというところはあると思うのですけれども、広めにというか、緩やかに考えていらっしゃるというふうな理解でよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"創業支援といいますか、そういう交流が大事だというところで、なかなかそこら辺のバランスは難しいところかと思います。どうしても創業支援ということで、趣旨から考えますと、ぎりぎりのところまでやらせていただければなというふうに考えているところです。","id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"そもそも論をお伺いしますけれども、１億円、１０年で老朽化してしまうのですかということが１点。その辺についてお伺いします。","respondent":"遠藤商業・ものづくり課長","answer":"新しいものに挑戦するのだという部分があることと、そういうことで人が集まってくることで地域が発展していくという部分はあろうかと考えています。その辺を考えて、この創業支援を今、いろいろな形でさせていただいているというようなところです。","id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"そういう意味で伺ったので、もう１回その辺の答弁をいただきたいのと、それしかたっていないのに施設は老朽化してしまうのかということ。１億円以上のお金を使って、また改修していくのですか、この施設はということ。","respondent":"遠藤商業・ものづくり課長","answer":"こういう形で自治体が創業支援をやっているというところは、ほかの地域、２３区でも品川区は突出していると考えています。いわゆる創業支援という部分で、当初考えられていたコンセプトはあったかと思うのですけれども、そういう部分なのかと考えているところです。","id":"exchange-021"},{"speaker":"大倉委員","kind":"質問・要望","question":"ちょっと教えていただきたいのが、それはどういう情報、その辺の情報を教えていただきたいということが１つ。今ある１０１から１０３の部屋を２年にしたら、それは２年で終わるという話もあって、その辺も含めたところで説明をもう１回していただければ。","respondent":"遠藤商業・ものづくり課長","answer":"創業支援という部分につきましては、創業支援をしているのだと、そういう起業を支援している部分だというところで。１階の広さについて、最終的には、そういう中で今回こういう形で３つの施設を置いたような形で進めたです。","id":"exchange-022"},{"speaker":"大倉委員","kind":"質問","question":"どういったものをやられていて、それがうまくいっていないからここに至ったみたいな経緯が分かると、分かりやすいかなと思って。いろいろな人、地域の人に見てもらうとかというのも１つ形としてはあるのかというところでは、その辺の状況とかが分かれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"今まで武蔵小山創業支援センターもいろいろと外に向けてのアプローチなどをさせていただいているところはあるのですけれども、１階は店舗でしたので。そういう部分でも広がるのかというふうに思っているところですので、今後いろいろと考えていきたいというふうに思っております。","id":"exchange-023"},{"speaker":"石田（ち）委員","kind":"質問","question":"すみません、１点だけ。そうすると、改修等に向けて、アンケートや調査的なことはしてこなかったということでいいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"通常の使用の部分といいますか、特に改修に向けてのアンケートは特にとったというふうには聞いておりません。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問","question":"私も１０年が経過して老朽化というのが、そういう調査的なものもやっていない中で、どうして改修なのだろうということは感じたのです。しかも１億円もかけているので、やはり調査等も必要だったのではないかというふうに思うのですけれども、今後に向けて考えを伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"武蔵小山創業支援センターが、そういう部分についてはいろいろなところから御意見は頂戴しているところでございました。あるいは意見聴取なりがあった場合、こういう形でのご紹介といいますか、させていただければと思うところです。","id":"exchange-025"},{"speaker":"つる副委員長","kind":"質問","question":"今回、トライアルウォールについて月額３,０００円とありますけれども、それは正に規則の中に記載があるという理解でいいですか。一番最後の別表の中には、そのトライアルウォールについての３,０００円というのは、規則の中に３,０００円という記載があるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"おっしゃるとおりです。ここだけ３,０００円を規則のほうで定めさせていただいているところです。","id":"exchange-026"},{"speaker":"つる副委員長","kind":"意見","question":"これ、予約が入っていない時間は無料、ただ今ある交流室ないし会議室については別でということですね。どういう形で、その上で予約できてしまうのか、その辺りをとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"名前については愛称なども考えているところで、趣旨がちょっと違うところがあるので分かりづらいというふうに思っているところです。イベントをやるというのが一番の中心だと考えていますので、外から何かやっているのかなというふうなことを目指しています。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"確認","question":"配慮した工事状況なのかという確認と、今、通常店舗には都のお金とかが別でありますね。今回せっかくやるのだから、そういったものがついているのかということがちょっと気になったので、その辺りについて確認させてください。","respondent":"遠藤商業・ものづくり課長","answer":"保育園が２階と３階に入っておりますけれども、説明に行きまして、ここを何とかしてくれというところはないというふうに聞いているところです。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"しつらえとしてあるべきものなのかという理解、これだけ３店舗分としてスペースがあるわけですから、追加でやるべきこともあるのかなとは思います。いろいろな意見を伺っているところではあるのですけれども、その辺のサインについて最後に説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"あそこが武蔵小山創業支援センターだと見えるような形のものも、考えている、恐らくできるかというふうに思っているところです。多くの方が武蔵小山創業支援センターがあそこにあるという認知の部分、ちょっと見てみようかなという部分も含めて。","id":"exchange-029"}]},{"id":"topic-03","title":"に記載の順番を入れ替えまして、(5)第６３号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"に記載の順番を入れ替えまして、(5)第６３号議案、令和２年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"小芝委員","kind":"質問・要望","question":"これを契機に多くの店も大分仕切り板とか、まだまだ８月３１日以降に知ったという方がいて、そういう意味では本当にすごく心強いかとは思います。幾つか質問させていただきたいのですけれども、助成対象の事業者数が４７０件ということで、ざっと大まかに教えていただけますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"２番目に多かったのが飲食業の方で、こちらが１４０件弱ぐらい。はぐっと下がりまして、製造業、小売業、医療業など病院が大体３０件から５０件ぐらいというような形になっているところです。","id":"exchange-030"},{"speaker":"小芝委員","kind":"質問","question":"９月末にたしか審査が完了されて、その決定通知書を送られたということなのですけれども、振込はこれからということでよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"それが問題ないということであれば交付決定通知を送るのですけれども、実際にその後買われるとか、実績報告をいただく形になります。その段階での振込となりますので、もう既に振込をさせていただいているのですが、まずいただいてからという形の処理になるところです。","id":"exchange-031"},{"speaker":"小芝委員","kind":"質問","question":"それと、不交付、交付されていない事業者が４３件ということで、これも主な理由を教えていただけますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"書類審査になりますけれども、今回の感染症の対策という部分からはそういうふうに読み取れないというのが大きなところです。聞いている中からは、残念ながら対象として読み取れないというところで、この規定の中で不交付とさせていただいたところがあったです。","id":"exchange-032"},{"speaker":"小芝委員","kind":"質問・要望","question":"第二弾ということで、これから冬場を迎えるというところで、区のほうで冬場に特化した感染防止対策のイメージがあれば教えていただきたいと思うのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"１つは乾燥する部分と、そういう形で加湿器などの機能がついているところもあろうかと思いますので、そういう部分で多く助成の申請をいただければなというふうに考えているところです。","id":"exchange-033"},{"speaker":"藤原委員","kind":"質問","question":"対象者ですけれども、なぜ「ただし、販路拡大支援助成の交付決定者」は除いてしまったのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"知らなかったとか、そういう方をさらに今やっている中で、今回になってそういうものが必要になったというところを中心に考えているところです。先ほど何名か、１０％の方が落ちてしまっておりますので、今回は前回の方につきましては対象外とさせていただいたところです。","id":"exchange-034"},{"speaker":"藤原委員","kind":"質問・要望","question":"大変ですから、ここを手厚くしていっていただきたいという思いもありますので、上限２０万円で１回だけではという思いがあるのです。３回でも４回でも、コロナという意味の環境において、やっていっていただきたいと思うのですけれども、その辺についてはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"家賃支援とか、今回はこういうタイミングでということで、２回目という形でさせていただいたところです。支援するのは一番大事な仕事だと思っているところですので、いろいろな形で、この助成も含めていろいろ考えていきたいというふうに思っております。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"私も第３９号議案の実際に今年の６月のこちらの内容をもう１回確認しているのですが、助成額が６,０００万円、３００件を予定していたと思います。これが当初予定していたよりも圧倒的に多く追加でやっていただきたいという希望があって、こちらを追加で行ったという認識でよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"前回の販路拡大支援助成で３００件で予算要求させていただいたのですが、こういうご時世なので、内部で流用で対応させていただいたところです。５００件で、まだまだ需要があるだろうというところで、今回改めて５００件という形で要求をさせていただいたです。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"募集期間が２月２６日までということなのですけれども、一度前回までの４７０件に入った方でも、やっぱり季節柄で違ったりするではないですか。１回目に間に合わなかった人、プラス１回目で気づかなかった人という対象だけではなく、もう１回ご見解をお願いします。","respondent":"遠藤商業・ものづくり課長","answer":"まずは今までに助成を受けていない方が優先だろうという判断をこちらのほうでさせていただいたところです。で、支援という部分では大変重要だと考えていますので、感染症の状況などを見ながら適宜対応させていただければというふうに思っております。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"もう１点、実際に前回の４７０件の中でされた方がいらっしゃったのかどうかであるとか、そういった事例はあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"全体の１０分の１ぐらいがアクリル板、もちろん２つ申込をされている方もいるので、４７０分のというわけではないかと思いますけれども。おおむねそんなにこれに使うのかみたいなものは、記憶にないようなところです。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問・要望","question":"なので、私が今伺った１つの理由が、事業者に対してこういったことにも使えますという例示がたくさん増えると思うのです。それに対して上限２０万円の助成をして、それがさらにフィードバックできるのかということを伺いたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"今後、実際に実施報告の中で、こういう形で役立っているみたいなものを書いていただくような形になっております。そういう部分で、そういった部分でのセミナーなりとかという、うちのほうの施策にもうまくつなげていければというふうに思っているところです。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問・要望","question":"２０万円の助成が出るから、結局、例としてあとからどんどん出てしまうとむだになってしまうではないですか。引き続きですけれども、こういったことをもう少し力を入れて取組例のところに挙げていこうという部分があったら教えていただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"これからその中でどの業者が多いかということまではまだできていないところがあります。うまくいくのではないかみたいなことができるのかというところでの、今の段階では支援という形になるのかというふうに思っているところです。","id":"exchange-040"},{"speaker":"くにば委員","kind":"質問・要望","question":"前回３００件の当初の補正予算の件数、これが今回は１億円の予算で５００件ということで、もっとアピールをして宣伝をしてほしいと求めました。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"松本委員","kind":"質問","question":"これは当然入っていらっしゃるのですけれども、滞納というのは、猶予は含まれないというふうな理解でよろしいでしょうか。お願いいたします。","respondent":"遠藤商業・ものづくり課長","answer":"あくまでも滞納されているという形ですので、その辺の手続といいますか、猶予の申請をとっていただければ、そこはこちらの助成の対象とさせていただければというふうに思います。","id":"exchange-042"},{"speaker":"松本委員","kind":"質問","question":"これもほかの補助金とか助成金でもよく問題になりますけれども、これは最終的には課税対象というか、お金が入っている分は、この２０万円については課税対象ということでよろしいのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"特にこれが非課税対象というふうにはなっていないので、基本的にはそのように考えております。","id":"exchange-043"},{"speaker":"松本委員","kind":"質問","question":"今の２点の辺りもはっきり明示していただけると、その辺りも不意打ちにならないような形で告知の仕方を今後も考えてほしいと求めました。ここは早めにＰＤＦに差し替えていただいて、ずれがないような形にしてほしいと求めましたが、ここのところはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"ご指摘いただいたとおりだと考えています。すぐにＰＤＦに直したいというふうに思います。","id":"exchange-044"},{"speaker":"大倉委員","kind":"質問・要望","question":"今回、先ほど来のお話の中で、前回申し込んだ方は今回は公平性の観点から見ても申込についてはできませんというお話。例えば前回１０万円で、今回また出て１０万円というような上限まで使えるような検討はされたのかどうかということを教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"満額に満たなかった方をどうするのだですけれども、検討はさせていただきましたが、今回につきましては対象外という形で決めさせていただいたところです。","id":"exchange-045"},{"speaker":"大倉委員","kind":"質問・要望","question":"いいものだと１０万円かかってきてしまいますが、多分そういった質問はかなり来るのかと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"もう１回検討していただくということはできないのでしょうかということを伺いたいのと、やっぱりコロナ、マスクとアルコールというのは。これから必ず必要になってくるものですので、そこをもう１回ご見解を伺いたいと思います。","respondent":"遠藤商業・ものづくり課長","answer":"汎用品と言われているほかのものに転用できる部分については、今回のこちらの助成については対象外というふうにさせていただいているところです。お店の方がずっと使っているということも認識していますし、逆に言うと、こちらについてはご理解いただければというふうに思います。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"転用とか、状況とか現場を見ていただいて、そこは対象にした上で判断をしてもらうというふうにしていただきたいと思うのです。入ってきていただきたいという状況をつくるための助成金なので、そこを引き続き、引き続き検討していただきたいと強く要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"つる副委員長","kind":"質問・要望","question":"三弾と可能性としてはあるわけですから、そうしたときも含めて、ぜひそこは強く検討いただきたい。審査費用等については、これは確認したいのですが、時間がないので委員会外で確認をさせてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"どういう部分での影響が出てくるか分からないです。一応配慮はしていきたいと考えていますが、なかなか強制という部分では難しいかなというところは思っているところです。","id":"exchange-049"},{"speaker":"つる副委員長","kind":"質問","question":"そこは自由競争ではないですか。お金幾らですか、やっぱりそのようにかけ過ぎてもあれですよねという、そういうバイアスがかかると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"}]},{"id":"topic-04","title":"議案審査、(3)第７３号議案、指定管理者の指定","agenda":"議案審査、(3)第７３号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"提案","question":"どういう方なのか教えていただきたいのと、選定基準以外に区が提案というか、選定基準だけが満たされているということなのかを説明を求めました。","respondent":"古巻文化観光課長","answer":"突発的なケースに対応できるような体制があるか、それに対して点数をつけていく、そのような進め方になります。独自のそれを超えた提案もいただいている部分もありますので、そういった総合的な観点から評価をさせていただいたと、そのような流れです。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１回だけで終わられているということでいいのかということと、この間、委託料等々は変わらないという形での選定ということでいいのですか。そこを伺いたいと思います。","respondent":"古巻文化観光課長","answer":"選定委員会ですけれども、今回につきましては、この日、１日だけ、１回だけの選定委員会ということでやっております。収入が減りますので、そういったものも収支の要点を出していただいていて、妥当であるという判断をした上で選定に至ったです。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、今のお話だと、減るであろうという部分を区が上乗せして委託料を出すということでいいということですか。お願いします。","respondent":"古巻文化観光課長","answer":"そういう考え方ですので、場合によってはそういったことも起こり得るというふうに思います。必要経費が減る部分はありますし、その辺りをバランスをとっていただいている、そのような流れになります。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。管理職の方が、ここの品川区立総合区民会館においては、何人ぐらいいらっしゃるのか伺いたいのですが。","respondent":"古巻文化観光課長","answer":"区のＯＢとして元管理職の方、中川原理事長を入れまして３名の方が在職されております。現職の派遣で２名、合わせると３名プラス２名ということで５名ということになるのだというふうに数えることもできるかと思います。","id":"exchange-054"},{"speaker":"松本委員","kind":"質問","question":"予算というか、委託料のところもいろいろと影響があるのではないかと思うので、そういったところはぜひとも私としてもお願いしたいと思います。議案というところでお伺いしたいと思うのが、こちらの総合区民会館で、この辺りのご事情についてご説明ほしいと求めました。","respondent":"古巻文化観光課長","answer":"評議員会の中では説明をしていたと思いますし、実効性のあるそういったチェックについても、しっかりやっていかなければいけない。","id":"exchange-055"},{"speaker":"松本委員","kind":"質問","question":"今回のことを伺っていると、区民の方からの情報提供だったと思うのです。行政と管理の指定をされている側で２つあるわけですけれども、区側にあるのか、そこの点をお願いいたします。","respondent":"古巻文化観光課長","answer":"そうですね、基本的には条例を持っているのは区になりますので、条例上の責任というか、ルールを作った区の責任は当然あると思います。区立の会館でありますし、区側がしっかりそこはチェックさせるというような、そういったような形が正当なのかというふうに考えています。","id":"exchange-056"},{"speaker":"松本委員","kind":"質問","question":"今回の件を受けて、具体的に実際には指定管理者が見ていくということになると思うのですけれども、どういうふうなチェック体制をとっていくのか。どうやって把握していくのかとか、本件についても少し伺っているのは、そこのところの検討状況をお伺いできるか尋ねました。","respondent":"古巻文化観光課長","answer":"しっかり検討しているというところで認識をしておりますし、また、一定の期間がたちましたら。具体的にというところでは、お話しできる具体策はないのですけれども、今現在、検討中であるということで認識をしています。","id":"exchange-057"},{"speaker":"松本委員","kind":"質問・要望","question":"質疑というか、要望という形になると思いますけれども、今回はどうしても公募ではなくて、一旦流れてしまいながら決まっていく。これ自体はコロナの問題もあるので、そこの部分は今も申し上げたとおりで、具体的なところで把握していただくように努めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"藤原委員","kind":"確認","question":"そもそも論をお伺いしますが、今回こういういろいろな事情があって、指定管理の公募をしなかったのですよね。つまり、文章として特別な事情がある場合は、公募せずにみたいなことは入っているのか、まず確認。","respondent":"古巻文化観光課長","answer":"今回公募によらなかったことについては、基本的には公募であるというような原則がありますけれども、やはり事情によっては特定の事業者を選定できる、そういったような形のルールになっておりますので、そこは何か特別な扱いをしたということではないです。","id":"exchange-059"},{"speaker":"藤原委員","kind":"質問・要望","question":"何の意図もないですからね。そういうルール、担保になっているのですねという話で伺っていますので。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"しっかり継続、何となく継続が決まっているみたいな、しっかり説明できるような基準に基づいて選定をしたという事実を積み上げていくことで。ご心配の部分については… ２年弱、正直、収支は黒にはなりません。そういう中で受けていただけるところはないだろうと区では見込んで、今回については、再度。","id":"exchange-060"},{"speaker":"藤原委員","kind":"質問・要望","question":"ずっと区の行政に関してやられていたわけですから、だって、これがこういうふうにプラスになりますみたいなことはシートには出てこないですものね。そういうものも逆に出すべきだと私は思うのですけれども、いかがか尋ねました。","respondent":"古巻文化観光課長","answer":"考え方についても、区と両輪でみたいな、そのような形で運営をしていただいているということで認識しておりますので。こういったところでは新しい工夫をしてもらっているとか、そういうプラスの部分もしっかり説明できるような選定ができるといいのかと思います。","id":"exchange-061"},{"speaker":"くにば委員","kind":"提案","question":"いわゆる頭を使って新たな提案をするところだと思うので、そこについてぜひ伺いたいのは、そういったことがたくさん試みられていると思います。もう１つ、実際にどういった事業を展開するというような提案があったのか、それぞれどういった提案があったのかということを説明を求めました。","respondent":"古巻文化観光課長","answer":"それをさらに推し進めるというか、もう１つの表現の手法の１つとして取り入れていくというか、そのようなプログラムの実施も考えているようです。１つのやり方として、その辺りは新しい手法の１つとして評価をした、そのようなことです。","id":"exchange-062"},{"speaker":"くにば委員","kind":"質問","question":"正に目の前で、この大規模改修の手前がそれがしっかりできる設備が現状整っているかどうか、これから整う予定なのかどうかというのが１つ。先にそれを伺いたいです。","respondent":"古巻文化観光課長","answer":"そういった面では、一定程度のインフラがあるということで、まずは試み的にやってみるということが１つあるのだというふうには認識しております。足りない部分があれば、そこはしっかり整えていく、そういったような流れになるというふうな認識です。","id":"exchange-063"},{"speaker":"くにば委員","kind":"意見","question":"そのメニューの１つとして、いわゆる施設を売るパッケージの中にこういったものがありますというような形で、それはどちらのイメージなのかということが……との意見を述べました。","respondent":"古巻文化観光課長","answer":"できるというようなことで調整をしていくというふうに認識しておりますので、まだ不確定な部分がありますけれども、双方には対応できるのかというふうに思っております。","id":"exchange-064"},{"speaker":"くにば委員","kind":"質問","question":"先ほど伺った形だと、そこで何かイベントを行ってもらうみたいな形で、きゅりあんはどこに関わっているのかというのがちょっと見えなかったんです。何か演劇をやりますという際に、あくまできゅりあんはそういう施設を貸し出す側の立場で、もう１回ご答弁をお願いしたいのですけれども。","respondent":"古巻文化観光課長","answer":"そういった方々に働きかけて連携しながら、様々な検討をしていきたい、選定の点数の加点になったという流れです。","id":"exchange-065"},{"speaker":"くにば委員","kind":"質問","question":"では、これは新たな取組としてということで、現状これと同等の事業はきゅりあんではしていないということか尋ねました。","respondent":"古巻文化観光課長","answer":"基本的にはきゅりあんを使っての様々な活動ですので、外へというような働きかけとか、実際の活動はやっていないということです。新しい試みです。","id":"exchange-066"},{"speaker":"くにば委員","kind":"提案","question":"これは両輪というか、どんどん提案をしていただいたりとか、ノウハウをためていっていただいて進めていってほしいと求めました。以上２点ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-067"},{"speaker":"つる副委員長","kind":"提案","question":"ちょっと分からない部分もあるので教えていただきたいのですが、今の新たな事業展開を提案しているわけですけれども、ただ。そうした事業の提案が文化振興事業団から向こう５年間もう既になされているので、その前後を含めれば１年半ぐらいになるのでしょうか、本来との意見を述べました。","respondent":"古巻文化観光課長","answer":"やはり継続性の問題等がございまして、継続をしていく、こみゅにてぃぷらざ八潮の委託もお願いしている部分があります。それはないというふうに認識しておりますので、基本的に人件費的な部分については、必要な経費だというふうに考えているところです。","id":"exchange-068"},{"speaker":"つる副委員長","kind":"提案","question":"(3)公認会計士、こういった専門の方が入って見ていただいての区に対する提案という形だったと思うので、妥当であろうという評価だと思うのです。ただ約１年間、どういうことを考えられているのかというのは、もう既に具体的なものは何かあるのか尋ねました。","respondent":"古巻文化観光課長、山崎文化スポーツ振興部長","answer":"やはり継続的なというところをやはり重視すると、収入として見込めるような事業をやっていただく、そのような考え方なのかというふうに思います。ちょっとうまく答えになっているかどうか分からないのですけれども、より適正な… これも今いろいろ内部で検討していますけれども、文化振興事業団の方々自体は、それはそのままスライドして八潮のほうで諸活動をします。","id":"exchange-069"}]},{"id":"topic-05","title":"第７４号議案、指定管理者の指定","agenda":"第７４号議案、指定管理者の指定","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"さっきのところと同じ感じになるのですけれども、この有識者の２名は、ここの場合はどういう方になるのか尋ねました。","respondent":"中元スポーツ推進課長","answer":"２名のうち１名は弁護士の方で、もう１名は元品川区スポーツ推進委員の会長を１４年にわたってやっていらした方にお願いいたしました。やはり体育館ですので、利用者としての視点等も大事と思いまして、そういうことでお願いさせていただきました。","id":"exchange-070"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。ここも点数がついているのでしょうか、点数がつくというのは一緒で、何点ぐらいだったのかということを伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"こちらは１者ではありますが、指定管理者の候補者の提案書を紙で出していただき、実際に来ていただいてプレゼンテーションをしていただきました。","id":"exchange-071"},{"speaker":"石田（ち）委員","kind":"提案","question":"提案書に基づいて、私たちは提案書は見られずに選定した理由というところを見ていくだけになってしまうのですけれども、モニタリングから流れて。こちらのほうも区からの元部長だったり、元課長のＯＢがスポーツ協会のほうにはどの程度行かれているのか、伺いたいと思いますとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"ＯＢの在籍状況ですが、元部長が１名、事務局長です。区の管理職、課長級が１名、事務局次長ということで、こちらは区の管理職の卒業生としては２名です。","id":"exchange-072"},{"speaker":"くにば委員","kind":"提案","question":"２点伺いたいのですけれども、具体的にどういった内容で新規利用者を掘り起こそうと提案があったのか、そちらを伺いたいですとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"逆に、健康づくりという視点から啓発講座やお試し体験などを実施して、運動習慣のきっかけづくりを行っていきたいという提案がございました。そういうものに対して、こちらとしても様々な評価はさせていただいているところです。","id":"exchange-073"},{"speaker":"くにば委員","kind":"質問","question":"これが１５年間であるとか、ここ直近５年間であるとか、利用者数が上がっているかどうか。今後、新規利用者をこれだけ増やしていきますという具体的な数値目標を出しているかどうか、そこについて伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"昨年の１月ぐらいからほとんど、また４月以降は閉館もしておりましたので、なかなか難しいかと。競技の種目とかによっても変わってまいりますので、それを見込むというのは、実際問題なかなか難しいところがあるということで思っているところです。","id":"exchange-074"},{"speaker":"くにば委員","kind":"質問・要望","question":"例えばネーミングライツ等を活用して、そういった部分にもぜひともこれからの５年間、取り組んでいただきたいというふうに思う部分が１点です。結果的に１年、後倒しになった部分についても見込んでいたのかどうか、ここは中止の可能性はきちんと見込みをつけているのかどうか伺いたいです。","respondent":"中元スポーツ推進課長","answer":"本当に区民の昔からずっと継続していらっしゃる方の利用というところもあって、その辺のところはなかなか難しいです。そこももちろん見込んでおりまして、必要なものは支出をして、残ったものは区のほうに返していただくということでやらせていただく予定です。","id":"exchange-075"},{"speaker":"くにば委員","kind":"質問・要望","question":"ここから２年、３年、ここに莫大な経費をかけて予算を見込んでいる部分が完全に飛んでしまうということもあり得ると思っています。以上、要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2884#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":63313,"voices":219}},{"id":"r02-20201130-7","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"厚生委員会","time":"午前１０時００分～午後 ４時０７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を75件整理しています。","topics":[{"id":"topic-01","title":"第６７号議案、地方税法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","agenda":"第６７号議案、地方税法等の一部を改正する法律の施行に伴う関係条例の整理に関する条例","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"それで、結果として合計幾らなのでしょうか。どのような人が延滞金を徴収されているのか、その辺、どのような人が払っているのかということをお伺いしたいと思います。","respondent":"池田国保医療年金課長","answer":"〔「９万？」と呼ぶ者あり〕 合計で１０万８,８００円ほど、延滞金としてこちらのほうに入っているところです。特例割合を使っておりますので、納付期限の翌日から３か月を経過した日以降につきましては、年８.９％の割合がかかっているところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"１番目のほうですが、国民健康保険で取って、介護保険と後期高齢者医療で取らない理由は何かとお伺いしたのですが、その点もう一度お答え願います。現段階で国民健康保険で取って、どのような理由でそのような運用になっているのかということをお伺いしたつもりなのですけれども。","respondent":"池田国保医療年金課長、宮尾高齢者福祉課長","answer":"国民健康保険で現在取っている理由は、国民健康保険のほうで延滞金の徴収の準備、研究などが完了いたしまして、今年の４月からできたです。実際２３区の中で延滞金を徴収する区では… 私からは、介護保険料の滞納に対する考え方についてご説明をします。ですので、ここについては慎重かつ丁寧な対応が必要かというように考えております。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"今、国民健康保険では研究が終わったから取るようになったのだということですが、その研究で出された結論というのはどのようなことなのですか。その差が出たところを知りたいので、ご説明いただければと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"その中で平成３０年度に国民健康保険制度の改革がございまして、今年から保険料の延滞金を徴収する形ということで運用させていただいたところです。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"それが払えるものなら払いたいと思っているけれども、そもそも高過ぎるのだ、負担感があるのだ、とても大変なのだという意味では同じだと。取るほうの区の側から見てどうなのかという理由を、率直なところをお伺いしたかったのですけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"そういった面では、収入に合わせた負担をお願いしています。それに対して保険料の納付が遅れてしまった方に対して、ご協力いただくようなことをお願いするために、延滞金を運用し始めたということです。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問","question":"ですから、私は課題ではないかと思うのですけれども、その点ご認識いかがでしょうか。お伺いいたします。","respondent":"池田国保医療年金課長","answer":"私ども市区町村の国民健康保険では、こちらのほうにさらに増やしていただきたいということでご要望はさせていただいているところです。ですので、一応使うべきお金のために保険料を決定するということ、それから国や都に対しては予算についてのご要望はさせていただいているです。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのような点で、ぜひ取らないという運用を継続していただきたいと強く要望しておきたいと思います。それから延滞金の徴収はこれからでもやめるべきだということで、改めて要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"}]},{"id":"topic-02","title":"冒頭申し上げましたとおり、取上げる順番を変更し、議案審査（17）を先に行います。 それでは、第６３号議案…","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、議案審査（17）を先に行います。 それでは、第６３号議案…","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"２番が、当初１１月６日締切の、ＰＣＲ検査などを助成しますといったものに申し込んだものだと理解してよろしいのでしょうか。そして、障害者福祉課がご説明された２枚目の紙の分は、当初１１月６日締切だったその東京都のものとは関係ないものと理解してよろしいのか尋ねました。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"２点目の交付金につきましては、１１月よりも前に制度として提示をされていて、このタイミングで予算の要求をさせていただいたものです。３点目につきましては、寄附金の活用ですので… 障害者福祉課につきましては、都の補助金ではなく、自治体のクラウドファンディングを活用するものとなっております。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"障害者福祉課に対しては、なぜ申し込まなかったのかというふうにお伺いしたいと思います。私としては申し込んでいただきたかったというか、申し込むべきではなかったかと思うのですけれども、そのような点、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長","answer":"認知症高齢者グループホーム、これ以外にも東京都の補助金というのは、施設から東京都のほうに直接補助の申請をするというルートがあります。念のためというか、万全を期すために… 委員お尋ねの申込みについてですが、グループホーム等に新たに入所される方につきましては、これまでの予算の範囲内で対応が可能と考えております。今回の補正予算の予算案を提出することを見送った次第です。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"これから申し込むこともあり得るということですか。あるいはそもそも必要とは考えていないということか尋ねました。","respondent":"松山障害者福祉課長","answer":"予算の範囲内で対応可能と考えておりますので、補正予算を提出するということを致しませんでした。","id":"exchange-009"},{"speaker":"おくの委員","kind":"質問","question":"都が１０分の１０を助成してくれるという制度ですけれども、それに申し込んで、ＰＣＲ検査や、いろいろやれるということを、通所施設やグループホームなどに関して、障害者福祉課として必要だとはお考えにならなかったというようなことなのか尋ねました。","respondent":"松山障害者福祉課長","answer":"実際に必要だと考えております。ただし、現段階では新たな入所者の見込みが立てられなかったため、もし新規入所者がいましたら、予算の範囲内で対応していく予定です。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ぜひこれを行ってほしいということで、５月に要望に行ったときにセットで、区長のほうでお考えいただいて実現したものだと思っています。これを先方にはどういった形で、当然我々の要望とすると、それはしっかりお伝えいただきたいなと思うのが１点です。","respondent":"宮尾高齢者福祉課長、松山障害者福祉課長、高山健康課長、櫻木生活福祉課長","answer":"この購入費用の一部に今回の寄附金を活用していますという趣旨がしっかりと伝わるようご案内させていただきたいというように考えております。高齢者福祉課と同様に、区民の善意ということが事業所にきちんと伝わるような形の、何かしらの文書を作ってお渡しするということを考えております。私のほうからは支援金ということで、各医療機関への支援ということで、区民の方々からお寄せいただいた医療関係者へのご支援という。","id":"exchange-011"},{"speaker":"あくつ委員","kind":"質問・要望","question":"１件につき、すごく多いということでもないですから、伝わるようにやっていただきたいということが１つです。そのようなことも視野に入れて、何とかこのコロナ禍を皆様に生き抜いていただけるように、区のほうでしっかりと支援をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ＰＣＲ検査というのは意義のあるものではないかと思うのですけれど、それを１点お聞かせほしいと求めました。それから、ケアホームの新規入所者の場合はどうなるのかについても説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"今回のＰＣＲ検査費用の助成ということでの対象の考え方についてですけれども、地域密着型１施設分を予算案として提出しています。そのほか、９月に予算案として提出させていただいた、従業員に対するＰＣＲ検査も先週から行っているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実際申請されたのかどうかということは、区立の特養ホームも多いわけですから、把握されているのか。ケアホームも、品川区がつくってきた施設ですから、この考え方もお聞かせほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"指定管理施設の特養やケアホームについての申請状況ですが、現時点で申請をしているかどうかという情報は持ち合わせておりません。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこのところはぜひ把握をしてほしいと求めましたし、やはり区としても様々な情報が入る中で、ぜひそれは今後もしてほしいと求めました。必要性についてどう考えられるのかという辺りもお聞かせいただきたいのですが、今回は１６日で締切ってしまって、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"具体的には、利用者の方の検温を毎日毎日行うですとか、消毒等の徹底等に万全を期しているつもりです。ですので、今時点でこの考え方をしっかりと継続していって、引き続き感染拡大防止に万全を期してまいりたいと思っているところです。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほど６３人分の慰労金、１人５万円ということだったのですが、要支援のケアプランを作る職員という意味なのでしょうか。品川区でも１人６万円の、なかなか何というのですか、ちょっと見通しが分かったら教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長、高山健康課長","answer":"在宅介護支援センター２０か所の総合事業担当職員分というふうに書かせていただきましたが、区が事業費として申請する分です。支援金ということで支給させていただいたり、しっかりと協力をしていますので… 第３回定例会において、若干の遅れをもって進めざるを得ないですが、そちらについては速やかに進めてまいりたいと考えております。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その点を確認させてほしいと求めました。３か月に１回申請して、援助しなかった人でそのまま条件に合うような状況が続いている場合、再度の申請というのはできるのか尋ねました。","respondent":"宮尾高齢者福祉課長、櫻木生活福祉課長","answer":"私からは在宅介護支援センターの慰労金の補助経路ですけれども、各在宅介護支援センターが直接申請をするという。なお、予算をご承認いただいた後、速やかに各職員の下に渡るよう執行してまいりたいと考えています。 ４月にご申請された方が１２月で切れるということへの区の対応です。１つは、その状況を注視しつつ、適切に対応していきたいと考えております。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"実態を、具体的な状況をつかんでいる自治体から国に延長を求めていただきたいと私は思いますが、その点についてはいかがでしょうか。歯科医師会所属が５万円、額を１桁上げてもいいのではないかという思いをするくらいなのですけれども、お聞かせいただけたらと思います。","respondent":"櫻木生活福祉課長、高山健康課長","answer":"住居確保給付金の延長ですが、国のほうで具体的に１２月の延長というような方向で検討されていると認識しておりますので、注視してまいりたいと思います。支援金、給付金などの名目で介護従事者や保育従事者などに対して給付してきた金額などを基軸に、金額の検討のほうを開始いたしました。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"消毒液を各事業所に２本ずつということなのですが、この施設というのは、大小問わず一律２本ということなのでしょうか。事業所のほうからの要望ということで消毒液になったのか、また、施設で困っているものや足りないものなどということに対しては。","respondent":"高山健康課長、松山障害者福祉課長","answer":"やはり今回ガバメントクラウドファンディングなどで集めていただきました医療支援という、この事業の検討のほうを始めております。そして区民の医療支援という、その気持ちに寄り添いたいといった、そういった支援の内容と考えておりま… こちらも規模には応ぜず、一律２本ということで考えております。そのニーズに合わせた形で、衛生物品等を今後も考えてまいりたいと考えています。","id":"exchange-019"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この中で取上げている６５歳以上の高齢者や基礎疾患のある希望者に対して、例えば隣の目黒区などでも既にやり始めていることなのです。それこそこれからでも手を挙げて導入してほしい制度だと私などは思ってしまうのですが、どのようにお考えか、いま一度お伺いしておきたいと思います。","respondent":"鷹箸保健予防課長","answer":"決して例数は多くありませんけれども、症状がない方、それが正しいのかというところも非常に難しいところだというように考えているところです。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"２８日は１２人ということで、品川区の危機感というのですか、その辺のところはどう考えられているのかということをお聞かせいただきたいのです。８３％の使用率になっているということがテレビでも報道されていまして、そこのところではどのように考えられているのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"やはり濃厚接触者の方々への検査を確実に実施するようになった結果、無症状のご家族でお子さんとか、そのような方がとても増えている認識があります。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"迅速かつ集中的な対応が求められるということで、政府や自治体、現在の状況に一丸となって対処することが求められるということで言われて。私はこのようなことが必要なのではないかと思うのですけれども、この提言に対しての区としての捉え方はいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１例でも確認された場合というところ以外に、ここの実施というのが新たに、改めて打ち出されたのではないかと私は思うのです。このようなところに対しては、厚生労働省も求めているし、それに対しては区としてどう考えられるかということについて説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"保健所としてこう考えるというようなものは示して、そのようなものを所管課にお任せというような形でいいのでしょうかということが１つです。それは施設の中に外から新たに入っていくわけですから、そこのところで入院の人も、新たな入院者にはＰＣＲ検査をやるようになると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それに対して保健所としてはどう考えられているのか。それは高齢者福祉課のほうで判断してやってくださいという考え方なのか、その点についても伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ショートステイやデイサービスというのも、保健所として必要、意義のあることだというようには考えられないのでしょうか。小規模多機能とか、そのようなところに対しても同じ考え方になるのではないかと思うのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"対象の人数が非常に多いということもありますので、検査の方法も含めて、例えば目黒区では区内の医療機関に全て検査をお願いするようです。保健所の検査とは別に実施するようなのですが、その検査の実現可能性も含めて、今後検討していくべき問題かというように考えております。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"小規模多機能、そのようなところにまで拡大していただきたいですし、６５歳以上の高齢者と基礎疾患のある方も本当に心配しております。それは１つの安心になりますし、ぜひそのようなところで、ＰＣＲ検査を増やしていただくというようなところをご検討いただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"西村委員","kind":"意見","question":"担当課より丁寧な説明をしていただきました。区は現状をしっかりと捕らまえて適切な判断をしていただいていると考えていますので、本陳情に関しましては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"あくつ委員","kind":"意見","question":"本日結論を出すで、不採択です。この陳情の方も１つのお考えだとは思うのですが、合理的だなと思いますので、不採択ということにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"おくの委員","kind":"意見","question":"ますます、今度こそ増やしていかなければならないと思います。採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問","question":"前回もご説明いただいたということで、今回も同じように、現状区のほうが行っている対応で十分やっていただいているということです。具体的な方策も説明いただきましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-04","title":"したいと思います。 それでは、最初に通所系サービス施設といたしまして、(2)第７７号議案、(3)第７８号議案、(4)第７９号議案、(5)第８０号議案…","agenda":"したいと思います。 それでは、最初に通所系サービス施設といたしまして、(2)第７７号議案、(3)第７８号議案、(4)第７９号議案、(5)第８０号議案…","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"そして７施設について、なぜ有識者を入れるところがあって、そこのところを教えていただきたいのが１つです。まさか机上配付ということはないと思うのですけれども、その辺りを教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"令和２年８月１９日の総務委員会のほうで全庁的な説明があったというように聞いておりますが、企画部主導で今年から試行という形で。","id":"exchange-032"},{"speaker":"あくつ委員","kind":"質問・要望","question":"かなり活発な議論がなされたのかどうかというところと、４ページの、これは障害者施設も連続性が要求されるということでよろしいのかどうか。そのようなことであれば、なぜその文言が入っていないのかというところ、ちょっとその辺りを確認させてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"ちょっと抜粋ということになりますけれども、そういった様々なご意見をいただき、活発なご議論をしていただいたというふうに記憶しています。","id":"exchange-033"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの確認ですが、障害者施設はこの方２人と決めて、固定してやったと。拡大をしていただきたいと、それはどうしても方向性というものが見えるものですから、その辺りの今後の方向性を説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"それから施設については、もちろん可能な限り全施設に入れていくということが望ましいと私も考えております。急遽準備したということもありまして、残念ながら全施設はできなかったのですが、可能な限り拡大していく必要があろうと考えております。","id":"exchange-034"},{"speaker":"おくの委員","kind":"質問","question":"それともう一つ、この「合理的と認められる場合」というのは、具体的にどういったことなのでしょうか。それを伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"利用者満足度の視点という項目があるのは前回のモニタリングのときにもご説明させていただいたと思うのですけれども。これは継続をしてもらうことが望ましいだろうというように総合的に判断した場合に継続するということで合理的というような表現を取っている。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは私もずっと前から外部委員は入れるべきだというようなことで申し上げてきたので、その後のモニタリングには関わっていかないのでしょうか。ちょっと担当課長のほうからお聞きしたのですけれども、その公表についてどう検討されているのかお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"今後については、まだ外部委員の方に入ってもらうかどうかということの検討段階ではないので、今日の段階でお答えはできないのですが。この段階でお答えはできないので、こういった声が委員会であったということは伝えておいて… こちらも今回外部委員を、外部の方を入れた選考の過程というのは、企画部のほうで主導して今年初めて実施するものです。ですので、こちらの点数の公表等も含めまして、企画部のほうとも連動しながら、前に進めていきたいと考えています。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その関係を継続させ、長期的に安定したサービスの提供が求められる。今回２２施設が全て継続というようなことになっている理由というのも、そのように中身を検討していったら、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"基本の方針、次期５年間をお任せする指定管理者として適任かどうかということをこの間議論、審議してまいりました。継続性を持たせる、そういったところも総合的に含めて、今回結果として全て継続という形になったものです。","id":"exchange-037"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"２２施設が公募によらず継続ということになっている、継続性が必要だというようなことで継続されたのではないかというふうにお聞きしたのですけれども、そのようなことではないのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"ここが崩れてしまうと継続といっても中身が違ってしまいますので、特に継続性を重んじて、継続という対応をしたと。そのようなことです。","id":"exchange-038"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから今回５年たって、新たな５年間の指定管理ということになるのですが、その点についてもお聞かせほしいと求めました。それからもう一つ、あるのでしたらどのような中身で行われ、その結果どうだったのかということについてもお聞かせいただけたらと思います。","respondent":"宮尾高齢者福祉課長","answer":"定期的にやるものも行いますし、随時行うというものもあります。労務監査につきましては、現時点で私どものところにそういったものを行ったという情報は入ってきておりません。","id":"exchange-039"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その確認をお願いしたいと思います。せめて５年に１回の選定のところで必要ではないかと思うのですけれども、その点についてもお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"ちょっと今手元に資料がないので申し訳ないのですが、お答えできませんけれども、実施はしております。それをモニタリングのときに我々のほうで把握をするというのが、今の段階の流れです。","id":"exchange-040"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ちょっと引き続いて伺いたいのですが、どうだったのかというところは把握をしていただいて、報告していただきたかったと思います。私はそのような、人的な状況のようなものが分かるような形の資料もぜひ出していただきたいと要望したいのですが、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"それから離職率についても同様です。保険者としても大変重要なテーマであるというふうに捉えておりますので、こちらは引き続き様々な支援策を講じながら推進していく予定です。","id":"exchange-041"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"これは５年に１回の指定管理者の選定ということになるわけですから、透明性という形になるのですか、その点いかがでしょうか。それから先ほど伺ったところでは、なかったような感じがするのですが、改めて伺います。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"選定委員会でもそのモニタリングの内容についてはご説明しているというところで、内容についてはきちんと委員のほうにはお伝えしています。資料等につきましてもいろいろ検討はなされていくというように我々も考えておりますので… 指定管理者に次期の５年間をお任せするにふさわしいかどうかという視点を持って点数化をして、最終的にこちら、本日の資料に相なったです。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなものも含めて出していただきたいということで、今回は５年に１回の選定ですから、資料についてはご検討ほしいと求めました。これも、何か算定の根拠を改めてお伺いさせていただけたらと思います。","respondent":"寺嶋福祉計画課長","answer":"モニタリングの段階からいろいろな手を打つところが出てくるかと思いますので、そこについてはしっかり取組んでいければと考えています。今、そういったお金が全くかからないので委託料に反映されていないということで、大きく違っているということが挙げられると思います。","id":"exchange-043"},{"speaker":"高橋（し）委員","kind":"確認","question":"２つほどお尋ねしたいのですが、載っているのですが、ここに出てきているということはしっかりしているのだということでしょうかという確認です。２つとも確認なのですが、すみません。","respondent":"寺嶋福祉計画課長","answer":"それで経営についてはきちんと安定的に運営できているということの確認を取らせていただいているところです。区として支援できることについてはできる限りの支援をさせていただいて、介護人材が大変厳しいという中でも、選定委員会の中でもご報告しています。","id":"exchange-044"}]},{"id":"topic-05","title":"て、(6)第８１号議案、(7)第８２号議案、(8)第８３号議案、(9)第８４号議案、(10)第８５号議案、(14)第８９号議案…","agenda":"て、(6)第８１号議案、(7)第８２号議案、(8)第８３号議案、(9)第８４号議案、(10)第８５号議案、(14)第８９号議案…","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"人員体制というものが多床室とユニットケアでどう違うのかという辺りと、経営的にはどうなのかという辺り、ちょっとお聞かせほしいと求めました。モニタリングでそこを見ていないのですが、指定管理料が高くなるとか、そのようなことがあるのかどうか伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"多床室を持っているから経営的に不利ということにならないよう支援していくのが、我々の役目だというように考えているところです。例えばほかの施設での成功事例等は紹介するように努めているところでもありますし、こういったことを意識してやらせていただいているところです。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今、ユニットケアのほうの指定管理料が特に高いというわけではなくて、それでも運営はできているということで考えていいのでしょうか。私はやはり、集団入浴から一人ひとりのお風呂に入浴介助をするというようなことも変わってきたということを施設の方から伺ったこともあるのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"}]},{"id":"topic-06","title":"令和２年陳情第５６号、加齢性難聴者への補聴器購入費用の助成を求める陳情","agenda":"令和２年陳情第５６号、加齢性難聴者への補聴器購入費用の助成を求める陳情","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"ですから、積極的に推進していくということに、イコール踏み出していくということになっておかしくないのだと思うのです。そのように考えるべきではないかと思うのですけれども、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"我々はこちらの医療機器について専門ではないので、責任を持って有効性がありますというように断定することは、残念ながらできないです。我々もそこにつきましては、ぜひそうしていただければという考えを持っているということで再三申し上げているところです。","id":"exchange-047"},{"speaker":"おくの委員","kind":"質問","question":"先日の厚生委員会では有効性に対しては認識しているというように答弁されているのですから、その点を後退させる必要はないのではないでしょうか。伺います。","respondent":"寺嶋福祉計画課長","answer":"我々も日々情報収集をしておりまして、介護現場のほうでもコミュニケーションの大切さということは言っているということは聞いております。区として責任を持って、補助制度が一番効果的だということを現段階で申し上げることはできないと、このように申し上げているところです。","id":"exchange-048"},{"speaker":"おくの委員","kind":"質問","question":"これはご認識なさっているのでしょうか。それも伺っておきます。","respondent":"寺嶋福祉計画課長","answer":"２４％という数字がいつの調査か、すみません、私の手元の資料と数字が全く異なるのですが、我々が把握しているところとしては、補聴器を使わない理由の上位として挙げられていないということ、これについては前回の請願のときにご答弁申し上げたとおりです。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"賛成討論のときにも申し上げたのですが、耳鼻科の方の見解については重々認識をしており、同様の認識ですと答弁されておりますよね。ということは、早期着用がいいことだということが区の認識でもあるというふうに答弁していただいたと思うのですけれども、そこは違うのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"専門の医療機関の方が補聴器の有効性について認識があるというように言ったということを、再三になりますけれども、我々が我々の発信として。できる形の支援があれば、把握に努めているのですけれども、そういったことを責任を持って発信できる立場に今ないです。","id":"exchange-050"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"区は同様の認識だと前回は言われたと思うのですけれども、それが区の認識とは、専門家ではないからできないというようなことになるのですか。この間ずっと確認をしていたところなのですが、補聴器学会の方々も皆さん言われておりますし、区の認識にはならないというようなことなのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"区の認識になる、ならないということを申し上げてございません。それを専門家の立場、そこについても我々は情報としてしっかり持っているという、そのようなことです。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"ということは、耳鼻科の先生方が皆さん、専門家の方々がそろってそのようなことを言っているということは区も認めて、それは否定しないと。ではもしも、区がこれに対して補助制度をつくっていくということになる場合は、何か障害となることはあるのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"専門機関が皆さん言っているかどうかについては、申し訳ないのですが、この段階では責任を持って答弁することはできません。今の段階では普及しない理由が必ずしも経済的な理由だけではないということで、今の段階では補助制度に至るものではないと、このようなことです。","id":"exchange-052"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"区が助成制度をつくったということになれば、それは１つの契機になるでしょうし、経済的にもすごく助かるということにもなっていくと思うのです。私は助かるというところまでの補助制度をつくっていただきたいと思うのですけれども、その点についてもいかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"今の段階の想像では申し上げられませんので、これについては申し訳ないですが、分かりません。そのような場もありますので、それは今後の課題だと考えていますが、今の段階ではまだそこには至っていないです。","id":"exchange-053"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"東京都も、そこのところはやはり本当に聞こえというのは重要な問題ですので、区としてもここのところはぜひ取組んでほしいと求めました。今のところはということですので、これが最後というようにならないうちに、補助制度をぜひつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"西村委員","kind":"意見","question":"定期的な検査、調整がとても重要な器具であることを実感しています。ですので、まずは専門機関にて正しい理解を啓発していくことが必要だと思いますので、本陳情に関しましては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"}]},{"id":"topic-07","title":"令和２年陳情第５９号、生活介護の事業所運営法人を現在より減らすことがないことを求める陳情","agenda":"令和２年陳情第５９号、生活介護の事業所運営法人を現在より減らすことがないことを求める陳情","exchanges":[{"speaker":"渡部委員","kind":"提案","question":"確認をして、木曜日でしょうか、現事業者の継続を求める陳情が出されておりますという発言がありました。それと１点、おくの委員の質問の中で、４０名の議員全員に宛てて継続を求める手紙も送られてきておりますというような発言がされていたのですがとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"決まったところで、ここの議会の中でどれほど議論しても、もうそこで決まってしまうわけですから、決めるにあたってこの思いを聴いてほしいと。決めるにあたって、この切実な思いを聴いてほしいのだということが今回の陳情だと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"あくつ委員","kind":"質問","question":"ですから内容に配慮して、議会のルールとして、これについて審査してはいけないというようなルールは私はないと思います。先ほど理事者のほうからあのような説明がありましたけれども、本当にそれでいいのですかという感じを、私は受けています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"あくつ委員","kind":"質問","question":"公式に結びついたわけではないですから、恐らく相当気を遣った文章だなと、私は受止めさせていただいています。そこはできないということではないと、私どもは考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"西村委員","kind":"意見","question":"今公募中ですので、事業者選定に影響を与えるということと、公正な選定のため、倫理上私たちの考えは控えるべきではないかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"高橋（し）委員","kind":"意見","question":"現状、指定管理の選定を進めているところなので、委員としてそれに関して、現時点で可とも不可ともということを話すことによって、何らかの影響が、自分ではないと思って発言しても、結果として出たとしたら。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問・要望","question":"この中にも表れていますが、障害者の方を中心に考えるのか、ここのところが問われているのではないですかという質問をさせていただいたつもりです。今回ご答弁がないということですから、意見表明のような形になっていますけれども、最後に１つだけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"需要はどうなっているのですかと課長に伺ったら、２倍とか、そのような形で需要がぐんと増えているというようなことが分かったのです。さらに荏原地域に考えています、またさらに誘致もしますというようなことで答えられているわけですから、その点について伺えたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今後新たな施設が必要だというように考えていますと、私はそのように答弁してほしいと求めましたけれども、どうでしょうか。そのような場をつくっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"事業所の整備につきましては、現在も進めているところです。利用者への対応につきましては、必要性があると判断した場合は説明をする機会等を設けたいと思います。","id":"exchange-064"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひやっていただきたいということでお願いしたいと思うのですが、いかがでしょうか。そのような事業所をつくっていくということが必要ではないかと私は思うのですけれども、そこのところはどう捉えられているのか伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"区民への説明につきましては、先ほどもご説明させていただきましたが、必要と判断した際に対応したいと思います。方向性としましては、事業所を増やしていって、利用者の選択肢を広げていけるよう取組んでまいりたいと思っているところです。","id":"exchange-065"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この１年間、そして皆さんがぜひこれをなくさないでほしいという声を上げているということが、今の状況だと思うのです。そして実際に１年間たって、期待に十分応えていただいた、そこのところは区としてどう受止められていますか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"指定管理者において、利用者満足度を向上させる取組みはとても大切な視点であるという認識です。その上で、地域生活の支援拠点という施設の設置目的に沿った運営ができるかどうか等を総合的に評価することも必要であると考えております。","id":"exchange-066"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"今回の公募はそのように建物管理と一体管理というようなことでの公募ですから、本人のことを一番に考えて支援をしてくださってきたと。本当にしっかりと当事者の立場に立って、この当事者の思いを区としてどう受止められているか、その受止めについてちょっと伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"当事者の思いということですけれども、施設に対する評価として受止めております。","id":"exchange-067"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"どう受止められているかということを伺っているのに、評価として受止めていますという一言だけで済まされるでしょうか。ちょっとその点についても伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"あまり言いますと公募のほうに影響が出ますので、コメントは差し控えたいと思うのですけれども、評価というところでいうのであれば、利用者に沿ったきめ細やかな支援をされていらっしゃるなというところは感じているところです。","id":"exchange-068"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区としても基本に据えてほしいと求めましたが、いかがでしょうか。先ほどもこれを一番に考えるべきだということがありましたけれども、そのことをどう位置づけ、伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"委員の言っていることは当然の考え方だと考えております。その上で、施設の設置目的に沿った事業運営ができるようにということで、取組んでまいりたいと思っているところです。","id":"exchange-069"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"混乱しているという状況が訴えられているわけですから、必要だと思えばということですが、その点について伺いたいと思います。家族の要望、そしてどのように審査に反映させていくのかという点について、具体的にどうされるのかお聞かせほしいと求めました。","respondent":"築山障害者施策推進担当課長","answer":"利用者の意見につきまして、審査会の前に実施という予定はございません。審査の基準につきましては、お答えできる範囲での回答とさせていただきたいのですけれども、事業運営というところで見ていくことになっております。","id":"exchange-070"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そのようなところはぜひとも受止めて、選定してほしいと求めました。２つの委員会があるのか伺いたいということと、合計４名の外部委員を入れるということになるのか、その点についても伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"選定につきましては、指定管理の区のガイドラインに沿って対応しているものです。それから外部委員につきましては、複数名入る予定ですけれども、現時点での詳細については控えさせていただきたいと思います。","id":"exchange-071"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"今ちょっと聞き取れなかったのですが、２つの委員会に２名ずつで、合計４名入るということで、今答えていただいたのでしょうか。違いますか。","respondent":"築山障害者施策推進担当課長","answer":"委員構成に関わることにつきましては、現在公募期間中ということで、回答のほうは差し控えさせていただきたいと思います。","id":"exchange-072"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それと外部委員を２名ということは、２名というようになると思うのですけれども、両方なのかは言えないということですか。別に名前を教えてとは、２名ずつ入るかどうかと、その辺までなぜ言えないのか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"構成に関することの詳細はお答えできませんが、審査会、選定委員会ともに外部委員が複数名入る予定になっております。","id":"exchange-073"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それだけ皆さんが、今の事業所に何としても続けていただきたいという、その強い思いをこのように陳情という形で出していただいたのだと思うのです。その思いをしっかりと、品川区として受止めていただきたい、このことを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"意見","question":"継続です。先ほど渡部委員からもありましたとおり、公募の期間ということもあるので、それも配慮した上で継続ということにしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3582#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":83993,"voices":286}},{"id":"r02-20201130-8","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"建設委員会","time":"午前１０時００分～午後 １時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"第９２号議案、北品川一丁目地内特別区道路線の認定","agenda":"第９２号議案、北品川一丁目地内特別区道路線の認定","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"お話では２０２７年頃ということだと、大体２０３０年頃ではないですかというのが我々の理解なのだけれども、その理解でいいのかということ。それは地域のお話も聞いてそのままの状況でこれが出てきていますということで理解していいのかというところだけ教えてほしいと求めました。","respondent":"稲田土木管理課長","answer":"位置を変えたというようなものですので、区道III－２０号が、位置を変えて旧東海道につながってきているです。これは道路として、ほかのところもそうですけれども、路線として今後やっていくものです。","id":"exchange-001"},{"speaker":"石田（秀）委員","kind":"意見","question":"２０３０年頃と我々は理解しているので、地域の方からお話があったから、先ほど言った清水横丁の話。計画のところに入っていないけれども、これはこれで地域の方々と話してこういう形になっているという理解でいいのかというところだけお願いしますとの意見を述べました。","respondent":"中道まちづくり立体化担当課長","answer":"駅前広場のほうは令和２年４月１日から令和１６年３月３１日までという形で、今、事業期間を指定しています。道幅であったり、地域の方の意見を踏まえまして、また整備の内容等については検討してまいります。","id":"exchange-002"},{"speaker":"西本委員","kind":"確認","question":"今までも幾度かご説明があったと思うのですが、確認も含めて、重複になるかもしれませんが、お願いいたします。結局、最終的には区道III－２０号というのはなくなるわけであるので、ここはどういう状況になっていくのでしょうかということ。","respondent":"中道まちづくり立体化担当課長","answer":"今現在、詳細については、東京都が検討中です。車道上に自転車のレーンを設置するかというところにつきましては、今現在、調査というか、詳細な検討をしています。","id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"すみません、１点、答弁漏れというか、黄色いところは今どうなっているのでしょうかという。〔「線路」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"線路。今、どういう状況になっているのですかというのを。","respondent":"中道まちづくり立体化担当課長","answer":"黄色い区域の部分につきましては、今現在、線路上というところで、京急が用地を持ってあります。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"一体的に進められているという状況ですけれども、そこの関連性を改めて伺いたいと思いますので、ご説明いただけたらと思います。そこを伺いたいのと、そういった広場を使用するにあたっての手続きというのはどういったことが必要になってくるのか、伺います。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"２つ目、清水横丁の道幅または景観であったりというところは、意見交換を重ねてあります。こちらのほうの駅前広場をどういう広場にしたらいいかと、地域の方を併せまして、検討している最中です。 交通管理者の警察の許可が要るというところでございまして、もちろんそういうところで警察と区と協議もしながらですが、そういう手続きが必要になってきます。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"最初の説明のときにも、一体的に行われているという説明があったので、それは関連性がないとは言えないと思います。そこの建物が除却されてしまって、旧東海道の景観というのが壊されてしまうのではないかと思うのですけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"生け垣や、また、そうした壁等のしつらえ等で景観を守っていきたいです。そうしたことも踏まえまして、今現在、地域と意見交換をしながら進めているところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"やはり建物がなくなることで景観が変わってしまうということになりますので、そこは守れないのではないかと私は思っております。意見書の募集なども行われておりますが、意見書の賛成・反対の数というのがどうなっているのか、伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"当初は、２０通、５８名の方から、変更のときには１５通、１６名の方からいただいているです。変更案につきましては、また、または清水横丁の道幅といったことを配慮した計画案について賛成します」という意見を多数いただいてあります。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問・要望","question":"意見書のほうは、たしか最近行われたものでは、賛成２件、反対十何件という感じだったと思うのです。やはりそうしたところでやっていくということが必要だと思いますので、ぜひそのように進めてほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの変更のときの意見書の数、賛成・反対の数ですが、賛成が２通、反対は１２通、その他といたしまして１通あります。地域の方と話し合って進めてほしいですが、こちらの駅前広場の事業を進めている最中ですので、私たちも進めていきたいと考えています。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"そして、スケジュール感なのですけれども、もう一度確認させていただいてもいいですか。ここには、私の調査漏れなのか、そういったことがもうどこかで報告されていたのかというところも併せて伺いたいと思います。","respondent":"稲田土木管理課長","answer":"この事業自体を議案にかけているというものではございませんで、ここの図に示す赤い部分での路線を認定するです。これは事業認可が４月に下りておりますので、速やかにというのですか、そういう形でこのような手続きをしているものです。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、今、感染症が広がる中で、シーリングがかけられているときに、なぜこのタイミングなのか。区としても、今この認定を出す時期なのかというところもお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"この事業ですが、まず、区が事業主体ですが、事業を進めていくにあたっては、国費または都費といった補助金を入れていきます。今年の６月３０日の建設委員会での報告で、事業決定をしましたので事業を進めるというところで、地域に対して事業の概要等を説明した経緯があります。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"工事とかは、では、都としてもこちらのほうは進めていくということなのですか。そのスケジュール感を先ほど伺ったと思うので、そちらもお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"この事業を進めるか進めないか、まず１点目のご質問ですけれども、進めてまいります。今現在、東側のほうにはにぎわいを創出する広場といった形で、こういった駅前広場の事業を進めていきたいと考えています。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"この道路を造ったら、学生の滞留が解消されるのですかというところと、あと、車ですよね。というところとかも、利便性が、広場を造ってにぎわいがというところが主だったのかというのを思ったのですけれども、そこら辺を確認させてください。","respondent":"中道まちづくり立体化担当課長","answer":"東京都が行います連続立体交差事業で、こちらにあります踏切が３か所解消されます。今タクシーまたは一般車両といったものが気軽に乗り降りできるところが駅前にないというところで、西側に交通機能を持たせた広場を造るものです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"それほどここでタクシーを利用するというのが、地域でもあまりないのかというのは感じていまして、地域の方からもそういうお話を伺っています。立体化が地域から求められているのはすごく分かるのです。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどご説明いたしました国費の申請をする前に、今、行政手続きを進めている最中です。将来も踏まえて、こういったところの品川駅から歩いてこられる北品川駅というところで、交通機能を向上させたいです。","id":"exchange-014"},{"speaker":"のだて委員","kind":"質問","question":"財源がどうなるのかということで、区が施工して予算をつけていくのかどうかというところを、財源がどうなるのかというところを伺いたいと思います。そうすると、住民の方が気軽に使えなくなってしまうのではないかと思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長、稲田土木管理課長","answer":"財源ですが、事業主体が区ですので、まず区がそちらのほうのお金を用意する。その中で、国費が約５０％、また都費が約２０％ということで、約７割の補助金を入れて事業を進めていきたいと考えています。広場を使うときにはということで、先ほども言いましたけれども、イベントやおまつり等で使う場合、一般的には警察の許可が要るです。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"今、普通に使う場合は許可は必要ないということでしたけれども、普通というのはどういうことですか。おまつりとか、そういうときに使う場合には許可が必要だと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"認定については、今なぜこのタイミングなのかというところも、やはりお話を伺ってもよく分からなかったというところと、あと、道路にしてからの利便性というところも分からなかったというところで、ここの認定については反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","agenda":"令和２年陳情第６０号、「大井町駅周辺地域まちづくり方針」のＣ地区に関する陳情","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"実際、そういうことが話されたのか、伺いたいと思います。区の認識として、この準備組合というのは残っていると考えているのか、伺います。","respondent":"多並都市開発課長","answer":"まずは知っていこうということを有志の方々が集まって進めている会と認識していますし、事務局の方もその会の中で説明されております。具体的には、やはり地域活動でもありますので、そこは区としての今の認識というのをご理解いただきたいと思います。","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"そうしたよさを残しながら改善をしていく手法というのはどういったものがあるのか、伺いたいと思います。そのまま残ってしまうのか、伺います。","respondent":"多並都市開発課長","answer":"検討していくことが重要でありますけれども、基本的には組合の中で検討していただくことになりますので、区としても事業計画を認可する場合には。","id":"exchange-019"},{"speaker":"のだて委員","kind":"質問","question":"この借金がどうなってしまうのかというところで、仕組み上の話で伺いたいのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"皆さんで話し合って進めていただくのですけれども、清算についても同じような考え方で、皆さんで考えていただくことになります。借金がなくなるわけではありませんから、そういうのも全体を含めて皆さんで考えていただくというのが答えかと思います。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"今こうした再開発をやめてくれという声が出ているわけですから、こういう手法がありますということで、ぜひやってほしいと求めました。大井一丁目南第１地区ですかね、本組合の設立をしたときの地権者数と同意人数を伺いたいのですが、いかがか尋ねました。","respondent":"多並都市開発課長","answer":"まだ、事業がどういうものがあるかというのを皆さんで勉強しようとしている段階ですので、そういう段階だとご理解いただければと。反対だというわけではなくて、それをまず知っていただくということで、みんなでそういうのをやっていただく段階だとご理解いただければと思います。","id":"exchange-021"},{"speaker":"のだて委員","kind":"質問・要望","question":"住民合意のもとで進めてほしいということですので、進めたいことも含めてですけれども、よりよいまちにしていくと。まちのよさを活かしながら進めていくということでやっていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"「地域の実情等を踏まえた方針の見直しを要望」ということで、先ほどの冒頭の説明の中でも、この陳情の趣旨と本当に合致をしていますよね。区のほうにこの陳情について何か伺うというのはとても変な形だと思うのですけれども、陳情にはぜひ皆さんに賛成してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"ですので、こういうのは、まず１つは、区の関与というのがどこまでできるのですか。それを品川区としてのメッセージというのは、しっかりと示していかなければならないのではないかと思いますが、今までのご見解をお聞きします。","respondent":"多並都市開発課長","answer":"耐火、このＣ地区については４割程度ということで、ほかの周辺地区よりは課題が多いということは認識しているところではあります。段階的にというのはそういう意味も含んでいますので、そう考えているところです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問・要望","question":"確認をさせていただきたいのですけれども、私はそのように受け取りましたので、客観的にお話を聞きたいと思いますけれども。改めて説明を求めました。","respondent":"多並都市開発課長","answer":"勉強会のほうが、令和元年５月から第１回目で、令和元年７月、９月、１１月、あと、令和２年１月で５回ということをやられていると認識しています。心配する会が令和２年２月、３月ということで、２回やられているということで認識しております。","id":"exchange-025"},{"speaker":"大沢委員","kind":"意見","question":"ということは、まだその中では意思の疎通というか、心配されている方は分かりますが、その中では双方の意思の疎通が十分に行われていないということが見受けられるのですけれども、そこのところをどのようにお考えになりますかとの意見を述べました。","respondent":"多並都市開発課長","answer":"意思疎通については、まちづくり勉強会のほうに心配する会の方が出席されて、再開発についての、例えば、心配されることをご発言いただいていると。その段階ではないというご説明をして、行き来をしているような、そういう認識で区としては思っているところです。","id":"exchange-026"},{"speaker":"大沢委員","kind":"確認","question":"それだと、ここのところの方針については、かなりの弾力性というか、遊びがあると考えます。ここに言う、都市再開発法で定めた権利変換なるものに対して決まったというわけではないということで、そこは一回確認させてください。","respondent":"多並都市開発課長","answer":"今、委員のお話のとおり、まさにそのとおりで、権利変換というのはもっと本当に先の話で、まだその本当の前の前の段階とご理解いただければと思います。","id":"exchange-027"},{"speaker":"大沢委員","kind":"意見","question":"初期段階で方向性が決まっていないということですので、初期段階であれば、今後の様々な調整方が必要になってくるわけだと思います。そこのところの段取りはどのようにお考えになりますかとの意見を述べました。","respondent":"多並都市開発課長","answer":"まちづくり協議会だとか、そこの中でまずは話し合っていただくことになるかと思いますけれども、そういう次の段階に移るかどうかの途中だとご理解いただければと思います。","id":"exchange-028"},{"speaker":"大沢委員","kind":"確認","question":"それなりの方向性を導くために、よしとする方、それに対して違うという方の平らけく意見を聞かれているということが現状ですね。もう一回確認させてください。","respondent":"多並都市開発課長","answer":"委員のおっしゃるとおり、区としては、双方、いろいろな方のご意見ということで捉えているところです。","id":"exchange-029"},{"speaker":"田中委員","kind":"質問・要望","question":"やはりこれは地域の方たちが主体になっていないではないですかと思って、まさかそうではないですよね、というのを確認させてください。確認させてください。","respondent":"多並都市開発課長","answer":"皆さんで学んでいただいているのが今の状況という説明をさせていただいたつもりです。ただ、そういう段階というのですかね、というご理解という説明を先ほどさせていただいたところです。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"選んでいる段階ではなくて学んでいるということで、分かりました。本当に地域の方たちとともに進むまちづくりに、先ほど冒頭の説明にもあった、その地域主体でのまちづくりが進むように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"先ほど来、一緒にともにやってもいいのではないですかという話もあったけれども、議会としても我々がこの陳情に対して考え方をどうだと。協働で一緒にやっていくということであれば私はいいですが、ここでこういう趣旨で今来ているということについては賛同しかねますので、不採択。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"よって、ここにおきまして採択をすることによって一定の方向性を出すことについては、反対をいたします。よって、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"若林委員","kind":"意見","question":"品川区の活力の源であり、また、そういったものを今後ぜひ創造していってほしい。そういう意味では、Ｃ地区の皆様の意見を闘わせたり、議論をしたりという機会をしっかりと継続したほうがいいかと思った次第ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問・要望","question":"まちのよさを活かした修復型という手法で進めていくのが私たちもいいと考えていますので、これはそうした中で住民合意で進めていくということを今回も求めている陳情ですので、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"今、地域主体の方針となっていないということから、地域の事情等を踏まえた方針の見直しの要望が出されています。そして、丁寧に議論する必要があると私たちは考えていますといった、議論を求めているので、私は本当にこれは採択したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"区の意思も確認をしたわけですけれども、やはり住民サイド、今回の心配する会の方々と区が言っていることが少しずれている部分があると思うのです。今後の対応も含め、柔軟な対応と、それから、区の考え方をさらに示していただきたいとお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"その検討委員会のメンバーについて、都と区とというお話があったのですけれども、ほかにどのようなメンバーで構成されるのかというところをお知らせほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"詳細については、今後協議ということになってきますが、一般的に、東京都、区、鉄道事業者、この３者で構成されます。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問・要望","question":"今後ということだったのですけれども、この検討委員会が立ち上がった後の検討状況というのは、基本的にこれまでは公開されてきたのか、今後されるのかどうかというところとか、お知らせいただきたいと思うのですけれども。","respondent":"中道まちづくり立体化担当課長","answer":"検討委員会の公開についてですが、そちらも踏まえまして、今後調整ということになっていきます。今までの経緯につきましては、現在、把握はしてございません。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"そういう場合は、品川区から東京都に申入れをしてという形ができるのかどうか。その辺はどういう仕組みになっているのか尋ねました。","respondent":"鈴木都市計画課長、中道まちづくり立体化担当課長","answer":"そうした区の考え、東京都の計画も踏まえながら、マスタープランのほうに位置づけていくというような関係性です。 踏切対策基本方針の中に、重点踏切および重点交差予定箇所として、その中で品川区は２０個の踏切を重点的に解消していきたい。こちらのほうが、２０２５年度までに重点的に対策を実施すべき踏切という位置づけです。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"役割分担だと言われればそれまでなのですけれども、ただ、そこからの何とかしてほしいという強い思いというものをどれだけ聞いてくれるものなのか。品川区の現状をもっと伝えて、それを酌み取っていただきたいという状況なのか、その辺はいかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"品川区の全体の踏切の数については、すみません、今現在、持ち合わせてございません。話し合いを進めておりますし、現実、先ほど言っていたシステムの調整というところでも改善が見受けられているです。","id":"exchange-041"},{"speaker":"西本委員","kind":"質問","question":"見直しをある程度するという仕組みがあるのか。鉄道事業者も経費もかかることなので、その辺の調整というのは、東京都がやるのだろうかと思うのですけれども、どのようにされているのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"そのときに位置づけで、改善方法というのでしょうか、そういうのも検討しています。先ほど説明いたしました生活道路のボトルネック踏切というところで、手法をその都度、または調査した結果に基づいて柔軟に対応しています。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越公園駅のところで伺いたいのですけれども、差し引きで車が１,３３６台になるのかと思うのですが、内訳が分かれば教えてほしいと求めました。鉄道側が８５％ということになっているのですけれども、この関係性というのですか、そこのところの説明を詳しくほしいと求めました。","respondent":"中道まちづくり立体化担当課長","answer":"考え方といたしましては、こちら、１日の遮断時間が８時間になります。そういった形で、今ここに書かれているのは原則であって、また検討会の中でいろいろと柔軟に活用していくです。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"今回の一般質問でも取り上げさせていただきましたけれども、そこのところはどのように考えていらっしゃるのか、伺いたいと思います。事業効果等を検討しているということも書いてありますけれども、今の検討状況がどうなっているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"戸越公園駅付近の踏切遮断時間ですが、こちらは４０分以下というところで、区の調査等でいきますと、約３５分程度です。こちらの連続立体交差事業を実施する費用対効果であったり、高架であるのか等、今後事業化をするかしないかというのを判断していくと聞いてあります。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問","question":"車の交通量が増えてしまうということにもなりかねないと思うのですが、そこはどう考えているのか、伺います。","respondent":"中道まちづくり立体化担当課長","answer":"この踏切は、生活道路で一定程度自転車または通行者の遮断をしているというところが今該当して、連続立体交差事業を進めたいです。今、ここでは補助２９号線のお話がありますが、またそれは延焼遮断帯機能を形成するという目的のために東京都が進めている事業です。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"そうなのです。６か所が解消するということで、ぜひ進めてほしいと求めましたが、やめていただきたいということで要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"何点か教えていただきたいのですが、地元では３０年来ずっと要望してきたことであって、やっとここへ来て念願が叶う。１００か所あったら１００か所、この２年間くらい見せていただかなかったけれども、これは必須なのだというところだけ確認してほしい。","respondent":"中道まちづくり立体化担当課長","answer":"連続立体交差事業を進めていくにあたりまして、全体を事業を進める中で一つの条件といいますか、そこの要素というのは非常に今強くあります。","id":"exchange-047"},{"speaker":"石田（秀）委員","kind":"意見","question":"そうしたら、その次に、これは交通広場なのだという話になって、いきなり９割くらいの人が反対。交通広場という位置づけ、これも必須だよねということを聞いているので、そこをもう一回答弁してほしいとの意見を述べました。","respondent":"中道まちづくり立体化担当課長","answer":"今、駅前広場ではこの２つをきちんと併せ持った広場にすることです。交流機能、にぎわいを創出する機能を持った駅前広場といった形で、柔軟に説明を工夫してまいりたいと思います。","id":"exchange-048"},{"speaker":"石田（秀）委員","kind":"意見","question":"１５％の部分をプラスして、もう少し風穴は、地域と一緒になって。せっかくここは品川区の区道でもあるし、そういういろいろなことができないかと思っているのだけれども、そこら辺の点はどうお考えになるのかとの意見を述べました。","respondent":"中道まちづくり立体化担当課長","answer":"鉄道側が８５％というところで、８５％の使い方につきましても、一定程度やはり区の要望というのは言っていきたい。もちろん駅前ということになりますので、そこににぎわいを生むような施設というのは、区としても要望していきたいと考えています。","id":"exchange-049"},{"speaker":"田中委員","kind":"質問・要望","question":"確認させていただきたいのですけれども、また別のものなのかというのを確認させていただきたいというのと、駅前広場では。地域の方たちが求めているかどうかの確認でいいといったご答弁だったのかというのと、それと、どちらなのかという確認をさせてください。","respondent":"中道まちづくり立体化担当課長","answer":"区がそれをどう考えているのか、また、地域としてもそれを一定程度理解をしているのかどうかというところが東京都の判断基準の一つとしています。","id":"exchange-050"},{"speaker":"田中委員","kind":"意見","question":"区民の方が誤解しやすいといったことから交通広場にして、本当に２つの名前が出てしまうと混乱してしまうので、統一していただければうれしいです。ごめんなさい、私、理解ができていなくてとの意見を述べました。","respondent":"中道まちづくり立体化担当課長","answer":"一方で、もしかしたら交通広場といいますと、皆さんがにぎわいとかをもたらすようなただの広場というイメージは持たれないかもしれません。はにぎわいを持った、両方の機能を持たせた駅前広場とか、少し表現の仕方というのは工夫していきたいと考えています。","id":"exchange-051"},{"speaker":"西本委員","kind":"質問","question":"すみません、先ほど議案審査をした北品川駅のほうで言うと、ここは何になるのですか。だから、そういう意味は分かるのですけれども、北品川駅の例で言うと、どういうイメージをすればいいのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"駅を挟んで東側というのは、一定程度の空間ですので、今言っている都市の広場という、そういった４つの機能です。私たちも詳細に検討はしていきたいとは思うのですけれども、今、そういった交通と都市の機能２つを併せた駅前広場の事業をしていきたいです。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問・要望","question":"言い方であったり、説明の仕方であったりというのが、すごく誤解を生んでしまうような部分かなというのを私も感じました。すみません、理解力がなくて申し訳ないのですけれども、今やっと理解できた状況なので、これからもご配慮ほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"確認","question":"その中で、要配慮者と外国人への情報提供を今後どのように図っていくのかという部分を伺いたいと思います。当事者の方への聞き取りが行われていないといった答弁があったと思うので、そこの部分を確認させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":42457,"voices":156}},{"id":"r02-20201130-9","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"文教委員会","time":"午前１０時００分～午後 ５時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を117件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"区立幼稚園教諭のほうの給与水準の体系の基本的な考え方というのは何なのか、改めて伺いたいというのが１点です。それと、前回の１１月９日の委員会で報告がありましたけれども、それ以後の労使交渉の結果について、妥結したのでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"３点ご質問をいただきました。交渉のところにつきましては、１１月１９日に妥結したと情報をいただいているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"そのときに、８月１７日から９月３０日までに行った月例給の民間企業調査について、そちらのほうはどのような結果になったのでしょうか。改めて伺いたいと思います。","respondent":"工藤指導課長","answer":"すみません、引下げ改定が何年ぶりかというのが手元に資料がないところなので、回答が難しいところです。月例給につきましては、まだ必要な報告・勧告が出されていないという現状です。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"最後にお伺いしたいのですけれども、２００５年から２０１５年までの１０年間でいいますと、７％も低下しているという状況です。教育の質の低下にどうしてもつながってくる問題だと思うのですが、区教委のお考えはいかがでしょうか、伺います。","respondent":"工藤指導課長","answer":"給与等、またこういった制度に関しましては、制度にのっとって進めるというものと考えているところです。教員としての資質・能力が認められるというものですから、もちろん育成も含めながら、しっかりと進めることが必要であると認識しています。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"この引下げで、実際に平均でどのくらい下がるのかという試算はされていますでしょうか。幼稚園のほうと学校のほうと、両方を説明を求めました。","respondent":"工藤指導課長","answer":"これにつきましては、どちらも職員の平均年間給与としては、約２万円の減になるです。","id":"exchange-004"},{"speaker":"安藤委員","kind":"意見","question":"労使で妥結しているということですので、それはもちろん尊重する立場なので、あえて反対はいたしません。賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"たけうち委員","kind":"確認","question":"確認なのですけれども、１回も相手の持ち主の方から学校のほうになくて、もし分かれば説明を求めました。","respondent":"有馬庶務課長","answer":"このたび、それを管理している不動産屋が、持ち主のほうにお話をされ、今回の結果になったというのが、今のところの経過です。特に７年生が練習で最初に外に出してしまうということがあるので、もう少し校庭の中のほうで対応していこうということで、対応しています。","id":"exchange-006"},{"speaker":"たけうち委員","kind":"質問・要望","question":"分かりました。大変だと思いますけれども、注意していただきたいと要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あべ委員","kind":"質問","question":"ほかのところからは一切お話もなく、被害もなくて、この屋根だけに硬球が集中したということでしょうか。何かお分かりか尋ねました。","respondent":"有馬庶務課長","answer":"ほかは隣のマンションだったりすると、屋根が高かったりするので、そういった報告は受けておりません。先ほども申し上げましたように、シャッターが下りていた奥の駐車場ということで、そこが入って探しにくかったというところがあったです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"意見","question":"練習場所を変えられたということで、いいと思うのですけれども、その状態が分からないので、そこからまた新たにどこかに出てしまって、何か別のところに被害が行くということはないように、慎重に対応をお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"筒井委員","kind":"確認","question":"平成３０年４月から令和２年５月までの間という、事実確認というのは、どうされているのか尋ねました。","respondent":"有馬庶務課長","answer":"今の学校にいる顧問が、ボールが飛び出たことがあるというのを確認できた期間ということで、この期間ということになっております。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問・要望","question":"もっと大変なことになってしまうので、再発防止をしっかりと行っていただくよう、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"}]},{"id":"topic-02","title":"専決処分の報告について（報告第２４号）","agenda":"専決処分の報告について（報告第２４号）","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"庁有車のほうの被害額というのは、どれくらいなのか尋ねました。","respondent":"横山品川図書館長","answer":"廃車という形になりましたので、１２８万５,２００円です。","id":"exchange-012"},{"speaker":"あべ委員","kind":"質問","question":"その辺は何か役所としては、運転技術や経験みたいなものというのは勘案しつつ、庁有車というのは運転することになっているのか尋ねました。","respondent":"横山品川図書館長","answer":"運転者講習会等、研修の機会は必ず受講するように、各職場で指導しております。なかなかきつい状況で、図書館でも実質上、１人しか運転できる人はいないという形です。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"今後その辺の公平性というか、考えていらっしゃることはありますでしょうか。これは役所全体の話だと思うのですけれども。","respondent":"横山品川図書館長","answer":"なので、図書館としては、運転できる人を必ず異動の際にお願いするという形を取っています。ですが、区全体ですと、限られた人材ですので、そこを工夫しながらという形が、今のところの実態です。","id":"exchange-014"}]},{"id":"topic-03","title":"令和２年請願第１４号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願","agenda":"令和２年請願第１４号の審査でございますが、会議の運営上、予定表の順番を入れ替えまして、(3)令和２年請願第１６号、「子どもたちの安全と学びの保障」に関する請願","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"議事進行の関係なのですけれども、中途議決の関係もあって、結構項目も多いので、午前中だと中途半端になってしまうと思うので、こちらの審査なのですけれども、午後に回してもらえないかと考えていますとの意見を述べました。","respondent":"こんの委員長","answer":"時間的に、これから説明を受けて質疑に入ると、途中になってしまうと。午後の予定を考えると、１１時をめどに、こちらの会議を一旦止めするという予定でいますので、その時点で、あとは午後に回るという話になります。","id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"かなりの人数の方が署名を提出されていると思うのですけれども、傍聴の関係もありまして、午後からの予定だと考えている方も結構いらっしゃるので、そういった関係もありますので、できれば午後からに割り切って配慮してもらえるとありがたいのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"あべ委員","kind":"確認","question":"確認なのですけれども、国の基準が何時間だったか、今の時数は学年ごとに国でどのくらいの時数になっていましたか。それで、品川区の１・２年生の部分はプラス何時間になっていたか、一応、数字で確認をさせてください。","respondent":"工藤指導課長、篠田学務課長、矢部教育総合支援センター長","answer":"２年生につきましては、国が９１０時間に対して、私どもは９６０時間ということで、５０時間増です。３年生が９８０時間… 少人数学級に関しまして、３５人の効果の部分です。そういった対応が非常に取りやすくなっているということもありますので… もう一つ、スクールカウンセラーは丁寧に子どもたちに対応していまして、来ていただいた相談者については丁寧に対応できていると感じております。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"よりよい教育環境というのを品川区の教育委員会としてはどのように考えていらっしゃるかということを、もう少しお伺いできればと思います。学校や教室あるいは生徒にとって、子どもの側にとって十分かという質問をしましたので、何か課題を感じているところがあれば説明を求めました。","respondent":"篠田学務課長、齋藤教育次長、矢部教育総合支援センター長","answer":"今、委員のご指摘があったとおり、国では３０人学級という形で様々な動きがあるということは、承知しています。制度が変われば… 大体７０年以上ということで、ベビーブームの世代に対応した学校ですので、基本的には３０人学級に準ずる形で学校経営はできていると考えております。… 委員もご存じかもしれませんが、Ａさんという方が必ずしもＢ君と本当にぴったり気持ちが合うかというと、そうでない場合があります。","id":"exchange-018"},{"speaker":"あべ委員","kind":"意見","question":"むしろ後半でおっしゃっていた、４分の１の学校が４０人になっているという。では、そこをもう一回との意見を述べました。","respondent":"齋藤教育次長","answer":"１クラスでも４０人のいる学校が４分の１で、ほとんどの学校では３０人学級となっています。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"そこの姿勢の部分をお伺いしたいというのが１点です。改善の余地はないと考えているのでしょうかという思いも込めて、質問させていただきましたので、それぞれお願いします。","respondent":"篠田学務課長、矢部教育総合支援センター長","answer":"教育委員会としての学級人数に関する考え方ですけれども、基本的に、まずきちんと法にのっとった対応を取っていくのが第一だと考えております。個別の対応については、少人数での対応もできるとか… 教育相談につきましては、これから子どもたちの実態把握をしっかりと常々しながら、きちんと対応できるように体制を整えてまいります。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問","question":"それと、授業時間を多くしているというか、区自体が１・２年生については多くしているわけですけれども、その目的は何なのでしょうか。どういう状況なのかというのも日常的に把握できないですし、常にその学校でどういうことが行われているか、区の考えをお伺いします。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"午前中の段階で申し上げた私どもの教育要領上の標準授業時数を算出する上では、学校の教育課程では３５週と考えて組んでいるものです。ですから、私どもは標準授業時数を上回って… それと、先ほども区としては目安箱、生活アンケート、相談電話の窓口で対応したいです。あくまでもお子さんの実態とか社会の状況なども踏まえて、丁寧に対応していきたいという考えです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"なかなか学校でどういう教育活動が行われて、どういうところに子どもが悩んでいるかというのはつかみづらいというか、いかがでしょうか。どれぐらいあるのかというのを伺ったので、それの目的は何なのですかというのも伺ったので、説明を求めました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"３点、私どもの担当で分かる範囲でお答えいたします。上手に対応できるかというのは、委員ご指摘のとおり検討していく、引き続き進めてまいりたいと考えております。 本区で国の学習指導要領を上回っているところは、本区一貫教育の特色であります英語科、市民科などの推進に必要な時数を増やしています。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いたいのは、今年度中に、コロナで失われた１４０時間を全て取り戻す学校というのは、どれぐらい生まれているのでしょうか。それも伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"一つ一つの単元という、本当は１０時間でやらなければいけないところを９時間や８時間でやっているということで、ねらいを達成するようにしています。月一、子どもたちが慌てて授業をしていないかとか、どのくらい学校で考えて活動させているかということを把握しています。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問ですけれども、品川では実際、この辺はどうだったのかを伺いたいと思います。これは具体的にはどういう対応なのでしょうか、伺いたいと思います。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"７時間授業のほうは、半数程度と認識していますが、３学期は戻そうと考えているという声も聞いてあります。委員がおっしゃったような声もあると思いますけれども、子どもたちが少なくて寂しいとか… 私どもは個に応じた丁寧な対応をするため、さらにもう１展開ができるとかということで、少人数指導を充実させるような施策を行っているというところがあります。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問","question":"習熟度別というのはやめるべきだと私は思っています。そもそもふだんから少人数にするということとは全く違うことだと思うのですが、いかがお考えでしょうか、伺いたいと思います。","respondent":"工藤指導課長","answer":"個に応じた指導もできるような体制を取っておりますので、そういった意味では、個に応じた丁寧な授業が行えるような体制を取っているです。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回、請願を出されている「少人数学級を求める品川連絡会」さんからお手紙をいただきましたけれども、少人数学級の意義と思いが書かれていました。私は先ほどの習熟度別ですとか指導助手では、伺いたいと思います。","respondent":"矢部教育総合支援センター長","answer":"そういったデメリットもある。本区の現状としては、大人数と少人数をバランスよくやりながら、そのメリットとデメリットを見極めて進めていくというところがスタンスです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"提案","question":"ですから、伺いたいのは、今はそれが強く求められる時代になっていると思いますが。少人数学級の実施というのは、少なくともプラスになるということについては認識を共有できるのでしょうか、伺いたいと思いますとの意見を述べました。","respondent":"矢部教育総合支援センター長","answer":"重複しますが、多様性を大事にするということは、本当に私どもも重要なことだと考えています。それを皆で一緒に考えて理解するという経験も、大人数の中でもできると考えております。","id":"exchange-027"},{"speaker":"安藤委員","kind":"確認","question":"議事録を確認してもらえばと思いますけれども、一人ひとりが活躍できるという点で、少人数のメリットというのは相当大きなものがあると思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"質問・要望","question":"1)から4)の、それぞれの要望の声みたいなものが、どの程度上がっているのかというのが分かれば説明を求めました。","respondent":"工藤指導課長、篠田学務課長、矢部教育総合支援センター長","answer":"例えば英語科を１・２年生から教科として行っているところですが、あるいは児童・生徒アンケート等でも、肯定的な回答をいただいているところです。ですの… 少人数学級に関する学校からの声ですけれども、学校から、学級編制自体を小さくしてほしいという声は特段聞いていないです。… スクールカウンセラーについてですが、主に学校からの評価をこちらは受けてありますが、校長からそれの頻度については、要望は特段ございません。","id":"exchange-029"},{"speaker":"筒井委員","kind":"質問","question":"１番で、授業時数を削減してしまったら、教育効果に与える影響というのはあるのでしょうか。同じような内容の授業を受けなければいけないと思っているのですけれども、実際に削減してしまったら、どういう影響があるのか尋ねました。","respondent":"工藤指導課長","answer":"それを削減するということは、少ない時数の中で目標・ねらいを達成させなければいけないということで、そういった意味での圧迫にはなろうかと思います。","id":"exchange-030"},{"speaker":"筒井委員","kind":"質問・要望","question":"先ほど増員してほしいという声はないというのがありましたが、改めて確認ですが、十分消毒はできているということでよろしいでしょうか。人件費はどこが増員というお求めなのか分からないのですが、現状の対応で消毒は十分なのか、この２点をお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"大きな変化はないということですので、特に増員するまでのことはなく、きちんと効率よく学校の中では仕事がされていると考えております。きちんと用務の方のほうで対応できて、今のところ、増員はなくてもいけると考えているところです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"３０人学級を目指すべきだということもおっしゃられているので、実際、少人数学級を目指すということは可能なのでしょうか。なるべく現在の環境で工夫してできることはないのかなと思っているのですけれども、その辺りについて、どうお考えなのか尋ねました。","respondent":"篠田学務課長","answer":"新たに外に何らかの形で、仮設の校舎みたいなものを造るのかどうかといったことも含めて、検討していく必要はあろうかと考えているところです。できるだけ教育環境を整えながら、普通教室もきちんと充足をさせているということで、今のところ対応しているものです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"３０人学級ということになっていくのかなと思いますし、できる限り転用とか、今ある課題はぜひとも解決していっていただきたいと考えております。いきなり２０人ということなのですが、２０人学級というのは今の品川区で、やろうと思えば可能なのか尋ねました。","respondent":"篠田学務課長","answer":"これは第３回定例会のときにもご答弁申し上げたとおり、一気に１,５００ぐらいの数にするというのは、現実的には不可能であると言っても差し支えないかと思っているところです。","id":"exchange-033"},{"speaker":"芹澤副委員長","kind":"質問","question":"本日、結論を出すで、不採択でお願いします。お話がありましたとおり、実現がなかなか不可能に近いものが多くありますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"せお委員","kind":"意見","question":"本日、結論を出すで、不採択でお願いします。不可能なものもありますということで、今の品川区の現状では不可能かなということで、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"たけうち委員","kind":"確認","question":"質疑で確認させていただいたとおり、区独自でという、どこを目指しているのかがよく分からない部分もあります。そういったことで、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"安藤委員","kind":"質問","question":"少人数学級を、ここには２０人と書いていないですし、区独自にどのような少人数学級にしていくか、一歩踏み出すということが大事だと思います。その矛盾がこの中で一層浮き彫りになっているわけですから、加速しているわけですから、私は採択すべき内容だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"筒井委員","kind":"確認","question":"必要な授業数はやらなくてはいけないですし、あと、様々、先ほど答弁で確認させていただきました。それを踏まえて、今回は不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"あべ委員","kind":"質問・要望","question":"様々な心のケアの仕組みを整えてほしいと求めましたし、それから５番目のほうも、増務になっているのは確実だと思います。全体としては、現在の実施されている方向で進めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。ご答弁をお伺いしてまいりましたが、内容によって、少人数指導や習熟度別学習などを適切に実施していただきたいと私は考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"芹澤副委員長","kind":"意見","question":"少人数学級というところに関しては、自民党も国政のほうで決議を出していて、３０人というのは検討しているところであります。１学級の人数を２０人程度にすることは必須の条件と書いてあって、２０人というのは、不採択ということでお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"せお委員","kind":"質問","question":"３０人ですけれども、そこら辺は長期的なビジョンとかを持って学級編制を考えて、シミュレーションとかだけはしておいてほしいと思っています。ただ、現実、２０人というのは不可能に近いと思いますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"安藤委員","kind":"質問・要望","question":"２０人ぐらいにしないと、国が言っている「１ｍは少なくとも離れましょう」みたいなことは、実現できないわけです。私は２０人学級を展望して、少人数学級の実現を強く求める意見書を出していくということは、採択を主張したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"３０人になるかどうかというのが専らの課題で、２０人学級ということを展望といっても、物理的に現在の体制では不可能ということでもあります。少なくとも３０人学級に向けての備え、転用とか、そうした工夫をぜひ検討していっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"同じ３０人学級という目標で、地方もこれを応援しているということで、そういう形で声を上げていっていただきたいなと。３０人よりさらに減らしていくかどうかというのは、それを３０人よりさらに、それは今の議論ではないかなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"安藤委員","kind":"意見","question":"本日、こちらの陳情でも２０人程度にと書いていますので、クラスそのものを２０人ぐらいの規模にするようにしてほしいということだと理解しています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"本日、結論を出すということで、不採択でお願いいたします。７割の学級というのは既に３０人以下になっているわけですから、積極的にこの３０人学級というのをぜひ応援してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-04","title":"令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情","agenda":"令和２年陳情第５５号、学校及び保育園の給食放射性物質検査の継続・拡充を求める陳情","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"私は継続すべきだと思うのですけれども、いかがでしょうか。つかんでいらっしゃるところがあれば、伺いたいと思います。","respondent":"立木保育課長、篠田学務課長","answer":"それから他区の状況ですが、２３区の状況ですと、令和３年度実施予定は、品川区を含めまして１１区あります。令和２年度も実施は１１区ということで、今のところ把握をしているところです。他区の実施状況ということで、学校の関係で申し上げますと、令和２年度に関しましては、今の保育課と同じように１１区です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"質問・要望","question":"休止という判断はやめたほうがいいのではないですか、むしろ継続したほうがいいのではないですかという、伺ったのです。そういうのは私は不適切ではないかと思うのですけれども、むしろしっかりと継続・拡充こそ必要なのではないかと思うのですが、いかがか尋ねました。","respondent":"立木保育課長、篠田学務課長","answer":"当然教育委員会ともちゃんと連携を取って、今後細かいところは詰めさせていただきたいと考えていますが、休止という言葉を使わせていただきました。ただ、先ほども申し上げましたとおり、きちんと教育委員会とも協議した上で… 私どもも１０年間にわたって検査を続けてまいりまして、教育委員会のほうでは１件も検出されてきていないという状況があります。","id":"exchange-049"},{"speaker":"安藤委員","kind":"質問","question":"陳情に少し書いていますけれども、区としては検査するということそのものは、この風評被害を生むとお考えになっているのでしょうか。それも伺いたいと思います。","respondent":"篠田学務課長","answer":"安全なものが納入されているという前提で取り組んでいますから、基本的には検査自体が本来は必要がないものだろうという形で捉えているところです。","id":"exchange-050"},{"speaker":"安藤委員","kind":"確認","question":"品川区はそういう立場に立つべきではないと私は思いますし、むしろ今、そういうとんでもない対応こそが風評被害を生んでいると私は思います。やはりそれを防ぐためには、そういう事実をもって安全性を確認することになるし、これはしっかりと継続をしていく必要があると考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問・要望","question":"そうした業務を区内で忘れられてしまっては困るので、ぜひそうしたことは継続してやっていただきたいのです。別に専門でなくてもそういうことをし続けるという体制だけは残していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"篠田学務課長、立木保育課長","answer":"こちらの給食の放射性物質検査については、これまでも学務課の中の給食の担当がおりまして、そこが継続してやってきてあります。その関係をかなり精査をしながら対応したということもありますので… 今現在も特に放射能だけでなく、そのほかのいろいろな食中毒ですとかいったところにも十分気をつけた中で業務を行っているところです。","id":"exchange-052"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、この放射性物質についての食品検査というものは、東京都と、またさらにその食材の生産地でも検査が行われていて、そして問題がないとされているものが流通しているという理解でよろしいのか尋ねました。","respondent":"立木保育課長、篠田学務課長","answer":"生産地のほうで、きちんと自治体のほうで出荷にあたりまして検査をした上で流通しておりますので、安全なものが流通していると考えてよろしいかと思います。 食材に対する流通上の問題ですので、これはあくまでそれぞれの産地の中で間違いのないものが、国の施策の中で流通していると考えているところです。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問","question":"東京都でも検査されているということでよろしいですか。その点もお伺いしたいのですけれども。","respondent":"こんの委員長","answer":"いわゆるそういうものが、東京都も含めて検査しているものが流通されて、それを使っているのでというご説明と私たちは理解しています。ご答弁はちゃんとされたと思いますけれども。","id":"exchange-054"},{"speaker":"筒井委員","kind":"質問","question":"生産地はもちろん、生産地と東京都、両方ということか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問","question":"陳情の要旨（２）で、品川区では今まで学校給食、保育園の給食のみ検査されていたということでよろしいのでしょうか。（２）のように、１８歳未満の入所者のあるすべての施設で検査されていたということはあったのか尋ねました。","respondent":"篠田学務課長","answer":"１８歳未満の方々に対して給食を提供する施設というのが品川区内にどれだけあるかということだと思います。私どもも担当ではないものですから、細かいことは把握してございませんけれども、そういった対応は取っていないのではないかと思います。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問","question":"一旦休止というご答弁が再三あったかと思うのですけれども、先ほど福島の処理水放出の件とかがありましたが、当然状況によっては、また再び放射性物質に関する事故とかが起きた場合は、それは柔軟にやはり適宜対応、また再開ということもあり得るという理解でよろしいのか尋ねました。","respondent":"立木保育課長","answer":"一旦検証をした上で中断することになりましても、また必要に応じてそういったものにすぐに対処できるようなことは常に頭に置きながらと考えているところです。","id":"exchange-057"},{"speaker":"芹澤副委員長","kind":"質問","question":"約１０年間検査をしてきて、先ほど一定の成果というお話がありましたが、この成果というのが納入前の検査と品川区の検査に相違がない。そういったことが出てくればまた実施というのがあるのかなと思っていますが、現状の中では特に拡充をするというような必要性がないと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"せお委員","kind":"意見","question":"（１）のほうですが、あと何かあったら検査していくというお話がありましたので、そこら辺を必ず実施していただければいいかと思います。（２）のほうは、コストなども考えて現実的ではないと思いますので、不採択でお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"たけうち委員","kind":"意見","question":"ほかに１１区がやっているということなので、事業自体は継続していくというようなイメージもあると考えています。（２）については実質、また拡充ということについては難しいと考えていますので、不採択ということでお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問","question":"陳情の（２）番で、１８歳未満の入所者のあるすべての施設で検査を実施してくださいというのは困難なのかと考えております。さらに何か特段の状況に陥れば柔軟に再開ということもあり得るということを伺いましたので、以上の理由で不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問・要望","question":"今後は検査という形ではなくて、情報収集という形でこの問題に引き続きあたってほしいと求めました。何かあったらすぐにまた検査に戻せるような形でいっていただければ、そういう体制を取ってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"横山委員","kind":"質問・要望","question":"結論を出すで、不採択でお願いします。これまでの経過と今後の検査結果や情勢の変化、引き続き子どもたちの安全確保のために総合的に対応をしていっていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"}]},{"id":"topic-05","title":"議案審査に戻りまして、(6)第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"議案審査に戻りまして、(6)第６３号議案、令和２年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"その中で子ども食堂運営主体者の現状とか要望ですとか悩みですとか、区として、もしつかんだことがあれば教えてほしいと求めました。３点目は修学旅行のほうですけれども、義務教育学校の後期課程も含めて中学校１５校の中で、それぞれ何校ずつになっているのかを伺いたいと思います。","respondent":"三ッ橋子育て応援課長、吉田保育施設調整担当課長、若生保育支援課長、有馬庶務課長","answer":"例えば今、コロナ禍においてフードパントリーを実施するにあたっても、確かに消毒など非常に気をつけながら実施しているということ。… 保育園におけるコロナ対策の支援ですけれども、今までマスクやアルコール、そのほかのものを配布してきたところです。引き続き現場と確認しながら… やはり感染の今後の動向を見据えると、マスクですとか消毒液というところは、今後も引き続き必要になってくるだろうということは認識しています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"やはり本当にそのときでしか味わえないものですから、形にはまらず、また上から何か思い出はこうだと決まったものをおろすというのではなくて。区の教育委員会としても、あるいはそういうのを現場に提供してあげてほしいという思いがあるのですけれども、そこら辺はいかがか尋ねました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"修学旅行が未実施だった学校については、これまでも基本的には実施するという方向でこちらも促してまいりました。ただ安全第一ですので、そこは学校が子どもたちや保護者の考えを聞きながら決めていくところと認識しております。 それはそれぞれの学校がそれぞれ考えて、思い出づくりに取り組んでいるということもありますし、その卒業生に対して支援をしています。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問・要望","question":"中止になってしまったところについては、ぜひそういう営みというのを全面的にバックアップしてあげてほしいということは改めて要望したいと思います。最後、やはり今回のように少なくともキャンセル代等は出してあげるというのは行うべきだと思うのですが、そちらについてはいかがか尋ねました。","respondent":"矢部教育総合支援センター長、有馬庶務課長","answer":"１点目についてお答えしたいと思います。７校中、代替を考えているということで、こちらとしては日帰りとか近い距離でということでご案内をしております。 今後予定している学校、３月に無事に行けたらぜひ行っていただきたいと思いますけれども、感染状況で万が一そういうことになれば、ほかの学校と同様、キャンセル代等については公費負担をしていきたいと考えております。","id":"exchange-066"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今、それで致し方なくお弁当とかそういう部分でこの６施設が手を挙げたという理解なのか、その辺の状況が分かれば教えていただきたいのが１つです。もちろん自助・共助・公助といろいろとある中でのお考えもあるでしょうけれども、それについて、。","respondent":"三ッ橋子育て応援課長、若生保育支援課長","answer":"子ども食堂は現在区内に２４カ所ございまして、その中でフードパントリーを実施しているところが１２カ所あります。こちらで６カ所今回申請していただいたところは、すべてフードパントリーを実施しているところ… 物品等で工夫をする形を取るということで、例えば物品のほうにメッセージカードですとかシールで寄附で贈られたものというのが分かるような形で表示させていただいて、お届けするということを考えているところです。","id":"exchange-067"},{"speaker":"あべ委員","kind":"質問","question":"申請しなかったところは何でしなかったのでしょうか。なぜ６カ所だけの申請になったのかは把握されているのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"６カ所の中で、そしてその中でフードパントリー等を実施しているところであったり、内容が東京都の内容に基づいて対応しています。実際には東京都の緊急対応について子ども食堂の現状を、子ども食堂ネットワーク事務局を通じて把握したところです。","id":"exchange-068"},{"speaker":"あべ委員","kind":"質問","question":"お金が要らないというだけのことではないのではないかと思うのですけれども、そこら辺はもう少し突っ込んでいないのですか。申請したいけれども、この条件があるからできなかったところがあるとか、そういうことは把握されていますか。","respondent":"三ッ橋子育て応援課長","answer":"こちらとしても、申込みをされていないほかの子ども食堂にもきちんとネットワーク事務局を通じて何回か確認しております。内容につきましても十分ほかの補助金をもらっているところもあると思われますので、これを使わなくても対応できているのだと考えています。","id":"exchange-069"},{"speaker":"あべ委員","kind":"質問","question":"今のお話を伺っていると、２４カ所あるうちの実際に稼働しているのが１５カ所で、申請６件というのはどうも腑に落ちないのです。実はこういうのが運営では必要なのだという声が挙がってきたら、それは区としてはある程度対応を考えるということはあり得るのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"実際に第３回の募集が東京都であるのかどうかは確認しますが、今回にあたりましてはもう募集期間を終わっていると認識しておりますので、申し訳ないのですけれども無理なのではないかと考えています。","id":"exchange-070"},{"speaker":"横山委員","kind":"質問","question":"そして補助の内容についてなのですけれども、これまで現場のほうからどのような意見がありますでしょうか。補助の中ではちょっと買えないので困っているということがあるのではないかということを懸念しているのですが、そのあたり、現状を説明を求めました。","respondent":"若生保育支援課長","answer":"これが特に欲しいというようなお声は今のところ最近では届いていないところで、どちらかというとソフト面の対策等を求める声が大きいようであります。そういったお声も伺いながら、今後も感染防止対策に総合的に対応してまいりたいと考えています。","id":"exchange-071"},{"speaker":"横山委員","kind":"質問・要望","question":"そういった様々な現場との意見交換ですとか要望を吸い上げていただいているということで、例えば国や都などにそうした意見・要望をスピーディーに情報共有するなどの働きかけもお願いしたいと思うのですが、そうした情報共有の現状についてもお聞かせいただけないか尋ねました。","respondent":"若生保育支援課長","answer":"２３区の課長会ですとか待機児童対策の協議会等もありますので、そういった中で各区とも情報共有なども行っているところです。今後ともそういったところを活用しながら、適切に要望を上げていきたいと考えております。","id":"exchange-072"},{"speaker":"筒井委員","kind":"確認","question":"この感染拡大防止対策物品購入費についてなのですけれども、保育園とか幼稚園のもので、これは物品の対象を限定しているとかはあるのでしょうか。こういう品物でないといけないとか、それを確認したいのですけれども。","respondent":"若生保育支援課長","answer":"何にするかという特定に関しては、園ごとで個々に聞き取ってというのは現実的に難しい部分ですので、そこはある程度金額と見合ったものを私どものほうで選定させていただいた上でご提示するという方法で考えてあります。","id":"exchange-073"},{"speaker":"筒井委員","kind":"提案","question":"ある程度ご提案されるということなのですけれども、提案というのもぜひ行っていただきたいと考えていますが、そのあたりはどのようにお考えか尋ねました。","respondent":"若生保育支援課長","answer":"そういったご意見等々も園のほうにお伺いしながら、今のところこちらで想定しているものはあるのですけれども、ご案内いただいたようなご要望がございましたら、柔軟に対応してまいりたいと考えています。","id":"exchange-074"},{"speaker":"せお委員","kind":"質問","question":"１点だけ、先ほどの子ども食堂のあべ委員の質疑の中で申請が６カ所というのがあって、私もちょっと少ないかなと思ったのですけれども、申請が終わってしまったということで、今後に活かすためにアンケートを取ったりとか、お声を聞いたりとか、そういうことをしたりする予定はないのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今回の子ども食堂のこの補助金に関して、期間を長くて取って、なおかつネットワーク事務局とも何回もやり取りをしておりまして、各子ども食堂も十分理解した上での申請と捉えておりますので、また改めてアンケートを取ることは今のところ考えていません。","id":"exchange-075"},{"speaker":"芹澤副委員長","kind":"確認","question":"１点だけ、今のところの確認で、確かに少ないかなと。１０分の１０なので少ないと思うのですが、そもそもこの補助金が申請できないとかいうことは、条件としてあるのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"特にその子ども食堂が飲食店を経営していて、そこが補助金をもらっているからといってということは、文言については改めて言及していないところです。したがいまして、例えば飲食店が子ども食堂をしているところも、申請しているところは実際にありますので、それは大丈夫です。","id":"exchange-076"}]},{"id":"topic-06","title":"議案審査に再び戻りまして、(1)第６６号議案、品川区立保育所条例の一部を改正する条例","agenda":"議案審査に再び戻りまして、(1)第６６号議案、品川区立保育所条例の一部を改正する条例","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"なぜ民営化の直前に建替えや大規模改修行うのか、民営化との関係は何なのでしょうか、伺います。伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"民営化を進める上で、よりよい運営事業者を得られると考えまして、まずは民営化の前に工事を行っているところです。それから、事業者変更後は特に問題もなく進んでまいりまして、現在は閉園に向けた準備を進めているところです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"１歳児の入園ですとか、あるいは２歳児までしかいられない認証保育園の在園者などに、いかがでしょうか。それをカバーする方策というのは区は持っていらっしゃるのでしょうか、伺いたいと思います。","respondent":"立木保育課長","answer":"現ひろまち保育園で、今回３１名の方が優先転園の対象になりまして、２８名の方が転園をご希望されました。すみません、今回の優先転園による来年４月の入園枠への影響というのは、特に影響を出さずにここは優先転園が実施できたと捉えているところです。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"転園希望の方もそうですけれども、そもそもこの１歳児園の大きな枠が、やはり来年３月で閉園するということで様々な影響があると思うのです。あるいは３名の方は希望しないということは、この園で卒園するまで存続するべきだと、それができない理由を具体的に改めて伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"ひろまち保育園につきましては、開園当初より５年間の期間限定園ということで進めてまいりました。そのため、平成２８年から数えまして５年間になります今年度をもって、閉園することにした次第です。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのはこれができない理由で、別に今のはできない理由にならないと思うのです。仮に百歩譲ってそうだったとしても、それはやはりできない理由にはならないと思うのですけれども、もう一回お伺いします。","respondent":"吉田保育施設調整担当課長","answer":"大井町周辺の開発の関係もありますけれども、都市計画部門とともにＪＲと調整した結果、来年度以降、現在のひろまち保育園がある場所を使うことが難しいところもありましたので、今年度予定どおりの閉園ということにさせていただいてあります。","id":"exchange-080"},{"speaker":"あべ委員","kind":"確認","question":"保育園の移転のほうなのですけれども、三ツ木保育園は前も出ていたかもしれませんが、どのくらい距離があるのでしたっけ。はそこの確認をお願いします。","respondent":"吉田保育施設調整担当課長","answer":"三ツ木保育園と新しく移転する先の間の距離ということかと思います。約１km程度と考えております。","id":"exchange-081"},{"speaker":"あべ委員","kind":"質問","question":"ただ、これは今後考えてもいいのではないかと。転園ですから、マイナス１なので、いかがか尋ねました。","respondent":"立木保育課長","answer":"こちらの優先転園に関しましては、やはりいろいろと諸条件があります。通常１kmですと、なかなか一定難しいと考えておりますが、そういうのは検討しなくてはいけないとは思っています。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問・要望","question":"要望にしておきます。それともう一点、ひろまち保育園ですが、こちらの事業者は今年度以降どうなるのかということも説明を求めました。","respondent":"吉田保育施設調整担当課長","answer":"現在はＨＩＴＯＷＡキッズライフという会社が委託を請け負っております。閉園した際に、自社で本人の希望を聞きながら別の園だとか、閉園した際はそのような対応を取るものと考えております。","id":"exchange-083"},{"speaker":"あべ委員","kind":"質問","question":"となると品川区のこれまでの保育の蓄積というのが、今、単に契約が終わっても事業者がどこかで雇ってくれるよということではちょっともったいない。今後の品川区の保育に積極的に活かしていっていただくほうが、区の保育のためではないかと思うのですけれども、そうした視点はお持ちか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"確かにおっしゃるとおり、ひろまち保育園を作るときに、元品川区の職員が何人か勤めているというところもあります。今後、その辺がどうなるかは難しいところもありますが、考えてまいりたいとは思っております。","id":"exchange-084"},{"speaker":"安藤委員","kind":"意見","question":"やはりやるべきでない民営化を前提にして、改築してきれいな保育園を民間に渡していくための住所変更だということで、賛成できないと。待機児童解消にも逆行すると思いますので、反対なので、条例全体としてこれには反対という態度になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"}]},{"id":"topic-07","title":"第７５号議案、指定管理者の指定","agenda":"第７５号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"この選定委員会の有識者なのですけれども、２名というのはどのような分野のどのような肩書の方なのか、なぜその方々を選んだのかを伺います。この家庭あんしんセンターの部門を一部持っていたみたいな、その業務のすみ分けはどのような感じで変化があったのか、まとめて伺いたいと思います。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"１人の方は株式会社保育システム研究所代表の吉田正幸委員でして、こちらは品川区の子ども・子育て会議の副会長であるため選出いたしました。日本社会事業大学社会福祉学部准教授の菱沼幹男委員で… 今年度、今年度子ども家庭支援センターができまして、新規の受理から子ども家庭支援センターがすべて引き受けて対応するということにしております。","id":"exchange-086"},{"speaker":"安藤委員","kind":"質問","question":"この選定基準についても伺いたいのですけれども、ある意味、それと経費の縮減というのは矛盾があると思うのです。これを所管としてはどう両立しようと考えているのかを伺いたいと思いますし、これはなぜなのかというのを併せて伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"やはり経費の縮減については、福祉施設としては非常に難しい問題だという提言は実際にございました。３番については３０点満点、そして４番については２０点満点、合計１００点満点で審査いたしました。","id":"exchange-087"},{"speaker":"安藤委員","kind":"質問・要望","question":"これだけなのですかというか、そういった点ではどういう評価をしたのでしょう、評価しなかったのでしょうか。伺いたいと思います。","respondent":"三ッ橋子育て応援課長","answer":"すべてそうですけれども、国の基準よりも定数が、多くの人数で対応しているということが大きいと思われます。そのほかそれぞれの方が社会福祉士であるとか、実際に様々な資格や能力を持っているところはあります。","id":"exchange-088"},{"speaker":"安藤委員","kind":"質問・要望","question":"聞けばいろいろと答えていただけるのですけれども、そういったところはやはり大事な点だと思うので、ここの文面では全くそういうのが見えてこないので、またしっかりと区民に運営実態を明らかにするためにも、そこら辺はきちんと記載を今後充実・工夫していただきたいと重ねて要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-089"},{"speaker":"あべ委員","kind":"提案","question":"今回選定理由の中で提案ですとか計画といったところが書いてあるのですけれども、この資料からは全く分からないのです。これまでの事業の評価というのをどのように見ているのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"例えばモニタリング評価を実施していること、または第三者評価におきましても高い評価を得られていることが事実としています。実際にご相談であったり、また行事に呼ぶなど、切れ目のないように対応しています。","id":"exchange-090"},{"speaker":"あべ委員","kind":"質問","question":"そこはもう十分にニーズに応えているという評価の中で、再度こちらを指定管理者にしようということなのでしょうか。区としては十分だと思っているのか尋ねました。","respondent":"三ッ橋子育て応援課長","answer":"今後の令和３年からの事業計画の中においても、実際にこのようなニーズに応えていくという提案をなされているところです。それらを踏まえて、今回選定させていただきました。","id":"exchange-091"},{"speaker":"あべ委員","kind":"質問・要望","question":"今、あんしんセンターなり子育て支援に求められていることは上下しているのではなくて、それを踏まえてご答弁をほしいと求めました。これは前回の５年間と金額的には、数字が出せれば数字を出していただければと思うのですが、どのくらいになりそうなのか尋ねました。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"ニーズにつきましては、それに対応していけるように、この指定管理者候補者に対して求めていこうと考えています。指定管理料ですけれども、来年度以降もそれほど変わりはないと捉えております。今年度子ども家庭支援センターができまして、虐待相談・養育困難の相談についての一元化を図ったところです。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこをしっかりと精査して、必要なものは予算をつける、必要でないものについては見直すということをやってほしいと求めました。今後あんしんセンターでは、本年度と来年度以降、次の指定管理では子育て支援センター部分に関わる人数というのは変更があるのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"令和３年度からの基本計画書の案をいただいているところなのですけれども、そこでも子育て支援センターの人員については今年度よりも減ということでいただいておりまして、来年度予算についてはご提案させていただきたいと考えています。","id":"exchange-093"},{"speaker":"あべ委員","kind":"意見","question":"それは確かに経営基盤が良好になると思うのです。そういうことではなくて、しっかりと運営の面での健全性というのを図ってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-094"},{"speaker":"横山委員","kind":"提案","question":"こちらはこれまではどういった機関と連携をしてきたのかを教えてください。今回また何か新たに提案があるようでしたら、どのようなアフターケアの提案があったのかというところと、具体的な現状について説明を求めました。","respondent":"三ッ橋子育て応援課長、崎村子ども家庭支援センター長","answer":"退所後の関係機関につきましては、子育て応援課であったり、子ども家庭支援センターであったり、こちらが関係機関と捉えております。先ほど申し上げましたように… 子ども家庭支援センターとの連携という部分なのですけれども、我々が対応するといったことはできておりますし、対応ができるようにしております。委員ご指摘のように、漏れのないように対応してまいりたいと考えております。","id":"exchange-095"},{"speaker":"横山委員","kind":"提案","question":"アフターケアの新たな提案というのは、今回なかったということなのでしょうか。人材育成の部分について、ご答弁をお願いできたらと思いますとの意見を述べました。","respondent":"三ッ橋子育て応援課長","answer":"アフターケアの新たな部分ですが、同様と捉えております。人材育成に関しましては、そちらに関しましても研修をしっかりとすること、また質の高いサービス提供ができるようにしていくことと捉えております。","id":"exchange-096"},{"speaker":"横山委員","kind":"質問・要望","question":"引き続き、ぜひしっかりとそのあたりも連携をしていただきながら、情報共有などもしていただきながら進めていただきたいと考えております。こちらのひまわり荘ですとか、共有したりということもぜひ進めていただきたいと思っていますので、要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"ただ、虐待死などは１歳未満が大多数なのですね。その指定管理が代わるタイミングでも、これをもう少し広げられるようにぜひ法人と話をしてほしいのですが、いかがか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"そういった虐待予防の観点から、ショートステイの拡充については現在も検討しているところなのですけれども、お話をいただいているところです。","id":"exchange-098"},{"speaker":"あべ委員","kind":"意見","question":"賛成ではありますけれども、長年同じところに指定管理をさせていることが影響しているのかどうか、やはりより改善をしていく、それから委託費用などのお金の面についてもきっちりと積算が外に出せるような形でしていくということ、もう一度この機会に見直しながらやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-099"}]},{"id":"topic-08","title":"第７６号議案、指定管理者の指定","agenda":"第７６号議案、指定管理者の指定","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"こちらについてもかなり簡素な資料なので、同様に有識者２名はどのような分野のどのような肩書の方なのでしょうか。引き続き安定的に提供できる提案とありますけれども、具体的にはどのような提案であるのかというのを伺いたいというのが２つ目ですとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"ＮＰＯ子育て品川の理事会のほうでも、このままではＮＰＯは認定こども園になれないため、発展的なところは今の状態では見込めない。そのため今回の指定管理期間が３年間というのは、当初決めた残りの残有期間と認識しています。","id":"exchange-100"},{"speaker":"安藤委員","kind":"提案","question":"ちょっと理解できないところがあるのですけれども、私が先ほど伺ったのは、選定理由の（１）というよりも（５）のほうを伺ったのです。これは要するに保育士が引き継がれますよという提案のことなのか、この７の（５）はどのような提案がなされたのかというのを伺ったのでとの意見を述べました。","respondent":"吉田保育施設調整担当課長","answer":"１６年間ここで培ってきたというのは、区として国に先駆けて保育と幼稚園を連続させて一体化した仕組みを作ったことです。それから運営母体を福栄会のほうでこの内容をそのまま引き続き継続させるという事業提案がございましたので、その内容を判断したところでもあります。","id":"exchange-101"},{"speaker":"あべ委員","kind":"質問","question":"先日もちょっと詳しくお話を伺って、こういうところに行ったのかなと思うのですが、そもそも論として。指定管理でそういうことをしていいのかという思いはなかったのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーる西五反田におけるこれまで１６年間培ってきた乳幼児教育について、引き続き提供できる社会福祉法人というのを望まれたところです。その点から、特にその福栄会に替わったことによって質が悪くなるだとか、今までより悪くなるということは想定はしていないところです。","id":"exchange-102"},{"speaker":"あべ委員","kind":"質問","question":"母体がそっくり法人に入るということなので、その母体というのは何ですか。母体というのは通常組織を指す言葉だと思いますけれども、どういう組織がＮＰＯから法人に内包されることになるのか尋ねました。","respondent":"吉田保育施設調整担当課長","answer":"ご説明が雑駁で申し訳ございませんでした。ＮＰＯ側の理事ですけれども、一部の理事等を含めて福栄会のほうに吸収、移行するというような形になります。","id":"exchange-103"},{"speaker":"あべ委員","kind":"質問","question":"ＮＰＯの理事も福栄会の理事に入るということなのですか。指定管理者制度とその事業者の変更という意味で、それが妥当なのかどうかというのは、お話を伺っていて余計にちょっと不明瞭になってきました。","respondent":"吉田保育施設調整担当課長","answer":"ぷりすくーるを運営をするために、ぷりすくーる運営委員会というものを新たに福栄会のほうで立ち上げます。そちらの委員になるというところが、全員ではありませんが、ＮＰＯ側の一部の理事の参加する場所となります。","id":"exchange-104"},{"speaker":"あべ委員","kind":"質問・要望","question":"これもまたイレギュラーでなかなか似たようなことが今後起こるかどうか、１つには、これを前例にしてほしくないというのが一つあります。そうした話は出ているのか尋ねました。","respondent":"柏原子ども未来部長","answer":"今のＮＰＯに指定をしたのですが、社会福祉法人化というところにはまだ課題が残っていましたので、それをずっと検討していたというところがあります。","id":"exchange-105"},{"speaker":"あべ委員","kind":"質問・要望","question":"いろいろと課題があると思いますが、賛成はいたします。ただ、この指定管理の持つ制度的な危うさというのをぜひ前例にはしないでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-106"}]},{"id":"topic-09","title":"令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","agenda":"令和２年請願第１４号、品川区私立幼稚園保護者負担教育費の軽減に関する請願","exchanges":[{"speaker":"たけうち委員","kind":"意見","question":"幼児教育・保育の無償化ということなので、この保育料についての負担というのは、もうほぼないと思っていいのかどうか。その２点をお願いしますとの意見を述べました。","respondent":"若生保育支援課長","answer":"国のほうでの無償化の給付に関しましては、これは完全な無償化というわけではなく、制度上は一律２万５,７００円を上限とした給付になってあります。","id":"exchange-107"},{"speaker":"たけうち委員","kind":"意見","question":"ほぼ７割が負担なしということで大変よくなって、また品川区もこの間、本当に数年単位で拡充を図ってこられていることに大変敬意を表するところです。","respondent":"若生保育支援課長","answer":"これまでも様々な補助メニューを拡大してまいりましたけれども、今後の私立幼稚園のほうの教育の振興に資するために、様々な支援を検討してまいりたいと考えております。","id":"exchange-108"},{"speaker":"あべ委員","kind":"質問","question":"昨年の幼児教育の無償化以降、全国では保育料の値上げをした園がかなり目立つわけですけれども、品川区内では把握をされていますか尋ねました。","respondent":"若生保育支援課長","answer":"無償化に伴っていろいろと便乗値上げみたいなところで報道がなされて、昨年度については保育料を値上げしたというところは聞いてございません。","id":"exchange-109"},{"speaker":"あべ委員","kind":"意見","question":"無償化の影響もあって、保護者負担は以前に比べればかなり軽減されてきたかなと思います。あるいは特別支援にかけるサービスの充実ですとか、そうした形でのお金の使い方というのもバランスを持って進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-110"},{"speaker":"安藤委員","kind":"質問","question":"私立幼稚園保護者教職員連合会の活動について、区はどのように把握しているのかを伺いたいと思います。保護者と教職員との連携・交流というのは、よりよい幼稚園環境を作る上でも大切なことだと思いますけれども、いかがか尋ねました。","respondent":"若生保育支援課長","answer":"保護者・教職員相互の連携を図ったりしながら、各園の教育と相まってそういった教育の下支えをしているということで、区としても認識しております。","id":"exchange-111"},{"speaker":"安藤委員","kind":"質問","question":"保育の質を保つ上で大切な役割を果たしていたと伺っていますけれども、昨今、やはり非常に弱くなっているなと感じています。保護者と従事者との交流はもっと自由に活発に行えるようにしたほうが子どものためにもよいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-112"},{"speaker":"横山委員","kind":"確認","question":"現在の私立幼稚園を取り巻く社会情勢、そういった現場の状況というあたりを、区としては具体的にどのように把握をしておりますでしょうか、確認させてください。","respondent":"若生保育支援課長","answer":"私立幼稚園協会の会長とはかなり頻繁にやり取りをさせていただいて、その中から課題ですとか状況をお伺いする機会はよくあるところです。","id":"exchange-113"},{"speaker":"横山委員","kind":"質問・要望","question":"保護者の方々の要望というのも、様々個別であったり高い要望もあるような現状があると捉えております。保護者の方の様々な思いですとか、引き続き誠実な対応をお願いしたいと思いますので、こちらは強く要望させてほしいと求めました。","respondent":"若生保育支援課長","answer":"今後、私立幼稚園との関わりというところも、区としても今検討しなくてはならない段階に来ているかなというところは非常に認識しています。ニーズ等をどうくみ上げていくかというところは、ご意見を伺いながら検討してまいりたいと考えています。","id":"exchange-114"},{"speaker":"せお委員","kind":"質問・要望","question":"私立幼稚園しか選択肢がない方もいらっしゃいますので、そういった方にも重要かと思っています。区で調査、把握していただいて、指導などはしていってほしいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"筒井委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いします。公私の教育費格差の解消に向けて進めていっていただきたいと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-116"},{"speaker":"あべ委員","kind":"質問・要望","question":"子育てに関する広範な費用の軽減を進めてほしいと求めました。この件も、そしてその他のことについても区として指導してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-117"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5018#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":81736,"voices":382}},{"id":"r02-20201130-5","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"総務委員会","time":"午前１０時００分～午後 ２時０１分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"勤務条件に関する条例の一部を改正する条例、(8)第９５号議案、職員の給与に関する条例の一部を改正する条例、および(9)第９６号議案…","agenda":"勤務条件に関する条例の一部を改正する条例、(8)第９５号議案、職員の給与に関する条例の一部を改正する条例、および(9)第９６号議案…","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"１１月１９日に労使交渉があったというご説明がありましたが、どんな確認といいますか、その内容をご説明ほしいと求めました。第９３、品川区特別職報酬等審議会ではどんな意見やどんな議論がされたのかお伺いしたいのと、そこのご説明ほしいと求めました。","respondent":"黒田人事課長、立川総務課長","answer":"再任用職員の引下げの月数が０.０５月というところで、そういったところについて、労使でやり取りがあったというふうに伺っています。妥結のところでは、妥結を得たというふうに伺っておりますので… 特別区の人事委員会等の意見を尊重して、おおむね連動するような形でこれまでどおり実施したほうがよろしいのではないか。厳しい財政運営が見込まれるので、効率的な区政運営を行ってもらいたい、そういったご意見がございました。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"第９３号議案、第９４号議案のほうでもう一度伺いたいのですけれども、コロナによる経済への影響が出始めたときと言ったほうがいいんでしょうか。つまりはもっとボーナスをカットすると、そういう判断というのはされなかったのか、そのことについて伺いたいと思います。","respondent":"立川総務課長","answer":"特別職の報酬等につきましては、まず第１点が、特別区人事委員会等の勧告、職員の給与の状況というものはどういうものかということがまず第１点です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"そこは見ながらも、特別職についてはさらにボーナスをカットしていくという区政運営が、区民からも理解されるのかなというふうに思います。今回下げるという内容ですから、さらに厳しい判断というのが必要ではないかなと、意見だけ述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、今のご答弁の中で、品川区特別職報酬等審議会では、特別職は下げなくてもいいのではないかというご意見だけでしたけど、それはどういうふうな理由でそういうふうな意見が出たのか分かれば教えていただきたいのです。","respondent":"立川総務課長","answer":"先ほど、品川区特別職報酬等審議会の意見の主なものにつきましてお話をさせていただいたところですが、理由等につきましては、原則この審議会における議論の内容は非公開ですので、そこまでの答弁は控えします。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問","question":"今、中塚委員がおっしゃったように、一般職員の方たちはともかく特別職とか議員についてはもう少し下げるべきではないのかという考えです。品川区の公務員であり品川区の中の特別職であり議員なわけですから、審議されてもよかったのではないかなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"お聞きしたいのは、声明とかそういうものをきちんと申し伝えるところ、そういう手法というのはあるのでしょうか。そして、今現在、人事課長もご存じのとおり、世相は大変厳しい状況になっていますが、それに対してどのようにお考えか尋ねました。","respondent":"黒田人事課長","answer":"一定程度の考え方について、これまでの勧告の中でも出しているものはありますけれども、基本的には人事委員会は法で定められた第三者機関であるです。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"全く現在の社会、実社会、経済を見ていないということは非常に残念です。これから、特別区人事委員会が何かいろいろ改革していっていただいて、もっと国民に分かりやすい身近な勧告を出してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"そんな中、所管として、特に若手の職員に対して仕事への意欲をどういうふうに継続というか、やっていかれるのか。もし所管のほうで何かお考えになっているようなことあれば、何か教えてほしいと求めました。","respondent":"黒田人事課長","answer":"先ほどのご指摘あった、その直接に窓口等で対応する職員についてはそういった厳しさも感じているところだと思いますので、いかに区の職員として区民のために働くかというところの意識醸成を今後も図っていきたいというふうに思ってあります。","id":"exchange-008"},{"speaker":"中塚委員","kind":"意見","question":"第９３号議案について、先ほども意見述べさせていただきましたが、条例自体はボーナスを下げるという内容でありますので、反対をするものではありませんが、やはり厳しい社会情勢の中、さらなるカットというのが率直に必要だと意見を述べさせていただいて、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"吉田委員","kind":"意見","question":"今お二人がおっしゃったのと同じように、ちょっとこの内容についてはある意味、こういう内容ではいけないのではないかというふうに考えました。しかし、下げるということについては反対するものではありませんので、賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"中塚委員","kind":"意見","question":"第９４号議案、教育長の給与等についてですが、第９３号議案と同じくやはり下げるという内容の条例でありますので、反対するものではありませんが、今の社会情勢を踏まえて、さらに厳しく下げるべきだという意見を述べまして、賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"第９５号議案ですけれども、労使間の妥結を尊重して賛成したいと思いますが、交渉の中で論点となったこと、検討されるべきことは誠実に今後とも話合いを進めていただきたいと述べまして、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"吉田委員","kind":"意見","question":"民間企業とか、大変厳しい方も多い中では、もう少し下げ幅については考慮があってもよかったのではないかなというふうに思います。ただ、この下げるということについては賛成をいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"},{"speaker":"中塚委員","kind":"意見","question":"第９６号議案の会計年度任用職員の給与および費用弁償に関する条例の一部を改正する条例ですけれども、労使間の合意を尊重したいと思いますが、ここはやはり、もともとの月数が少ないということはしっかり踏まえていかないといけないと意見を述べさせていただきまして、賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"須貝委員","kind":"意見","question":"もともと任用職員の給与等は確かに少ないので、私としてもちょっと悩むところはあるのですが、ただ、民間では、もう本当にゼロということで職を失っている方のことも考えますと、下げ幅については納得できないところはありますが、下げるということで賛成しますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"吉田委員","kind":"意見","question":"第９６号議案については、そもそも会計年度任用職員という立場がそう強いものではない中で、こういうことがあるというのは、本当にここはちょっと心が痛むのですけれども、でも公務員ということでやはりこれは下げるということについては、賛成したいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"}]},{"id":"topic-02","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会に関わる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"２６日の最後の高橋しんじ議員の１番目の質問、監査の見解を、２つお聞きになったと思うのです。本来使うべきではないお金を使ったということについての見解が、それについての見解が、改めて伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-03","title":"称）品川区立環境学習交流施設新築工事請負契約、(2)第６９号議案、（仮称）品川区立環境学習交流施設新築機械設備工事請負契約、(3)第７０号議案…","agenda":"称）品川区立環境学習交流施設新築工事請負契約、(2)第６９号議案、（仮称）品川区立環境学習交流施設新築機械設備工事請負契約、(3)第７０号議案…","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"ただ、この間、説明会が行われ、戸越公園内につくるということに対して、様々意見があるというふうに伺っております。質問ですけれども、まず地元理解は得られているのかということと、その反対意見の主な理由は何か、伺いたいと思います。","respondent":"提坂環境課長","answer":"建設委員会でもご説明は続けてまいったところですけれども、その設置場所と同じく、戸越公園内に設置するという経過です。それからソフト面でも騒音を出さないようなプログラム等を検討するということで、対応させていただきたいと考えています。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"説明会の状況をご報告していただきましたが、私が伺ったのは、地元の理解が得られているのかということです。引き続き理解を得られるよう丁寧な対応をしていく必要が、私はあるのではないかと思っているのですけれども、改めていかがか尋ねました。","respondent":"提坂環境課長","answer":"昨年の９月に説明会を行い、今年の５月にも小学校の体育館をお借りして説明会を行う予定だったのですけれども、やむなく書面とし。１２月に工事説明会を予定していますけれど、それ以外のご質問についても真摯に対応しますし、個別のご質問等についても真摯に対応する所存です。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ、疑問や意見に対しては丁寧に説明をしてほしいと求めましたし、１回限りで終わりとか、そういうような態度ではなく、継続対応しているというお話ですけれども、ぜひとも丁寧に説明のほうは尽くしていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問・要望","question":"私も昨年９月の説明会に参加させていただいたのですが、大変なご意見でしたよね。その後出たご意見で、藤棚のこと以外に、反映させられるものがあったら教えてほしいと求めました。","respondent":"提坂環境課長","answer":"例えば施設の中の１階にキッズスペースというものを設置するのですけれども、保育園、そういうことの検討を進めてあります。遊具に変更があったということで、魅力ある施設づくりを引き続き検討して、計画を進めてまいりたいと思います。","id":"exchange-021"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、周辺の方たちの今までのイメージを損なわないような形で、ご相談しながら進めていっていただきたいというのが１つ。雨水利用設備がどれくらい、何にどういうふうに利用されていくものなのか、ざっとで結構なので伺いたいのですがいかがか尋ねました。","respondent":"小林施設整備課長","answer":"これは計画の段階から進めているところですが、設計の最中にボーリング調査等を行いまして、設計の中に盛り込んで実施していくものです。この水につきましては、トイレの洗浄水として使用することで今、計画のほう進めてあります。","id":"exchange-022"},{"speaker":"吉田委員","kind":"質問","question":"それらのことで、基本的には建物に使うエネルギーを賄えるものなのでしょうか。それとも、そこまではいかない、一部利用みたいな感じなのか尋ねました。","respondent":"小林施設整備課長","answer":"省エネという観点でいきますと、従来の建物、今基準となる建物に比べて５０％以上削減できる計画となっております。それと、つくるほうにつきましては、正味７５％から８０％程度の省エネになるかというふうに思っているところです。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問・要望","question":"やはりそういったことが、この建物の意義というのも丁寧に説明しながら、工事を進めていっていただきたいというふうに思います。これは意見にしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"この事業については、そして予算も流れてきているから区でもこの事業を、施設を造ろうということになったのですか。ちょっとその基本的なことだけ説明を求めました。","respondent":"提坂環境課長","answer":"もう１点は、区でもアンケートを実施してございまして、地球規模の課題であまりにも大き過ぎて身近に感じられずに漠然としてしまう。それから予算的なものについては、ＺＥＢの補助金を一部いただく予定ですけれど、それ以外は区の自主財源を今のところ予定しています。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問・要望","question":"どうして急にここまでやるというのは、きちんと区民一人ひとりが身をもって理解して、そして体験する。何とも言えないですけれど、教育委員会並びに様々な分野の所管と一緒になって、よりいいものをつくってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"吉田委員","kind":"質問","question":"蓄電池の設備があったと思うのですが、どれくらいか、確かここはいざ災害となったときのため防災機能を備えるのではなかったでしたか。ここに人が集まったときに、例えばここで蓄電されたものを提供できるのか、またそういう機能というのはどうなっているのか伺いたい。","respondent":"小林施設整備課長、提坂環境課長","answer":"私のほうから先に、蓄電池のハード面のお話についてご説明いたします。先ほどの太陽光と同じですが、いわゆる一般世帯の大体６世帯分の容量が賄える規模かと思ってあります。 戸越公園そのものは広域避難場所に指定されているということと、あと、周辺の戸越小学校なども避難所に指定されております。詳細についてはこれから防災課等とも連携して、調整を進めてまいりたいと考えています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません、分かりました。今後運営、これは運営になるのかもしれませんけれど、考えていってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"質問","question":"今、ちょっと細かい質問になってしまうのですけれど、寄附した方が品川区に福祉施設を造ってほしいという思いで寄附された土地なんですね。その移動した事務所はどれくらいの時期になったら解体されるとか、どこかへ移動すると、そういう計画というのはあるのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"今、この環境学習交流施設でそういったリサイクルが生まれて、品川のリサイクルの中心になるような施設になっていただければと思っています。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"}]},{"id":"topic-04","title":"第７１号議案、第二戸越幹線整備工事（下流部シールド）請負契約","agenda":"第７１号議案、第二戸越幹線整備工事（下流部シールド）請負契約","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"平成２９年度から始まったこの第二戸越幹線整備工事ですけれども、全体の計画を改めて伺いたいと思います。住宅にかかる部分は見た感じなのですけれども、道路のみで住宅にかかる部分はないということでよいのか、そこだけご説明ほしいと求めました。","respondent":"松本河川下水道課長","answer":"今回、取水工という工種において、Ｎｏ.３とＮｏ.４をやる予定です。取水工のＮｏ.１とあとＮｏ.２が残ってありますので、その工事発注を今後していく予定です。","id":"exchange-031"},{"speaker":"須貝委員","kind":"質問","question":"それに対して、もしかしてということで、例えば今後その調べられるとか、調査をするとか、そういうことは考えられているのでしょうか。今、品川区の地下を相当、掘って工事をしていますけれど、どのようにお考えか尋ねました。","respondent":"松本河川下水道課長","answer":"調布市で陥没事故があったことということにつきましては、私たちも認識しています。この工事を進めるにあたっては、あと、道路の状況はもちろん確認をしていくということは考えてあります。","id":"exchange-032"},{"speaker":"須貝委員","kind":"確認","question":"その辺について、いや、絶対これは安全なんだというふうに、我々、例えば区民に聞かれたときに、断言していいのでしょうか。そして、もう一度聞きますけれど、今までやったところ付近の空洞調査は、しなくていいのか尋ねました。","respondent":"松本河川下水道課長","answer":"お話にありました、基本的には通過した後につきましても、引き続き半年程度はしっかり道路の形状を見ていくということは考えてあります。その後ということにつきましては、道路管理者のほうで適切に管理をしていくということになろうかと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問","question":"そんな高地ではないのですから、非常にちょっと恐怖を抱いたものですから、それはまずいですか。どうか尋ねました。","respondent":"松本河川下水道課長","answer":"工事に絶対安全というものはなかなかないのかというふうに思ってあります。ですが、品川区内の私たちが今までやってきた事業の中では、そういった大きな事故があったということはあまり聞いてございません。","id":"exchange-034"},{"speaker":"須貝委員","kind":"質問・要望","question":"最後に、区民の財産と命を守るということがやはり基本ですから、何かありましたら、そこは早急に対応、また対策をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"}]},{"id":"topic-05","title":"第７２号議案、第二戸越幹線整備工事（上流部シールド）請負契約の変更","agenda":"第７２号議案、第二戸越幹線整備工事（上流部シールド）請負契約の変更","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"変更の内容の（５）の現地精査に伴う家屋調査の件数増とあるのですけれども、この、いわゆる地下を掘るシールド工で地上の家屋の調査の増とは、ちょっとよく分からないので、ここだけ具体的に説明いただけますか尋ねました。","respondent":"松本河川下水道課長","answer":"こちらは、今回上流部シールド工事を行うにあたって、トンネルから約４５度の範囲を家屋調査というものを実施しています。設計段階では６６０棟と見込んでいたのですが、現地の精査の結果、７１７棟あったということで、増額をさせていただいているところです。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"道路管理者の指示による舗装復旧面積の増工ですか、これは、現場での指示によって変わってきたということなのでしょうか。もうちょっと説明していただけるとありがたいのですが、いかがか尋ねました。","respondent":"松本河川下水道課長","answer":"１番の管きょ工の立坑位置の変更に伴うですが、既に今年の６月にもう完了いたしました、下水道本管整備工事というものの立坑工事がございました。２番目の、防音ハウスを設置するにあたって、現場での精査を踏まえ防音ハウスの出入口の配置や屋根の高さの形状を変更したものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"２番なんかはやはり、やはりやってみないと分からないということなのでしょうか。契約金額を決めるときだと、こういうことは、そうせざるを得ないものなのかどうなのかを改めて伺いたいのですがいかがか尋ねました。","respondent":"松本河川下水道課長","answer":"防音ハウスの形状につきましては、近隣の状況を踏まえまして、やはり形状を変えないとご迷惑がかかるということが判明いたしましたので、変更しています。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":26837,"voices":150}},{"id":"r02-20201130-10","meetingId":"r02-cm11","date":"2020年11月30日","dateIso":"2020-11-30","committee":"議会運営委員会","time":"午後 ０時４５分～午後 ０時４８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/101132?Template=document&Id=5386#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1163,"voices":8}},{"id":"r02-20201201-6","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"区民委員会","time":"午前１０時００分～午後 ０時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を55件整理しています。","topics":[{"id":"topic-01","title":"「品川区スポーツ推進計画（素案）」およびパブリックコメントの実施","agenda":"「品川区スポーツ推進計画（素案）」およびパブリックコメントの実施","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"パブリックコメントの実施についてという資料の「これまでの経緯」のところで、学識経験者、区内関係団体代表者等々、それぞれあるのですけれども、それぞれが何人で、全体が何人だったのかというのを教えていただきたいのと、学識経験者の方はどういう方なのかということを説明を求めました。","respondent":"中元スポーツ推進課長","answer":"公募委員は４名公募がございまして、その中からもともと２名という枠でございましたので、２名の方にお願いさせていただきました。品川区職員としまして、文化スポーツ振興部長と教育委員会事務局教育次長という構成でやらせていただいているものです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"これは、区民委員会にも報告があったのでしょうか。ここら辺の状況を伺いたいと思います。","respondent":"中元スポーツ推進課長","answer":"有効回答率が３９.３％で、郵送のアンケートにしては大変高い回答率を頂けたところです。それと、先ほどの児童・生徒向け調査の回答率は、有効回答率９６.１％でございました。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"提案","question":"それで、共産党としては、スポーツが権利であるということを冒頭に入れるべきではないかということをずっと提案させていただいていたのです。その下で、このような計画を作っていくという計画にしていただきたいなと思っているのですが、そこはいかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"実際には素案の４ページをご覧いただきますと、そのような権利を守っていこうということで、趣旨では提案されているところです。今後、パブリックコメント等でそのようなご意見が出たときに、策定委員会でも審議をしていただくところです。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"２４ページにアンケート等の声を聞き取られた状況も出ているのですけれども、私も障害者スポーツ推進計画を作るべきだということを求めてきたのです。障害の種別等々で本当に一人ひとり違いますので、そういったところを酌み取った推進計画を改めてお願いしたいのですが、いかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"総合的なものは、障害者のスポーツのことに関しましても、一緒にこの中で考えていきましょうという形で委員会の中では検討が進んでまいりました。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういう計画の中にも、そうした場の提供ということで、５９ページの場の充実。品川区はこのように求めてくれているのだなということも分かる形にしていただくと、より一層いいかなと思ったのですが、そこら辺はいかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"まず、地域の中でやれる機会や実施できる機会をなるべく取り組んでいきましょうという方向性で、地域スポーツクラブでもやっていただいてあります。確かに特化した部分も必要性はありますので、今後の課題として受け止めているところです。","id":"exchange-005"},{"speaker":"松本委員","kind":"意見","question":"書面で開催するとなると、どうしても議論がどこまでできたのかなというところがあると思います。その中を見ると、新型コロナという文言は出てくるのですけれども、それがどのくらい具体的に議論できていたのかなという検討状況をお願いいたしますとの意見を述べました。","respondent":"中元スポーツ推進課長","answer":"１０月２９日に何とか広い会議室で集まりましたところ、ご意見が大変たくさん出てまいりまして、やはり対面でやる大切さを感じたところです。致し方なく書面やウェブでやった回もありますが、なるべく最後のところは対面でまとめたいなと考えているところです。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問","question":"具体的な施策がコロナとの関係でどう反映されているかなというところでいくと、基本目標の４、７５ページで書いていただいているのかなと思います。計画の段階なので、どういった方向性というか、今のところのイメージがあれば教えていただければなと思います。","respondent":"中元スポーツ推進課長","answer":"実は、東京都や国でスポーツの専門サイトを既に立ち上げているのです。税金が二重投資にならないように、なるべく無駄なことはしないように、重ならないように工夫して取り組んでいきたいと考えているところです。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問","question":"長期的な観点で考えていくべきかなと思っていますので、児童生徒のスポーツというと、典型的には部活動が想定されると思います。あるいは方向性も考えていったほうがいいのかなと思うのですけれども、そういったものの検討は何かあったのか、お伺いできればと思います。","respondent":"中元スポーツ推進課長","answer":"文部科学省で、たしか来年度にモデル実施ということで、いろいろな権限を事業としてモデル実施されるということはあったのです。教育委員会といろいろ連絡を取り合いながら検討していく事項だなということは、課長としては考えてあります。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"今回、スポーツ推進計画ですから、この中にスポーツという言葉がたくさん出てくるのは当たり前というか、出てきます。行政が考えているスポーツというのは、どのようなことか尋ねました。","respondent":"中元スポーツ推進課長","answer":"概要の中で説明が不足してございまして、冊子の１３ページを参考にご覧いただければと思います。実はスポーツ実施率何％という指標は、正しい比較ができませんので、国や都の考え方に倣って規定させていただきました。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問・要望","question":"指導を受けなくても、お日様に当たればビタミンＤができるというお話も聞きますし、歩くことによって骨粗鬆症の予防ということも伺っているのです。確認です。","respondent":"中元スポーツ推進課長","answer":"委員ご指摘のとおり、意図的に体を動かした方も入るということで、アンケートのお問い合わせのところに書いてあります。","id":"exchange-010"},{"speaker":"藤原委員","kind":"質問","question":"せっかくこの推進計画ができていくわけですから、今から具体的にどういう形かということを考えていかないといけないと思うのが１点です。その辺について、大きく２点伺ったと思うのですけれども、いかがか尋ねました。","respondent":"中元スポーツ推進課長","answer":"素案の５７ページに「高齢者のスポーツの推進」ということで、６５歳以上の高齢者の方に向けての介護予防的な視点、様々な課がそれぞれ取り組む。","id":"exchange-011"},{"speaker":"藤原委員","kind":"質問・要望","question":"そうしてほしいという要望をこの委員会で要望しようと思ったのですけれども、さすがです。間違いなく来るわけですから、その辺においてもうまく庁舎内で、もちろんお子様たちも、成人の皆様も大事ですけれども、高齢者。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"くにば委員","kind":"質問・要望","question":"大枠の部分でお伺いしたいのが、週１回のスポーツ実施率の部分なのですけれども、例えば自分の例に当てはめてみますと、いわゆる子育て世代。これは、あたかもスポーツをやろうと思っているけれども、実施しない理由ではないか尋ねました。","respondent":"中元スポーツ推進課長","answer":"文化的な興味がある方でしたら、これから委員の様々なご意見があったことを検討会にお伝えさせていただいて、貴重なご意見だったかと思います。今後も引き続き、様々検討してまいりたいと思います。","id":"exchange-013"},{"speaker":"くにば委員","kind":"質問","question":"そこの部分にかけて、もう一つ伺おうと思っていた部分なのですけれども、見るスポーツの部分です。ウエートを割くつもりなのかを伺いたいのです。","respondent":"中元スポーツ推進課長","answer":"現在、どうしても記載のところは少ないかなです。まさに今後の課題として捉えているところです。","id":"exchange-014"},{"speaker":"大倉委員","kind":"質問・要望","question":"これに沿って多面的にいろいろ捉えられて進めていっていただきたいのですけれども、やはり施設が１つ大きなポイントになってくると思うのです。こうした中での施設のキャパシティも考えて、今後どうしていくかという検討が何かされているかどうかというのをお聞かせいただきたい。","respondent":"中元スポーツ推進課長","answer":"施設につきましては、やはり都心の品川区ですので、そう簡単に作りますという話にはならないところがあります。やはり既存の学校の施設や公園運動施設の公平な利用を引き続きスポーツ推進課で努めていきたいです。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問","question":"近くがいいのは当然そうなのですけれども、近くでなければ空いていますというのは大事かなと思っています。先ほどの中でも学校や地域というお話があったと思うのですけれども、そういった連携もしっかり実施していかれるということでいいか尋ねました。","respondent":"中元スポーツ推進課長","answer":"品川区内の運動、体育の施設につきましては、施設予約システムで一本化しているところがあります。私どもの職員がご案内し、スポーツコンシェルジュ的なことをスポーツ推進課の職員がやらせていただいているところです。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"今伺っていていいなと思ったのは、いろいろな形が出てくるというところではすばらしいなと思いましたので、引き続き頑張っていただきたい。その辺の取組もぜひ進めていっていただいたほうがいいのかなと思っているのですけれども、その点について、最後に説明を求めました。","respondent":"中元スポーツ推進課長","answer":"現役の方も多いので、部活といいますと平日の午後になってまいりますので、その辺のマッチングが課題かなと。今後、報酬面などで国や文部科学省で一定の方向性が出てくるのを期待しています。","id":"exchange-017"},{"speaker":"大倉委員","kind":"意見","question":"ぜひ力を貸してくださいといえば、指導をするのが好きな方もいっぱいいらっしゃると思うので、連携してやっていっていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-018"},{"speaker":"つる副委員長","kind":"提案","question":"今年の第１回定例会で、質問でラジオ体操の提案をさせていただいて、朝にやっていきますということを頂いています。それを説明を求めました。","respondent":"中元スポーツ推進課長","answer":"職員のほうでは実施しておりませんが、今のところ毎日５時１５分にしながわ体操を文化スポーツ振興部としてはやらせていただいているところです。紹介、ＰＲをかねて、時間で流させていただこうということで準備を進めているところです。","id":"exchange-019"},{"speaker":"つる副委員長","kind":"提案","question":"しながわ健康ポイントも提案して、実施していただいて、もう４年目ですか。聞き方によって、７割、８割がやっていないとなるのかもしれないけれども、実際はやっているという、加点方式というのか尋ねました。","respondent":"中元スポーツ推進課長","answer":"庁内なのですが、実は、私が先ほど説明で漏らしてございましたが、この計画を作るに当たって、庁内検討会というものを立ち上げてあります。今後も引き続き公園課と連携を図りながら工夫してまいりたいと思っているところです。","id":"exchange-020"},{"speaker":"つる副委員長","kind":"質問・要望","question":"言われても、どうすることもできないではないかという質問だったと思うのです。もしも既に何かお考えがあるのであれば説明を求めました。","respondent":"中元スポーツ推進課長","answer":"今年度、実は地域スポーツクラブが４地区に整いましたので、ぜひボッチャで対抗戦みたいなものをやろうよという形で計画をしていました。いろいろ防止策をしながら何とかやれればなということで、ボッチャについては引き続き普及啓発に努めてまいりたいと考えているところです。","id":"exchange-021"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ぜひ来年度に新たな取組ができるといいわけですけれども、そういったことを使って、やはり出入り自由な雰囲気というのでしょうか。詳しい人はいるけれども、誰でもが出入り自由など、いろいろルールがあるわけではないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-02","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"小芝委員","kind":"質問","question":"本当に皆様も疑心暗鬼になっておりまして、私にも地域の方からどうなっているのだといういろいろな問い合わせのお声も聞いておりました。そのキャンペーンを行った後の反響について、少し教えていただけますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"私どもである程度助成金なども考えながら、リサーチングさせていただいて、一緒に取り組んでいきましょうという形にさせていただきました。それ以降は、あのときは大変だったねという話で今は収まっているぐらいですので、徐々に持ち直したと認識しています。","id":"exchange-023"},{"speaker":"小芝委員","kind":"質問","question":"報道の自由がありますから、区からもそこら辺の予防策というわけではないですが、何か事前の取組をしておかなければならなくなってくるのではないか。今後、どうなるか分かりませんけれども、その辺のご意見をお聞かせいただいてもよろしいか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"それ以降、両商店街につきましては、マスコミの取材は受けないという形で対応されたと聞いているところです。１つは、変なものというか、それは違うのですよということをいかに言っていくかという部分での対応という形になるのかなと考えているところです。","id":"exchange-024"},{"speaker":"松本委員","kind":"質問","question":"区政に関するご意見３６件という話、あと、電話の対応が２２件ということです。これは、果たして区民の声がどのくらいあるのかなというところで、区外のものの割合はどのくらいなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"数字としては持っていないのですが、思っている以上、半分ぐらいは区外の方と考えております。","id":"exchange-025"},{"speaker":"松本委員","kind":"質問","question":"記者会見をやられたということなのですが、これは、どういうところでどのように記者会見をやられたのか。ご存じの範囲でお伺いできればと思います。","respondent":"遠藤商業・ものづくり課長","answer":"その地域にある３つの商店街が、何をやろうかといろいろ考えられて、フラッグを立てたという形になっています。会場が結構ぎゅうぎゅうになるというか、密の中で大変でしたが、そのような状況でやらせていただいたです。","id":"exchange-026"},{"speaker":"松本委員","kind":"質問","question":"プレスリリース自体は、商店街が同時にやられたのか、品川区としてもプレスリリースのところにある程度ご協力されたのか。その辺りはどうなのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"多分、商店街だけでは限りがあるかと思いますので、うちの広報部門が、それぞれの新聞社などですと、品川区担当みたいな形で個別に電話などもしていただいて、ぜひ来てくださいという形でやらせていただいたです。","id":"exchange-027"},{"speaker":"松本委員","kind":"質問・要望","question":"なので、ぜひとも商店街と、こちら側からも対抗する手段があるよということは共有していただきたいかなと思うのです。その辺りはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"どう対応すればというのは、こちらから発信するという意味では、非常に重要だと感じたところです。今後、いろいろな形で、今までのものを検証しながらつなげていきたいと考えております。","id":"exchange-028"},{"speaker":"松本委員","kind":"質問","question":"この辺りの評価をお伺いできればと思います。お願いします。","respondent":"遠藤商業・ものづくり課長","answer":"あちらの課題として、それ以上はどうしても費用がかかってしまうということで、今はそれほどやっていらっしゃらないかなと認識しています。その辺については、今後、商店街も研究しながらやっていくような形になるかなと考えています。","id":"exchange-029"},{"speaker":"松本委員","kind":"質問・要望","question":"最後に要望になりますけれども、やはり広げていくのはボランティア的になってなかなか難しいというのは、そうなのだろうなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、そういったことも国に求めていただけたらなと思うのです。自粛するなら補償もセットでということを私たちはずっと求めてきていたのですけれども、ぜひ求めていただきたいし、そこはいかがか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"仮にお店で感染したとしても、当然、マスクなどをしていれば濃厚接触者には該当しない形になろうかと考えています。そういう部分を使っていただきまして、仮に感染が出た場合には乗り切っていただければです。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問","question":"どんどんこうした事業を充実させていくべきだと言っているのですけれども、「Ｇｏ Ｔｏ商店街」は、現在申請はない状況だということです。その状況というのは把握されているか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"「Ｇｏ Ｔｏ商店街」の申請がないというのは、私どもの事業の資金貸付がないという形で考えています。一応、聞いている限りですと、大体十五、六件で、３０弱の商店街が申し込むのではないかという形で、今認識しています。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"営業を支えるという部分では、大事だということも報道では言われていますけれども、やはり感染が広がったら、また閉めなければいけないわけです。安心してその後も営業できるという状況を作っていくことに転換していくべきだなと思うので、国に求めていただきたいなと強くお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"くにば委員","kind":"質問","question":"こちらに関して、今おっしゃったのが、最終的に３０件ぐらい申請があるような見込みだと伺っていらっしゃるのでしょうか。そちらの２点をお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"約３０の商店街がやるという話も聞いているのですが、それも結局、商店街として正式な意思疎通ができた中で言っているのかが分からない状況です。その辺で、今のところ最大でそのぐらいではないかと考えているところです。","id":"exchange-034"},{"speaker":"くにば委員","kind":"質問","question":"先ほどの答弁でありました、最終的にこれは国の事業ということで、品川区として最終的な部分までは把握していらっしゃらないということだったのです。最終的に今おっしゃった３０件がやるのではないかとおっしゃっている中で、具体的にどういった事業をやるという情報が届いているのか伺いたいのです。","respondent":"遠藤商業・ものづくり課長","answer":"先ほども申しましたとおり、口頭で聞いている範囲なので、何とも分かりかねるです。","id":"exchange-035"},{"speaker":"くにば委員","kind":"質問・要望","question":"情報が限られているとか、情報を余り持っていない方々に対して、区からたくさんの例示をしてあげてほしいのです。国が行っている以上、推進できる部分は推進していっていただきたい、進めていただきたいなという要望が１点。","respondent":"遠藤商業・ものづくり課長","answer":"いろいろな形で、本当に商店街によってばらばらです。それを配るとか、あとは啓発的なもので使われたというところが多かったようなイメージがあります。","id":"exchange-036"},{"speaker":"くにば委員","kind":"質問","question":"そちらに関しては、最終的に全ての収支報告を受けるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"こちらにつきましては、支援金という形をとっておりますので、一律に最初に給付しまして、そのときにこういうものに使いますというのを出していただくような形になっておりますので、終わった後に、このうち幾ら使ったという報告は求めないものになっております。","id":"exchange-037"},{"speaker":"くにば委員","kind":"質問","question":"この支援金は、全て使っていない商店街に関しては、これから使うことが可能なものなのでしょうか。まだ、これを使っていないから、これから充てようという形で、まだ使っていない部分に関してこれから使うことができるような支援金なのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"いわゆる商店街への支援という扱いになっておりますので、空気清浄機というものは事務所に設置する可能性はあるかと思いますけれども。今回支援金を出させていただいて、こういう形で対策していますよとか、アルコールなども含めての支援金という形になっておりますので。","id":"exchange-038"},{"speaker":"くにば委員","kind":"質問","question":"すみません。アルコールなどの消費されるものに関しては、翌年に持ち越せる形で取得しておけるような類いの支援金なのかを伺いたいです。","respondent":"遠藤商業・ものづくり課長","answer":"それをどのようにいつ使うかということについては制限を設けておりませんので、そのタイミングでお使いいただければと考えているところです。","id":"exchange-039"},{"speaker":"くにば委員","kind":"質問","question":"例えば２年、３年先まで、かなりたくさんストックはされていると思うのです。そういったフェーズにおいて、現状考えている部分がいつぐらいまでで、大枠としてどれぐらいのボリュームなのかというのをお伺いしたいです。","respondent":"遠藤商業・ものづくり課長","answer":"支援の中身をどのぐらいまで考えているかというところなのですけれども、当然、いろいろなメニューを想定しています。考えとしてここまでという期限みたいなものはないのですが、考えとしては、元のとおりに戻るまでは十分考えているです。","id":"exchange-040"},{"speaker":"くにば委員","kind":"意見","question":"例えば直近の報道で、もしワクチンができたとしても、日本人がそれを接種しようと思うかどうかということに関して、たしか６８％でしたか。区として、第３波を乗り越えた後、また第４波が来るかどうかみたいな情報や算段、予想はどこまでされていますかとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"当然、第４波もあるという想定はしておかなければいけないなですけれども、それがいつまであるかというのはなかなか判断できないところです。次に備えるというところで考えております。","id":"exchange-041"},{"speaker":"くにば委員","kind":"質問・要望","question":"きちんとした考えや、予算の範囲内で新たな施策などをストックして、長期的に考えておいていただけたらなという要望が１つあるためです。例えばアクリル板１つについて細かく言及すると、実効性が実際にあるかどうかというのは、区で何かデータなどは把握なさっているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"例えばマスクについては正確なデータが出ていて、つけていることによって感染が抑えられるという話があろうかと思います。アクリル板で隣と遮断することで十分効果があるということで、区内に限らず、広くアクリル板が用いられているのかなと考えております。","id":"exchange-042"},{"speaker":"くにば委員","kind":"質問","question":"それは先ほど伺った実効性の部分なのですけれども、何かしらエビデンスがあれば、さらにお店を後押しする要因にもなると思うのです。例えばアクリル板の導入などを飲食店に積極的に促すというのは、広報の観点も含めて、施策を推し進めていくという部分の考えは何かあるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そこまでやるべきなのかなというか、そこに力を強めるのだったら、ほかのところにかけたほうがというのが、今のところの現状です。そのように考えているところです。","id":"exchange-043"},{"speaker":"くにば委員","kind":"質問・要望","question":"そこは要望という形で、入店するモチベーションになると私は思うので、そこに関しては広報をお願いしたいと思います。ＩＴ導入サポーター、商店街にかける五反田バレーに関して、次の施策はどのようなことを考えていらっしゃいますか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"民間企業との連携でデジマ式ｐｌｕｓというものをやらせていただいて、それを今度は横展開していって、いろいろなところの商店街に使っていただく。そういう部分で、私どもで何か支援したり、予算を組むのであれば、実証実験などのお手伝いができるのかなと考えているところです。","id":"exchange-044"},{"speaker":"くにば委員","kind":"提案","question":"五反田バレーの方々に、区からの提案でこういったことをもっとやってみましょうという提案は、様々なさっているのでしょうか。そこの部分をもっと推し進めていただきたいなという気持ちがありましてお伺いしているのですとの意見を述べました。","respondent":"遠藤商業・ものづくり課長","answer":"直接的には、間に入る方というか、こういう形ならビジネスに結びつくのではないかというところが一番難しいと考えているところです。今回初めて２５日にさせていただいたので、そこがうまく展開できればということで、今動き出したところです。","id":"exchange-045"},{"speaker":"くにば委員","kind":"質問・要望","question":"まだまだ品川区の産業、商店街が強くなっていける余地があると思うので、ぜひともいま一度力を入れて取り組んでいただければなという要望です。作成した後の伴走や、アドバイス、カウンセリングをどの程度まで進めていく予定なのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"そこをどのようにやったら売れるのか、このようなものは駄目なのですという部分を事細かくやっていただいています。もう一回、それぞれの事業者がいろいろと困っている部分につきまして、区とストアーズのほうで支援などをさせていただければと思っているところです。","id":"exchange-046"},{"speaker":"くにば委員","kind":"質問・要望","question":"そのサポートの部分、今後のコンサルティングをぜひともしっかり意識しながら、ウオッチをし続けていってほしいなと思っています。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"大倉委員","kind":"質問・要望","question":"５分の４なのかは分からないですけれども、その負担はしてくださいなのか、その辺の考え方について教えていただきたい。見守りなど、いろいろな商店街の能力が求められているところで言うと、その辺の把握はしておかなければいけないのかなと思うのです。","respondent":"遠藤商業・ものづくり課長","answer":"こちらに書いてあるように、できれば私どもの用意した２の(3)のホリデー・トレーニングをまずは使っていただこうと考えているところです。そういう部分での支援という形で考えているところです。","id":"exchange-048"},{"speaker":"大倉委員","kind":"質問","question":"商店街以外だとなかなか難しいのかなというところもあるのですが、そういった把握をされているかどうか。商店街内の連携とか、五反田バレーとの連携というのもされているのかなと思うのですけれども、その辺の状況も合わせて教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"それから、商店街連合会との連携というお話です。今後も商店街連合会のご意向などを聞きながら進めていければなと思っているところです。","id":"exchange-049"},{"speaker":"大倉委員","kind":"意見","question":"今、そういういろいろな業態などでうまく連携できないかということで、デジマ式ｐｌｕｓもやられているのかなと思うのです。これからまたどうなるか分からない中で、商店街は非常に大変な部分があると思うので、ぜひ応援してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"つる副委員長","kind":"質問・要望","question":"できることとして具体的にどういったことがあるのかということと、実際のいろいろな声を幾つか参考程度に教えていただきたい。個店数が分かれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"昨日も少し話のありました、販路拡大支援事業の助成や、家賃の支援という部分で、こちらのほうでは支援させていただいているところです。申し訳ございません。","id":"exchange-051"},{"speaker":"つる副委員長","kind":"質問","question":"四半期に１回出していただいている品川区の景況を見ると、逆に言うと、飲食というのはサービス業に入るのですか。製造など、いろいろと分かれていて、飲食というのは、その中でいうと、どのなりわいとして入ってカウントされているのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"物に付加価値をかけるという形になりますので、サービス業だったと認識しております。","id":"exchange-052"},{"speaker":"つる副委員長","kind":"質問","question":"個店というのは、なかなかそういった全体のにぎわいづくりの中に位置づけられにくい部分です。そうしたところに対しての支援というのは、今後、長期化という視点も含めて、どのように考えているのか説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"本当の個店について何か支援するということになりますと、金銭的な部分についてなかなか難しいところがあります。そのような部分を手厚くして、こういう形でやっていくのはどうですかといういろいろな情報でご支援などができればなと考えているところです。","id":"exchange-053"},{"speaker":"つる副委員長","kind":"質問","question":"１人で来てくれたとか、持ち帰りのお店に対する支援というのがあるのですけれども、消費者に対するポイントなどがあると思うのです。その活用など、その辺も含めて、商店街支援にもつながる消費者への支援についてあれば説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"消費者にとっては、３０％のプレミアムを乗っけて、それを軸に今年はやらせていただいたところです。ご指摘いただいた部分については、いろいろと広報等もあろうかと思いますので、今後も研究させていただければと考えています。","id":"exchange-054"},{"speaker":"つる副委員長","kind":"質問","question":"だから、ほかの区では、既に自治体ナイズした何とかペイなどをいろいろ作ってやっているのですけれども、その辺の今後。もしかしたら先ほど答弁があったのかもしれないのですけれども、区共通のキャッシュレス決済の在りようというのは、何かできるのか尋ねました。","respondent":"遠藤商業・ものづくり課長","answer":"例えばお店の人からすると、いまだにほかの自治体でやっているような話も聞いておりますけれども、まだ結論が出ていないところです。課題としては認識していますので、引き続き研究させていただければです。","id":"exchange-055"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/297302?Template=document&Id=2886#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":51799,"voices":126}},{"id":"r02-20201201-7","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"厚生委員会","time":"午前１０時００分～午後 ０時２２分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"冒頭申し上げましたとおり、取上げる順番を変更し、報告事項(2)から先に行います。 それでは、(2)新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"感染が２桁ぐらいずつ増えている状況だと、体制と、そのトレーサーの状況あたりを少し教えていただけたらと思います。これだけ感染が増える中で、ＰＣＲ検査センターのほうの対応は１日何件ぐらいなのか、その点についてもお聞かせいただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"翌日の１０時までに、１人の陽性者が出たときに、その周りへの対応というものが本当に増えているというのはあります。そういった場合は前後の週で検査の日数を増やしていただいたりということで、大変協力的に対応していただいているところであります。","id":"exchange-001"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"第１波のときは、残業もかなり多かったと思うのですが、今はそれほどの残業にならなくて済んでいるという状況でしょうか。水曜日ですか、１週間に２回ぐらいとか、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"例えば残りの４日の中ですと、業務自体が減るわけではないものですから、残業が如実に減ったという状況には残念ながらありません。火曜日１日で全てをやるというのが、それ以上の回数というのは、正確性を期すためには難しいかと思います。","id":"exchange-002"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"それはそれで分かりますので、連日本当に大変な思いをされているということですので、了解します。何とか解消できるような対策というのは、庁内でも取れないのかなと思うのですが、そこら辺のところの対策はいかがなのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"私が保健予防課長の立場でどう答えるか……。","id":"exchange-003"},{"speaker":"あくつ委員","kind":"質問","question":"少しそのあたりの、今のところのご見解みたいなものについて、教えていただける範囲で教えていただければ。それは当然議会も例外ではないのですけれども、教えてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"それ以外の職場の中でという形は、幸い今のところ区役所の中では……。保育園で第１波のときに、明らかにその個室でうつったなという保育園が１か所ございましたけれども、幸い把握してはございません。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問","question":"ありがとうございました。お話を伺わなければいけない、やはり立場上あるものですから、現業というのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"}]},{"id":"topic-02","title":"を再度、聴取いたします。 それでは、(1)第八期品川区介護保険事業計画概要（案）","agenda":"を再度、聴取いたします。 それでは、(1)第八期品川区介護保険事業計画概要（案）","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"たしかほかの業種の平均賃金と比べて、月額で１０万円ほど安いのだというお話も、いろいろなところで伺っているところです。ですから、その点はどうお考えになっているのか、１つお伺いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"ですので、そこに関しては私どもも大変重要に捉えておりまして、様々な支援策をこれまでも講じてまいりましたし、これからも講じてまいる予定です。それ以外のところで、介護に関わるサービスの従事者に関わる様々な支援策というのは、講じてまいりたいと考えているところです。","id":"exchange-006"},{"speaker":"おくの委員","kind":"質問","question":"少なくともこのプロジェクトの１つの課題、やっておいていいのではないかと私は思うのですけれども、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"今回、こちらの計画の中にも、例えば外国人雇用を検討するという文言を入れさせていただきました。しっかりと、日本人の方と全く変わらない待遇、処遇で採用したいと考えておりますので、そこだけは、しっかりと申し上げておきたいと思います。","id":"exchange-007"},{"speaker":"おくの委員","kind":"質問","question":"これは素朴になぜなのかというのをお伺いしたいと思います。お伺いします。","respondent":"宮尾高齢者福祉課長","answer":"１点目の認知症高齢者グループホームの伸びが、給付費の見込み、この数値を立てているところです。２０２０年度の見込みが、適切なサービス提供量の見込み、給付費の見込みを勘案して。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"それから、６,１００円から６,３００円程度にするのを見込んでいるということですが、これをどのぐらい取り崩していくとお考えになっているのか。そして、取り崩した残額がどのぐらいになると見込まれているのかというのを、お伺いしておきたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"見込みが６,４００円ですので、３億５,０００万円の基金投入、充当が必要かと予想しております。６,１００円にした場合は約９億５,０００万円程度の充当が必要と考えているところです。","id":"exchange-009"},{"speaker":"あくつ委員","kind":"質問・要望","question":"何というのですか、営業のスキルを持った人たちを入れるべきだとおっしゃっていましたけれども、取れる資格は社会福祉士ですか。そうしないと、何かもう少し踏み込んだお考えがあれば、教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"こちらにつきましては引き続きやっていくとともに、区としてもしっかりと支援をしてまいりたいと考えています。３年間区内にお勤めいただければ返済が免除されるという、これは本当に品川区ならではのすばらしい制度だと考えています。","id":"exchange-010"},{"speaker":"あくつ委員","kind":"意見","question":"どうしてもこのままいくと、あればというところでの希望で、お話をさせていただきました。すみません、無責任なことを言ってとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"渡部委員","kind":"質問・要望","question":"平均ですから、何で品川区はこんなに安くできているのかというのを改めて説明いただきたいのと、恒常的に続けられるのか。１個はそれをお聞かせいただきたいのと、１６ページは、最初の質問をお願いします。","respondent":"宮尾高齢者福祉課長","answer":"サービス量を見込み、それから給付費を見込み、大体６,４００円程度という見込みが出ております。２３区の中では下から、安いほうから数えたほうが早いというふうに、認識として持っているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１つお聞かせいただきたいのと、この計画を策定するにあたって、コンサルは入っているのでしょうか。私毎回、ぜひ説明会を開いてほしいということで要望し続けているのですが、その点についても説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"直接お寄せいただくというような、幅広い選択肢を用意しておりますので、説明会の開催というのは考えておりません。説明会を実施している自治体が、保険者があるというところは、認識しております。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そういうのを聞く機会としても捉えていただきたいし、改めてやっていただくようにということで、要望しておきたいと思います。報告をいただいた記憶がないのですが、そこの点についても説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"説明会につきましては、モニタリング調査等も行っておりますので、区として実施する考えはございません。こういうことによって、外部の方からのご意見を頂戴する予定です。","id":"exchange-014"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５００メートル以内に親族がいない高齢者を、その点をお聞かせいただきたいのと、どれぐらいになっているのかについてもお聞かせほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"支援が必要な方とか、ひとり暮らしをされている方で比較的支援というか、当然カウントしてきているという実態はあろうかと思います。これは３年に１回やっているので、残念ながらお示しできる調査ができていないので、今後の形になろうかと思います。","id":"exchange-015"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"では３年に一度やったというのは、いつの調査なのか、教えていただけたらと思います。３ページのところで、３５.５％まで上がっているのだなと思ったのですが、伺いたいと思います。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長","answer":"それで、今回３年後でまた来るということになっていた。そういった事業者が民間も含めていますので、そういった支援をしていくということを地域づくりと併せて取組む、そのような動きに今なっています。 介護保険事業計画の策定に合わせて、３年に一度、介護予防日常生活圏域ニーズ調査というものを行います。３か年のうちの３年目に実施できれば、年度としては昨年度、今年の１月から２月に調査を行ったです。","id":"exchange-016"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"地域包括支援センターということであれば、この保健師の数を私は増やすべきではないかと思うのですが、その点をお聞かせほしいと求めました。それから、地域包括支援センターの責任者というのは誰になるのか、その点についてもお聞かせほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"あるいは直接現地に赴いて対応したりということで、お受けした相談の対応内容に差が出るということは、決してないと認識しています。一般的にご相談いただく内容を対応するのは、高齢者支援第一係、課全体でセンターの位置づけを保っていると思っているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"品川区の条例でも書かれているわけですから、本当にこのような区は品川区だけですから、お願いしたいと思います。処遇改善交付金というのをぜひ復活させていただきたい、これをまた国に求めていただきたいと私は思うのですが、その点についてはいかがか尋ねました。","respondent":"宮尾高齢者福祉課長、寺嶋福祉計画課長","answer":"この重点プロジェクトの１つに掲げて、体制をしっかりと整備し、できる限りの支援をしてまいりたいと考えているところです。全業種の平均値に比べると、かなり低い数字になっていると認識しています。 高齢者福祉関係の福祉避難所としまして、避難所には特養１２か所、老健２か所、ケアホーム１か所が今の段階で指定されているという認識です。検討ですけれども、今年度も福祉部内で検討しまして、まず福祉部内で検討して。","id":"exchange-018"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"１６ページの「介護サービス量の推移と見込み」というところの、８９だったのが３５まですごく減ったのですが、これは何か理由があるのでしょうか。それから、療養病床が、今度は介護医療院に変わっていると思うのですが、今、区内に、療養病床というのは実際あるのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"夜間対応型訪問介護と老健に関して利用が減っているですけれども、やはり考えられるものといたしましては、そのほかいろいろな状況が考えられます。ただ、それらを踏まえて、第八期に向けては、そういった事情も踏まえて… それから、介護療養型医療施設から介護医療院への変更点ですが、大きな変更点というのは特にないと思っています。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"６,１００円から６,３００円ということで、５００円から７００円のすごい大幅な値上げになるということで、１つお聞かせほしいと求めました。今年度末までに基金はおおよそ幾らぐらい残るのか、それをどれくらいまで取崩すことが可能なのか、区の考えを説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"第七期の開始時は、少し丸めた、概数になりますが、約１７億２,０００万円ほどの基金残高をもってスタートしております。今年度末に一部取崩しを行う見込みとなっておりまして、約１２億円、この金額をもって第八期を迎えるものと想定しております。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、たしか区としても、その下に出ている費用負担の割合というところがあるではないですか。丸々２５％と、そういう要望を国に対して出していたと思うのですが、今でもそういう方向で出されているのか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"最終的にこれから年度末に向けて、しっかりとサービス供給量の見込み等を精査していって、適正な金額を設定させていただきたいと考えています。継続的に、しっかりと制度を運営できる、保険者としての責務をしっかりと果たせる金額を設定したいと考えています。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"本来であれば、５割はもともと国が負担していたわけですから、そういう形で増やすような方向でぜひ国にも求めていただいて。そのことも要望させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"今これは何の仕事をされていらっしゃるのか教えていただきたいということと、幾つか、どういうことをされているのかご紹介ほしいと求めました。そういうところについて身体障害者の方から、もうそういった声があるのかどうか、教えてほしいと求めました。","respondent":"松山障害者福祉課長","answer":"就労継続支援Ａ型については、主に食品製造が多いです。重度障害者の方が何か社会と関わる機会というのを、私どもも今現在検討しています。","id":"exchange-023"},{"speaker":"あくつ委員","kind":"質問・要望","question":"私がご紹介しても、そのまま就労につながらない方も当然いました。やはりできるだけ選択肢を増やしていただきたいということと、そういうところも今、ぜひそういったことも前向きに取組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"中小企業向けの障害者雇用に対する様々な助成金とかというのがあるのだけれども、区は何かそういうメニューというのは用意しているのですか。ただ、そういう啓発というのが何かあるのかなと思いまして聞こうと思ったのですが、いいか尋ねました。","respondent":"松山障害者福祉課長","answer":"あるいは企業見学会というのを予定しておりまして、就労支援部会で様々な事業所が入ってアイデアを出しているところなので、中小企業と一緒に連携する機会というのをつくっていきたいと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"そこら辺の考え方を１つ教えていただきたいのと、品川区ではレスパイトをやっていただいて、すごい助かるということで伺っています。これをすることが、それがないとなかなか難しいのかなという思いをしているのですが、その見通しも含めて説明を求めました。","respondent":"松山障害者福祉課長","answer":"フローレンスが実施する医療的ケア児の地域支援促進事業の中で、事業開始にあたり、数字を詳細に把握したものです。ただし、この連絡会は非常に重要と区は考えておりますので、今年度中には何かしらの形で実施したいと考えております。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現在の３５.８％から５５％まで、２０２９年度までには持っていくということですが、お聞かせいただけたらと思います。どういう資格、また一般企業に入られた方で辞めてしまう割合みたいなものが分かったら、教えていただけたらと思います。","respondent":"松山障害者福祉課長","answer":"それから、お一人の方が生活支援のコーディネーター、そして管理者が１人という状態です。支援開始１年後の定着率というのを、それによれば７３％の方、前の年は３３人の方が就職したということでございました。","id":"exchange-027"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"来年の３月１日から法定雇用率が引き上げになりますよね。自治体とかは２.６％になるということですが、種別に雇用をしてほしいという、そういうところに対してはどう考えられているのか尋ねました。","respondent":"松山障害者福祉課長","answer":"次の障害種別に雇用をするかどうかにつきましても、やはり特別区全体の人事に関しますので、制度上のものかと承知をしております。この制度上のものというのは、品川区だけで独自に何かを考えるということは、なかなか難しいと考えています。","id":"exchange-028"},{"speaker":"鈴木（ひ）副委員長","kind":"意見","question":"どういうところでどういう仕事をつくり出すかというところは、様々工夫すればできる部分というのがたくさんあると思うのです。障害者福祉課が、こういう形で目標を上げるというところも出ていることですので、ぜひそういうところでは働きかけも併せてお願いしておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/410936?Template=document&Id=3584#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40823,"voices":100}},{"id":"r02-20201201-8","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"建設委員会","time":"午前１０時００分～午後 ０時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"令和３年１月区営住宅入居者募集","agenda":"令和３年１月区営住宅入居者募集","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１点だけお聞きします。年に何回かこの区営住宅の募集があるのですけれども、当然、入居されている方の状況にもよりますが、実績として年間にどのくらい入れているのか尋ねました。","respondent":"森住宅課長","answer":"それから令和２年１月ですと、これも７戸です。その前の７月ですと、４戸という形になっておりまして、年間通しますと、１０戸前後、１５戸程度というところかなと思っています。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"前回の募集倍率が幾つだったかを伺いたいと思います。","respondent":"森住宅課長","answer":"募集倍率につきましては、令和２年７月ですと、単身向けで４６.５倍、世帯向けで３７倍となっています。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり高い倍率になっておりますので、どうしても区営住宅増設に向けて力を尽くしていただきたい、増やしていただきたいと希望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"}]},{"id":"topic-02","title":"（仮称）品川区立環境学習交流施設の検討状況","agenda":"（仮称）品川区立環境学習交流施設の検討状況","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"啓発になるだけではなくて、実践をしてほしいと思って、今のパネルの表示だったりとかを要望しているのです。確認をしたいのですけれども、まさか考えていないですよねといったところを確認させてほしいと求めました。","respondent":"提坂環境課長","answer":"雨水の利用についても、雨水を貯留する水槽を設置する予定です。今、施設の中に設置を検討していますけれども、ペットボトルなどは極力使わないほうがいいということで考えてあります。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"保育園だったり幼稚園での利用の促進はどのように考えられているのかを伺いたいのと、そういうものはかかるのかも伺いたいです。自ら答えを出す参加型展示なのですけれども、このプランターの展示のところがどういったものなのかと思いまして、ずっと置いておけるものなのか尋ねました。","respondent":"提坂環境課長","answer":"環境学習交流施設の中でも常設できるとか、区のほかの施設でも設置できないかとか、その辺を検討してまいりたいと考えています。自ら答えを出す参加型展示ということで、どういう形でメッセージを貼って、ごみにならないような工夫を考えてまいりたいと考えています。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問・要望","question":"そこはやはりきちんと丁寧に説明もしながらやってほしいと求めましたし、せっかく造るので、そこのところを少しご答弁いただけたらと思います。今、３０くらいの講座をやっていると聞いているのですが、その講座なども引き継いでいかれるのか、伺いたいと思います。","respondent":"提坂環境課長","answer":"１回だけで終わるのではなくて、その後は今度、個人で来てみようかなという魅力を発信できるような施設を考えてあります。運営事業者候補者の方とも少し協議を重ねて、そのノウハウを使って、新たな展開を図っていただきたいということを考えてまいりたいと思ってあります。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"やはりそういった実際に公園の中にあるわけですから、さらに関心を持ってもらえるように、発展するようにということでお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"単純で分かりやすいツールの近年の一番の流れとして、過日の本会議の質問にもあったように、ＶＲの活用も一つありかなと。そこのところをどのように活用されるのか、どのような方向性をＶＲに対して持っていらっしゃるのか、説明を求めました。","respondent":"提坂環境課長","answer":"単純で分かりやすいということとはどういうことかとご説明すると、お一人で来ることはなかなか考えづらいので、そういう展開を考えています。ＶＲの活用とかその辺についても、どういう形で活用できるかということは検討してまいりたいと考えています。","id":"exchange-008"},{"speaker":"西本委員","kind":"質問・要望","question":"なぜこの施設を造ろうと思ったのかという根拠をまず示してほしいのです。そこからお願いしたいです。","respondent":"提坂環境課長","answer":"平成３０年度の予算措置前から検討を進めてきてまいりまして、まず１点目は、国のほうでアンケートを実施しているのですけれども。２点目は区民の環境に対する意識ということで、３年前に品川区環境基本計画の策定にあたりましてアンケートを実施しています。","id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"ただ、なぜこの施設なのですかというところなのです。１回来て終わりとかになりがちな部分もあって、何ていうのでしょうか、新しい技術も加えていかなければいけないことなのではないかなと思うのです。","respondent":"提坂環境課長","answer":"自発的、活動を活性化させるためにもっと大きな拠点としての整備が必要だと考えまして、施設建設に至ったものです。実際の自然環境の中の、戸越公園の中を散策していただいて、自然環境の保全を感じ取っていただければと考えています。","id":"exchange-010"},{"speaker":"西本委員","kind":"質問・要望","question":"では０、１、２歳児の在宅のお母さんたちということは、児童センターに通っている親子たちが対象なのですか。保育園の先生方といろいろと何かできないかとかというふうにして、運用は決めてほしいと求めましたが、いかがか尋ねました。","respondent":"提坂環境課長","answer":"はっきりと何時までと少し決めかねる部分であるのですけれども、常識的にいえば１７時、１８時くらいになると考えております。そして幼稚園、庁内でもいろいろ調整して、より利用しやすい施設にしていきたいと考えています。","id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"こちらが決めたからといって、こちらの都合がいいように人は来ないです。では３年から６年生の間にこれだけの税金を使うのですかという話になってしまうので、そうではなくて、それだけ、答えるよう求めました。","respondent":"提坂環境課長","answer":"今、ご指摘のとおり、様々な所管課と協議を重ねてまいりまして、より利用しやすい施設にしていきたいと考えています。２か月くらい前に港区の施設を視察したのですけれども、基本はお子さんが対象なのですが、そういうイメージを持っております。","id":"exchange-012"},{"speaker":"田中委員","kind":"確認","question":"１点目が、障害児者の方たちも楽しめる整備がされているのかを確認させてください。まちづくりマスタープランの中で、具体的な、補完的なというのがどの程度の防災機能を備えているのかを確認させてほしいと求めました。","respondent":"提坂環境課長","answer":"障害者、あと視覚障害とか聴覚障害の方にも対応できるような形で、映像だけでも十分分かるような仕組みを考えてまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひトイレとかは当事者の方たちの意見も聞きながら設置をしていただきたい。ぜひ当事者の方たちに来ていただいて、実際に通ってもらって確認をしてほしいと求めましたが、いかがか尋ねました。","respondent":"提坂環境課長","answer":"建築設計事業者と協議を重ねてまいりますけれども、その中で車椅子の方が十分利用しやすい施設となるように、設計を進めてまいります。健常者が車椅子に乗って体験してみるとか、そういう形で使いやすい施設なのかどうかということの検証を重ねてまいりたいと考えています。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"令和４年の４月のオープンのときは、半年でも１年でもその後にでも、常にマスコミが紹介してくれるくらいの中心的な役割で。１０年で大きく変わると思うので、品川区の１つのシンボルにしていただきたいと思っているので、というところでお伺いしたい。","respondent":"提坂環境課長","answer":"その中で、施設で消費するエネルギーのうち７５％以上削減するランクを定めておりまして、交付決定の見込みが出ているところです。公共施設が多摩地区に１施設あるのですが、２３区で今、環境に積極的に取り組んでいる自治体だということをＰＲしていきたいと考えています。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこをどんどん突き詰めていっていただきたいし、あれは５万円程度でいいのかというのもあるけれども、そういうものをやっていくとか。何しろこれから多分ＣＯ２の排出量のことはどんどんそういう話が増えてくると思う。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"若林委員","kind":"提案","question":"では、何点か確認をします。運営事業者候補者からもこのフードドライブ事業についての提案というのか、希望、そこら辺のフードドライブ事業についての確認をまずさせてくださいとの意見を述べました。","respondent":"提坂環境課長","answer":"区としても食品を有効利用するフードドライブの実施は、食品ロス削減の大きな柱ということで、効果的な事業だと捉えてあります。その辺の頻度というのは、どういう形で実施するのが効果的であるかを、これから区と運営事業者候補者等とも検討をしてまいりたいと考えています。","id":"exchange-017"},{"speaker":"若林委員","kind":"質問・要望","question":"今年の代表質問でもＳＤＧｓに一貫してご質問をさせていただきましたけれども、まさに品川区内でＳＤＧｓに関して、やはり入り口としては環境。ＳＤＧｓという一貫性を持たせた何か見せ方、考え方というところを、もしお考えがあればお聞かせほしいと求めました。","respondent":"提坂環境課長","answer":"まだ正式に決まっていませんけれども、太陽光で走るソーラートレインの講座とか、そういう興味深い講座なんかも考えてまいりたいと考えています。その辺を踏まえて、品川区として環境保全活動を発信していく拠点として考えてあります。","id":"exchange-018"},{"speaker":"若林委員","kind":"質問・要望","question":"１７のゴールの４つほどを並べていただきましたけれども、ぜひＳＤＧｓを一貫して１７のゴール、この学習交流施設でこれから学べるのだなと。具体的にはそういうＣＯ２とか地球温暖化とかを本当に身に感じていくという、そういう一貫性というのですか、要望として終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-03","title":"しながわ区民公園北側ゾーンの改修","agenda":"しながわ区民公園北側ゾーンの改修","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、これは前回いろいろな話があった中で、そういったことも踏まえたところで案を出されたということでいいのかということも伺いたいと思います。それと実際、今回アンケートを行う中で、周辺住民の方の対象範囲がどこまでになるのか、伺いたいと思います。","respondent":"藤田防災まちづくり部長","answer":"それから周辺住民の範囲ですけれども、基本的には区民公園全体の周辺の方々にはポスティングはいたします。実際、先ほども申したとおり返信用の封筒を付したアンケート用紙を個別に配付するという形で行うものです。","id":"exchange-020"},{"speaker":"のだて委員","kind":"質問・要望","question":"たたき台の案のところで少し伺いたいのですが、多目的施設化とした目的が何か、伺いたいと思います。それと今回、これは実際の災害時のときにはどう使われていくのか、伺います。","respondent":"藤田防災まちづくり部長","answer":"様々な形で利用率が上がることがやはり望ましいと考えていますので、少年野球場として、多目的にも使えるという形で整備をするものです。今回、この園路が南側ゾーン、いろいろな物資を運搬するのにこの園路を使いながら搬入・搬出ができるということを考えて計画をしています。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"１２月中旬とお知らせがあったのですが、具体的にいつ頃なのかということと、ここはプレイパークがあるではないですか。プレイパークに協力してもらうといったような働き掛けは、今、想定されているのかを伺いたいです。","respondent":"藤田防災まちづくり部長","answer":"今回、そちらのほうへのポスト等の設置については今のところ考えてはいないところですが、その辺については十分検討したいと思います。","id":"exchange-022"},{"speaker":"田中委員","kind":"意見","question":"プレイパークとの関係のところなのですけれども、北側ゾーンで利用した方がプレイパークに来たり、またその逆とかもあると思うので、ぜひ協力していただければ、子どもたちの意見もより届くと思うので、ぜひ協力をしていただけたらと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"西本委員","kind":"質問","question":"野球場のところなのですけれども、この芝は、今現在、天然ですか。多目的だといい面もあれば、なかなか借りられなくなる状況も出てくることが起きやすいのではないかと思いますので、そのお考えをお知らせください。","respondent":"藤田防災まちづくり部長","answer":"それから多目的にすると使いたい方がいろいろと出てまいります。おっしゃるとおりですけれども、そこは今、しっかりと協議を進めていかなければいけない事項だと考えています。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな経緯があったのは分からないではないのですが、夜間まで使えるようにと、それも１つの要望としてあるわけなのです。絶対にやらないという状況なのか、それとも近隣の方々の了解が得られれば照明を付けてもいいとか、その辺は考え方としていかがなのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"その辺についても今回のアンケートの中でいろいろなご意見をいただいて、そこの中で区としての最終的な考えをお示ししていければと考えています。現段階ではいろいろなご意見が出て、それについてよく確認をしていくと思っているところです。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"項目の中に「夜間使用についてはいかがでしょうか」などと意見を求めるものがあると、いや、断言してしまうとそれ以上の意見が出てこないのです。いろいろなご意見を聞いてとおっしゃるので、だったらこういう書き方ではなくて、いかがか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"こちらの改修案のたたき台ですが、サッカーの利用も可能、あと天然芝であるとか人工芝の張り替えだとかその他の項目についても様々例示しています。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"ただ、こういうふうに断定してしまうと、なかなかご意見は出てこないのではないですかと言っているのです。これから再考していただけるものなのかどうか分かりませんが、検討していただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"田中委員","kind":"質問・要望","question":"現状平面図と改修案のところで、これは特にこれをなくすとかではないということを確認させてほしいと求めました。「トイレの洋式化」と書かれているのですけれども、今の機能を洋式に改善するという捉え方でよろしいのか、確認させてください。","respondent":"藤田防災まちづくり部長","answer":"基本的にはトイレについても駐輪場についても設置をする考えです。設計を進めている中で、位置等も含めて検討を加えて、最終的な結論を出したいと考えています。","id":"exchange-028"},{"speaker":"田中委員","kind":"質問・要望","question":"要望になるのですけれども、ぜひ障害児者の方たちも使えるものであることと、あと男性トイレにも子どものおむつ替えの設備が付くように。子どもにいたずらされて鍵を開けられてしまうことがあるので、ぜひ上のほうに鍵を設置してもらうとか、そういった配慮をお願いできたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"大沢委員","kind":"質問","question":"ここは、よく、高校野球でいえば甲子園が聖地であるように、品川区の子どもにとっては、この場所はやはり目標とすべき聖地なのです。ここの整備をお願いしたいと思いますし、そういうような１つ特色ある球場づくりというか、どうお考えなのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"その辺については十分感じておりますので、その辺も踏まえながら、整備の方法については検討していくべきだと考えています。そういう中で、そういった施設がつくれるところも限られてまいりますので、どういうやり方がいいのかについては確認をしていきたいと考えています。","id":"exchange-030"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そこら辺のことはよく考えてほしいし、品川南ふ頭公園で１面分のフォローはあったけれども、２面なくなっているわけです。それはきちんとそのときも説明したけれども、もう約１０年も経つわけだけれども、そういうことも含めて、意見は出すけれども、よく考えてほしい。","respondent":"藤田防災まちづくり部長","answer":"その辺については、どう折り合いがつけられるかについて、十分に区の中で検討を進めていきたいと考えています。照明等を設置することで確かに利用率、その辺について、区としても地域の方々も含め十分な検討を加えていかなければいけない項目だと思ってあります。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"それは考慮してほしいということであるのですが、あとここは照明があるのです。ですから、先ほどのアンケート用紙の話に入っていってしまうのですが、２回も言いませんけれども、その辺はどういう現状なのか尋ねました。","respondent":"藤田防災まちづくり部長","answer":"野球場そのものの利用が夜間まではないということで、当初、照明を付けなかったという経緯があると考えています。これからどういう形が一番いいのかについては十分検討を加えていきながら、区の案としてまとめていかなければいけないと考えています。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問","question":"この工事はそういう心配がないのかということで伺いたいと思うのですが、いかがでしょうかということと、具体的にどういうことでどう変わったのかを伺いたいと思います。","respondent":"松本河川下水道課長","answer":"家屋調査につきましては、今回、シールドで下水道管を造っていくのですが、トンネルから約４５度の角度で家屋調査を実施する予定です。当初設計では６６０戸の調査をする予定でしたが、現地を精査した結果、７１７戸に変更するものです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"これまでも上流部の工事はしてきているところではありますので、そういった安全面をしっかりとやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"提案","question":"それから全体の公園のことをやっていきますというお話、いつもそう言われるのだけれども、これは逆にいつ頃そういう提案は出てくるのですか。","respondent":"稲田土木管理課長","answer":"いつそういうのが分かってくるのかというのは、今現在、私のほうではその辺がいつ頃かというのは把握していないという状況です。今後の進み方等々を見ながら、これから全体を考えていくという話です。","id":"exchange-035"}]},{"id":"topic-04","title":"令和２年度 区内一斉防災訓練の実施","agenda":"令和２年度 区内一斉防災訓練の実施","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"そういった、やはり地元の意見を尊重しながら、防災訓練も重要な訓練ですのでやっていってほしいと求めました。その中で、少しご説明があったかとは思いますが、この新型コロナの対策をどのようにしてこの訓練をやっていくのかを伺いたいと思います。","respondent":"大森災害対策担当課長","answer":"区としますと７月中に新型コロナウイルス感染症に係る避難所運営マニュアルの標準版を各地区に配布させていただいているところです。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"今回のコロナを踏まえた訓練というところで、今のご答弁があったと思うのですけれども、私が聞きたかったのは、実施するにあたってのコロナ対策を聞きたかったので、そういうご答弁がありましたら。","respondent":"大森災害対策担当課長","answer":"９月上旬に防災課のほうで訓練をやるにあたってはこういった形であれば実施について検討できますというところについて、通知を流しています。感染症対策の消毒薬とかいったものを使って対応するというところなのですけれども、もう事前に各町会にお願いしまして、人数管理。","id":"exchange-037"},{"speaker":"西本委員","kind":"確認","question":"この目的で、なぜ一斉防災訓練をするのかということなのですね。一斉で訓練を行う意義、区との連携をどう確認して、どうやっていくのですかというところはいかがか尋ねました。","respondent":"大森災害対策担当課長","answer":"区といたしますと、そういった目的の趣旨みたいなところはやはり区民の皆様にもしっかりとお伝えをしていきたいとは考えております。その辺は避難所連絡会議の地域の方と情報交換をしながら、そこはしっかりと連携を図った形で訓練を実施していきたいと考えております。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"そこを明確にアプローチしていかないと、やはり今回は参加しません、参加しますとなってしまうではないですか。そこを明確にしていただきたいと強く思うのですが、いかがか尋ねました。","respondent":"大森災害対策担当課長、藤田防災まちづくり部長","answer":"区内一斉防災訓練の目的とか趣旨の部分についてですけれども、区といたしますと、やはりこういった訓練を進める意義は非常に高いとは考えています。今後もその目的とかをしっかりと丁寧に説明した上で… 各避難所の訓練そのものはそれぞれの避難所の訓練として実施はできると思うのですけれども、一番大事なのは、あるいは一斉に支援することができるか。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問・要望","question":"これを見ると、たくさん該当する避難所があれば、例えば伊藤学園はあんなに大きな施設なのに、町会は２つです。民間の施設をお願いするとかということで、それなりにカバー率を上げていかなければいけないのではないかと思うのですが、いかがか尋ねました。","respondent":"中島防災課長","answer":"区といたしましては、当然、避難所の収容人数のばらつきもありますが、全体といたしまして、補完避難所という考え方もあります。学校によっては、都立学校などの施設も活用いたしまして、区全体でしっかりと避難者を受け入れるような体制で考えているところです。","id":"exchange-040"},{"speaker":"西本委員","kind":"意見","question":"どういう使い方をしていいか分からないので。町会・自治会の方々に一緒になって考えてもらうとか、認識を高めてもらうとかしていただければと思うので、今後ご検討ほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"田中委員","kind":"質問","question":"こんの議員の質問の中で、要配慮者と外国人への情報提供のところで、情報共有の取り方が外国人の方への聞き取りがうまくいっていないと。どういう情報提供がいいのかを、どのような機会を捉えているのかと、現状どういった情報提供をされているのかを伺いたいです。","respondent":"中島防災課長","answer":"品川区国際友好協会を通じまして、ニーズを把握することについて検討をいたします。そのような場を捉えまして、ニーズを把握し、広報広聴課と連携して情報発信の具体化を図ってまいりたいと思います。","id":"exchange-042"},{"speaker":"田中委員","kind":"質問・要望","question":"１点、確認をしたいのですけれども、窓口でのタブレットのことが示されたのです。そのタブレットを少し調査したときに、こういう何か災害時だったりとかにそれは活用できないのかというところを少し確認させていただきたいのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"西本委員","kind":"質問","question":"２番のところなのですが、これは、国際友好協会はそれはそれでいいのですけれども、それだけで済むのでしょうかと思うのです。現状、それだけで分かるのだろうかと思うのですけれども、ほかのツールはありませんか。","respondent":"中島防災課長","answer":"防災課と連携している国際友好協会の事業の中で、ある程度のカバーはできているというところでこのように考えておりますが、その他のところについても検討してまいりたいと思います。","id":"exchange-044"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう方にアンケートをとるとか、それこそ防災課と一緒になって訓練を行うであったりとかというのは広がると思うのです。そういう方法もぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"若林委員","kind":"提案","question":"マンツーマンというのですか、いわゆる助け合い、そういう共助の地域をつくっていこうというのは提案したりした覚えがあるのですが。この資料を見ていて私は思ったので、そこら辺の考え方というか、取組をお聞かせほしいと求めました。","respondent":"中島防災課長","answer":"今回は４点ほど書かせていただいていますが、連携して、いろいろと情報共有しながら考えていければと考えています。そういう中でいろいろなお互いのいいところを提供し合いながら、連携をより深めて災害に備えていきたいと思っています。","id":"exchange-046"},{"speaker":"若林委員","kind":"質問・要望","question":"インドネシア大使館は、結構、積極的に地域に来られるという様子もうかがっています。今のお話とはまた違う展開になるのだろうというところも含めて、今後、取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"のだて委員","kind":"質問","question":"外国人への情報発信ということで４点、書いていただいているのですけれども、外国人の方が実際にここにつながっていけるのかなと思うのです。何をするとか、外国人の方がどうつながっていくと区では考えているのか、伺いたいと思います。","respondent":"中島防災課長","answer":"災害時、防災課としましては、しながわ防災ハンドブックや品川区防災地図もしっかりと多言語で情報をお配りしています。そういうところとか、先ほどの国際友好協会の事業など、使えるところをしっかりと捉えながら、情報発信に普段から努めていきたいと考えております。","id":"exchange-048"},{"speaker":"のだて委員","kind":"意見","question":"観光客として来られた外国人の方だと、そういう普段の発信とかは分からないです。そういう方たちが地震とかが起きた場合に、得られるというふうにしていかなければいけないのではないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/733618?Template=document&Id=4308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40856,"voices":143}},{"id":"r02-20201201-9","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"文教委員会","time":"午前１０時００分～午後 １時１８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"希望申請者の割合が大分減ったと思うのですけれども、その理由はどのようなものと分析しておられますでしょうかというのが１つと、あと、そもそも論として、区教委としてなぜ学校選択制を行っていいるのか、ねらいは何なのか、改めて伺いたいと思います。","respondent":"篠田学務課長","answer":"基本的には、平成３０年３月に学事制度審議会の答申を受けまして、新たな学区域ですとか、制度を各種、変更いたしました。学区域を変更したことによりまして、そういった部分でうまくつながるようになったので、選択が減ったのではないかと考えているところです。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"具体的にお伺いしたいのですけれども、全体の評価としては、これは選ばれる学校と選ばれない学校の差が開いているということになるのでしょうか。荏原第一中学校、日野学園あたりで転入が転出より逆に多いということで、その理由は何なのかも伺います。","respondent":"篠田学務課長","answer":"一番多いのは、一般的には多いという傾向がありますので、そういったことがあるのかと考えているところです。ある程度、そういった点では、そういった学校を選ばれる人が増えているのかなと考えているところです。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"どこの学校が改築というのは関係してくるのか、そこら辺を区としてはどのように捉えているのかをお伺いしたいと思います。中学校の方では、転出が大分多いと思うのですが、その理由はどのように考えていらっしゃるのかを伺えればと思います。","respondent":"篠田学務課長","answer":"浜川小学校などは、本格的に改築が始まっており、学区域から外に出られる方が１００名を超えているというような状況があります。小・中の連携がまだされていない形で入学されるお子様方が小学校に在籍されて、ほかの学校でもそういった傾向が見られると考えているところです。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"抽選校の中でも、住民基本台帳上の数と比べてかなり逼迫している学校が、御殿山ですとか、第二延山もそうですかね、この見通し、去年までは一応ぎりぎり入っているとはいえ、今後、どのように見通して対策を考えていらっしゃるのか尋ねました。","respondent":"篠田学務課長","answer":"御殿山ですとか第二延山に関しましては、今現在、住民基本台帳上の数と受入れ枠がほぼほぼ厳しい状況にあるという状況です。増えていっても対応できるところは受け入れられるだろうという形で、今、準備をしています。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問","question":"ある程度、この入学希望者数、あるいは住民基本台帳上の新入学者の数は、数年先まで見通せるものだと思うのです。そうすると、例えば３年、５年先、こうした学校はまだまだ増えるような状況なのか尋ねました。","respondent":"篠田学務課長","answer":"この先６年間、それに合わせて、教室の増設ですとかを早め早めに手を打っている状況があります。どういった対応をとっていくかは、直近の対応ではないのですけれども、先を見据えた対応をこれから検討していく必要があるかと認識しています。","id":"exchange-005"},{"speaker":"あべ委員","kind":"質問","question":"来年度に特別教室、あるいはその他、教室を潰して転用して教室を増やすというのは幾つぐらいか尋ねました。","respondent":"篠田学務課長","answer":"今の時点で、来年度の工事計画等は予算との絡みもあるのですけれども、ここのところ、例年ですと、５校前後で増やしていくような状況がありますので、これも人口の増加と併せて、同じぐらいの数をこういう形にしていくが必要あるのかなと考えているところです。","id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"こうして最初から選ばれない学校もどうしても出てくると思うのですけれども、今後、選ばれるようにしていくためにどうしたらいいのか。こういう結果になってしまったことに対する対応とか対策は、どのようにお考えになっているのか尋ねました。","respondent":"篠田学務課長","answer":"それぞれの学校はいろいろと考えながら、お子様方を自分の学校に、できるだけ地域のお子さんが残る形でそれぞれ対応をとっています。","id":"exchange-007"},{"speaker":"筒井委員","kind":"質問・要望","question":"その改築で新しくなったかどうかが選ばれる基準になってしまうと、全体的に改築というのはどんどん進めていっていただきたいのですが、その点はいかがお考えか尋ねました。","respondent":"有馬庶務課長","answer":"学校改築につきましては、長期基本計画でも実施計画事業と位置づけまして、計画的に進めているところです。日々、学校説明会でも行っておりますので、そういったところもしっかりとバックアップしていきたいと考えております。","id":"exchange-008"},{"speaker":"たけうち委員","kind":"質問","question":"１０足りないのですけれども、よそからの希望申請２０名の方については、抽選で１位から２０位まで順番がつくのかな。減を除いて１４０名の方が、抽選で仮に１番目になっていたとしても、こういう理解でいいのか尋ねました。","respondent":"篠田学務課長","answer":"受入れ枠は１３０名なのですけれども、そういった減も見込んで、受入れ枠を１３０名ほどの４クラスの設定でしています。２０名の方は順番がつくのですが、希望されても１人も入れないということは、数校出ていた状況はあります。","id":"exchange-009"},{"speaker":"横山委員","kind":"質問・要望","question":"１点ですが、なかなか一般の方が分かりづらいところが、お声が複数出ていると認識しております。ですので、ホームページ等で工夫をご検討いただきたいと思っているのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"予定者数が何かがよく分からないというお声もありますので、ホームページには説明書きもついている形で、対応させていただいています。今年度は前年度までの表現に合わせているところはあるのですけれども、これからは、そういったところは変えていければと考えているところです。","id":"exchange-010"},{"speaker":"せお委員","kind":"質問・要望","question":"年度末に数はあったのですけれども、改めて、特別支援学級の数を載せていないのはなぜかを教えていただきたいです。ちょっと何人かは入れるときに、たしか兄弟の関係は配慮していただけたと思うのですが、そこら辺をもう一度お聞かせほしいと求めました。","respondent":"篠田学務課長","answer":"個別の対応ができなくなってしまうので、そういう形では対応していないために、ここには載せていないというものです。いわゆる特別支援については、制度上の違いがあるということから、なかなかそのような形で取り込んでいくことは難しいかと考えているところです。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"例えばなのですけれども、上のお子さんが今度入って、下のお子さんが障害を持っている方で、どうしても特別支援学級に通わせたいと。そのような方だけではないのですけれども、いろいろな状況の方のお話も聞いていただきたいと思うのですが、そこら辺は状況としては無理か尋ねました。","respondent":"篠田学務課長","answer":"外れてしまった場合の対応ということで、指定校変更という制度がございまして、抽選が一番優先されているというのがあります。難病でいらっしゃって、どうしてもかかりつけの病院のそばでないとだめとか、そういったレベルでないと、今のところは対応をしていないところです。","id":"exchange-012"},{"speaker":"せお委員","kind":"質問・要望","question":"確かに個別で全部聞いていると、本当に大変かと思うのですけれども、兄弟枠があるということは、兄弟枠だけではなく、違った枠での検討もしてほしいと私は思っていますので、そこは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問・要望","question":"先ほどからのやり取りを伺っていて確認させていただきたいのですけれども、この表の中には、完全に数字に入っていないということなのでしょうか。確認させてください。","respondent":"篠田学務課長","answer":"住民基本台帳上のこの数字は、特別支援の方も含んだ数字です。ただ、特別支援の方でされる方もゼロではないということではあるのですけれども、今のところは計上がされているという形になってきてあります。","id":"exchange-014"},{"speaker":"あべ委員","kind":"確認","question":"確認ですけれども、住民基本台帳上の数字は、全てのお子さんを含んでいて、希望申請は出されないから、この枠、それ以降の右の枠には入ってこない、受入れ枠も、支援学級がここの数字に入っていないということか尋ねました。","respondent":"篠田学務課長","answer":"受入れ枠の中には、支援学級の数字は入ってございません。特別支援教室の対応等、様々ありますので、当初の中には特別支援と思われる方々も全部入ってきてはいるという形になっております。","id":"exchange-015"},{"speaker":"あべ委員","kind":"確認","question":"細かい数字の話で恐縮ですけれども、確認です。そこの矛盾はどのように考えていらっしゃるのか。","respondent":"篠田学務課長","answer":"下のお子さんが将来的に特別支援学級に入られるときに、なかなか制度上、難しいかなと思っています。そういった先行きを見通したものが対応が取れるのであれば、制度化していくことは、現状では難しいと感じているところです。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問・要望","question":"それと、１点質問を付け加えさせてください。３割は私立中学校で担っているのは、よりオープンにということでご検討いただきたいのですが、いかがか尋ねました。","respondent":"齋藤教育次長","answer":"私立を選択された方には、子ども政策の中で様々な取組みをさせていただいています。基本は、義務教育を基本に運営していますので、ご理解をお願いいたします。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"私立中学校も義務教育だと思うのですけれども、私立は義務教育の一環ではないのか尋ねました。","respondent":"齋藤教育次長","answer":"すみません、言葉が足りなかったと思います。公立の義務教育中学校と、義務教育後期課程の管理・運用をさせていただいているです。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問・要望","question":"私は、教育委員会には、品川区の子どもたち、特に義務教育段階にある品川区の子どもたちに対して、全てに愛情を注いでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"}]},{"id":"topic-02","title":"令和元年度品川区立学校における体罰等の実態把握","agenda":"令和元年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"たけうち委員","kind":"質問・要望","question":"毎年やっていらっしゃるのかどうかということと、その辺の、分かりやすく教えていただきたい。いわゆる校内でこういう聞き取りだったけれども、これはどこに当てはまるかをやっていくのか、その体制の概要を説明を求めました。","respondent":"工藤指導課長","answer":"体罰と呼ばれているものにつきましては、その対応によって、いわゆる傷害行為、危険な暴力行為です。最終的に校長がその学校の対応等を確認して報告していただき、最終的には東京都教育委員会とやり取りをする中で判断しているものです。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問","question":"質問が最初と違いますけれども、実際は違うのでしょうけれども、不適切な指導ぐらいのところになっていくのですか。この２つをお願いします。","respondent":"工藤指導課長","answer":"「実際にそうだったんですね」と理解を示すものもありますし、また、そのように丁寧に説明しています。（「教員からの申告は」と呼ぶ者あり） 教員からの申告のところは、指導に当たっては、複数で指導に当たる場合もあります。そこに居合わせた教員からも上がってくるというところはありますので、そういったことで、こういった案件を報告するようになっているところです。","id":"exchange-021"},{"speaker":"芹澤副委員長","kind":"確認","question":"数の確認で、この小学校の件数が、たしか合計８件だったと思うのです。４３件になったのは、説明されていたと思いますが、もう一度伺えればと思います。","respondent":"工藤指導課長","answer":"昨年との比較ということでご回答申し上げますけれども、今回は子どもに対して、全児童・生徒に対して質問紙を配って回答いただくところです。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"もう少し、この挙がってきた案件を分類する過程といいますか、もう少し説明してもらいたい。その申告からの流れをもう一度お伺いしたいのと、全５２校中の２４校ということでよろしいのか、これを伺いたいと思います。","respondent":"工藤指導課長","answer":"そういった流れの中では、この学校数については報告のないものもあります。４月１日からですので、掘り起こしも含めて、報告を上げているところです。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問","question":"やはりなぜ体罰がいけないのかを、根本から教師も子どもも考え合う機会というのですか、いかがか尋ねました。","respondent":"工藤指導課長","answer":"例えば３ページ、職員の連絡会等で人権意識を高めるということは、学校で取り組んでいただいているところです。基本的にはそれは不適切な行為に該当するという前提でお考えいただきたいと、そういった指導はこれからも引き続き行っていきたいと考えています。","id":"exchange-024"},{"speaker":"あべ委員","kind":"質問","question":"体罰が学校で禁止であるというのは、考え方としては定着していると思うのですけれども、改めて学校内での体罰の禁止は、どういった法律に基づいているものなのか、そして、その解釈はいつ頃から言われているものなのかを説明を求めました。","respondent":"工藤指導課長","answer":"体罰の禁止に関しましては、学校教育法第１１条に規定されているところであると認識しています。東京都全体の取組みの中で言えば、この調査が始まった平成２４年度、全区市町村で取り組むというところが大きな流れと認識しています。","id":"exchange-025"},{"speaker":"あべ委員","kind":"質問","question":"平成２４年の段階から、社会の体罰に対する考え方は、さらに進んできたと思うのです。今後、学校も合わせていくべきだと思うのですが、そこはいかがか尋ねました。","respondent":"工藤指導課長、矢部教育総合支援センター長","answer":"東京都の定義上の体罰ではないけれども、これらも許されるものではないという認識で、学校に対しては指導を行っているところです。本調査の場合では、そういった丁寧な指導を行うために必要であるという認識は… そこの中で改めて、体罰は学校でもしないけれども、家庭でも気をつけてくださいという通知文を、学校から保護者に出しています。保護者会や新１年生の保護者会では、虐待の認識を持つことや、そのあたりも周知しています。","id":"exchange-026"},{"speaker":"あべ委員","kind":"質問・要望","question":"むしろ家庭や学校の中で体罰によらないしつけと言ったらいいのでしょうか、小さい頃からのトレーニングというか学びの場でもあると考えています。学校でもどんどん取り入れていただきたい、そのような姿勢も持っていただきたいのですけれども、そこはいかがか尋ねました。","respondent":"工藤指導課長","answer":"あってはならないことが起きないようにという観点を持ちながら、様々なことを勘案しながら、体罰等の根絶に向けて指導をしていきたいと考えています。","id":"exchange-027"},{"speaker":"横山委員","kind":"質問・要望","question":"そういった中学校での児童・生徒の暴力行為などが多い学校の事例を１つご紹介させていただきたいのが、触らない、話は短く。研修の充実ということも挙げていただいていると思うのですけれども、そのあたりについて、ご見解をお聞かせいただけたらと考えています。","respondent":"工藤指導課長","answer":"ふだんから目安箱等を設置している中で、児童・生徒の声を聞くということは大事にしていきたいと考えていますし、学校に指導したいと思ってあります。","id":"exchange-028"},{"speaker":"横山委員","kind":"質問・要望","question":"学校作りということに関しても、ぜひお聞かせほしいと求めました。安全な学校作りというところ、体罰を根絶していくための学校経営、学校作りについての現在のお考えを説明を求めました。","respondent":"工藤指導課長","answer":"そういったことで、教職員だけでなく、児童・生徒、保護者も含めてみんなで取り組むということで進めているところです。複数人で当たる体制をとっている学校もありますので、そういった事例も共有しながら、やはり学校全体としてという学校作りは進めたいと考えています。","id":"exchange-029"},{"speaker":"横山委員","kind":"質問","question":"大変だとお聞きしておりますので、なかなか現実的に不適切な指導にならざるを得ないことが発生してしまうことがあるのかも分からないと考えています。品川区の教育委員会全体として取り組んでいくべき部分があるかと思いますので、今できることをぜひ進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"せお委員","kind":"質問・要望","question":"そちらをメインにしていただきたいと思うのですけれども、書式が決まったシートとか、そういったものはあるのでしょうか。その２つを説明を求めました。","respondent":"工藤指導課長","answer":"もしくは遅くとも翌日には私どもに報告が上がってくる案件ですので、そういったものも集めて、この調査自体は１２月にまとめてということがあります。学校から報告いただき、行っているもの、取りまとめとしてはこの時期に行っているものです。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"５３件中４１件が非該当になってきて、８割方が非該当になっているのですが、具体的にどのようなケースが非該当とされたのか。幾つか具体的な事案があれば説明を求めました。","respondent":"工藤指導課長","answer":"今回のようなケースで考えられるところを私どもでつかんでいるところでいきますと、また、そういったものが非該当ということで確認するものです。","id":"exchange-032"}]},{"id":"topic-03","title":"品川区教育大綱の改訂","agenda":"品川区教育大綱の改訂","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"それと質問ですけど、２ページに大綱の位置づけの図が出ていますけど、それがかなり形骸化しているような状況が残念ながらあると思います。区の教育委員会としては、教育の独立性、自主性についてどのように考えていらっしゃるのかを伺いたいと思います。","respondent":"有馬庶務課長","answer":"それで、もう一方では教育委員会のほうの目標もありまして、ルネサンスで教育も進めていると。例えば、そういったところを今後も教育委員会と区長部局、首長が連携して進めていこうということで大綱ができているものと捉えているところです。","id":"exchange-033"},{"speaker":"安藤委員","kind":"質問・要望","question":"住民、子どもの立場に立って言うべきところはしっかりと言えるような、独立性を意識しながらこれからも取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"位置づけをお伺いしたいのですが、品川区の教育大綱は、大綱というだけではない様々な観点が割と細かく入っているかと考えています。品川区としては、割と細かく書かれているけど、これを大綱そのものというふうに位置づけていらっしゃるのかを説明を求めました。","respondent":"有馬庶務課長","answer":"目標、理念だけではなくて、分野別に落とし込んでいるという構成になっています。この方針に基づいた個別の事務事業については、これに沿って行っていこうと、ちょうどそのぐらいのレベルの大綱になっているです。","id":"exchange-035"},{"speaker":"あべ委員","kind":"質問","question":"この大綱は、今後、印刷、配布ということなのですけれども、どの程度印刷して、どのようなところに配布をするのか。この教育大綱をどういった方々に理解していただき、共有したいのかを説明を求めました。","respondent":"有馬庶務課長","answer":"今、私どもが聞いているところでは、大体四、五百ぐらいを今回については印刷すると聞いておりまして、各所管のほか、例えば区政協力委員ですとか、地域の青少年対策地区委員の人たちとか、そういったところに配るようなことを聞いているところです。","id":"exchange-036"},{"speaker":"あべ委員","kind":"質問・要望","question":"さらにこうしたことに関心を持っていただくための方策を考えていただきたいというのが１つと、内容が大綱としては字数が多いですから、結局。それぞれに、随分とそのページの中で何を言っているか伝わるのではないかと思うのですけど、そうした工夫は今からでもできる余地はあるのか尋ねました。","respondent":"有馬庶務課長","answer":"この委員会の報告、総務委員会のほうも終わってからと聞いておりますので、そのやり方については工夫の余地があると思います。同じような形、大幅に変わるかどうかは難しいと思いますけど、そういう意見があったということは申し伝えておきたいと思います。","id":"exchange-037"},{"speaker":"あべ委員","kind":"質問","question":"前半の質問なのですけれども、パンフレット以外にどのような形で周知を図っていくかということについて。","respondent":"有馬庶務課長","answer":"基本的にホームページで公表すると聞いてあります。","id":"exchange-038"},{"speaker":"あべ委員","kind":"意見","question":"これは最後、意見にしておきますけど、ホームページでこれを見にくる方というのは、ほぼいらっしゃらないかと思います。これは単なる役所の自己満足というか、こなし仕事になってしまっては大変よろしくないので、そこはぜひ工夫してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"長期基本計画は中間見直しとかが行われていると思うのですけど、教育大綱も中間見直しは行われるのでしょうか。当然、時代の変化とかにあわせて直すところは直さなければいけないのかと思っているのですけど、その点、どうなのか尋ねました。","respondent":"有馬庶務課長","answer":"今回につきましては、長期基本計画とあわせた計画をある程度踏まえてつくっていますので、当然、長期基本計画は中間見直しが行われると思いますので、そういったタイミングがあればそのときにあわせてこちらのほうも見直すということになります。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問・要望","question":"４ページの品川区の教育を取り巻く状況の変化のところで、１段落目で人口推計が、よろしくお願いします。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"品川区総合教育会議なのですけど、傍聴もさせていただきまして、教育委員のご意見を少し伺った中で、そこに関連して伺っていきたいと思っています。９ページになるのですけれども、しくみづくりというところがあるかと思うのですけれども、そのあたりについても方向性をお聞かせいただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-042"},{"speaker":"横山委員","kind":"意見","question":"すみません。連携の状況といいますか、教育委員会からの連携の状況に関しての部分で構いませんので、説明を求めました。","respondent":"有馬庶務課長","answer":"スポーツのところは、委員長がおっしゃったとおり私からの回答は難しいところがありますけれども、できるだけスポーツの機会とは連携をとっていく。最後の質問の回答になりますけど、連携をということでありますと、その辺はしっかりと連携して進めていきたいと考えております。","id":"exchange-043"},{"speaker":"せお委員","kind":"質問","question":"７ページのすまいるスクールなのですけれども、私は一般質問でもお聞きしましたが、全児童放課後等対策事業となっているのですね。全児童放課後等対策事業というものは改めてどういうものなかということと、すまいるスクールの１０年間の方向性がありましたら説明を求めました。","respondent":"廣田子ども育成課長","answer":"この１０年間といいますか、現状を申し上げますと、全児童というところが立ち行かないようなところになっているというのが実際の問題です。","id":"exchange-044"}]},{"id":"topic-04","title":"子ども家庭支援センター開所日の追加","agenda":"子ども家庭支援センター開所日の追加","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"今年４月に開所していろいろとやっていく中で土曜開所の必要性が出てきて追加的に行ったのかという、そこら辺の考え方をお伺いしたいのと、その分の人員配置の追加とか現場への支援策というのはどのようなことがあるのかを伺いたいと思います。","respondent":"崎村子ども家庭支援センター長","answer":"他区の子ども家庭支援センターにつきましては土曜日も開所しているところが３分の２ほどございまして、当初から検討はしていたところです。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"参考までに、開所してからこれまでの相談件数、特に１日平均の件数と、あと、土曜も開いてほしいという具体的なお声なり要望があったのか尋ねました。","respondent":"崎村子ども家庭支援センター長","answer":"我々がケースの対応をしている中で、土曜日にしてもらえないか、日曜日にしてもらえないかという声はいただいております。そういったところで、我々もこれまで柔軟に対応することで土曜日の訪問面接ですとか家庭訪問などを実施してきたところなのですけれども。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問","question":"土日は平日以上にニーズが大きい部分もあるかと思いますので、今後も体制を充実してほしいと求めました。夜間や日曜日のご相談というのはどこが受ける形になっていて、それが子ども家庭支援センターにどのような形で共有されるのかも説明を求めました。","respondent":"崎村子ども家庭支援センター長","answer":"一旦、緊急性がある場合には１１０番通報をお願いするとともに、宿直からも１１０番をして警察のほうに対応していただいたというところがあります。","id":"exchange-047"}]},{"id":"topic-05","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"これは区内では初の事業者になるのでしょうかということと、あと、人件費比率や離職率の状況などがもしつかめていれば教えてください。それぞれ開設日が９月１日になっていますけど、品川区としてどういう考え方を示して開所に至ってくるのか、そこら辺の考え方を伺いたいと思います。","respondent":"若生保育支援課長","answer":"離職率につきましては１５％ということで把握しています。これは子ども・子育て支援事業計画にのっとって開設を進めているところですけれども、どのくらいの物件、そういったような状況です。","id":"exchange-048"},{"speaker":"安藤委員","kind":"確認","question":"そういう形で掲載されているのかという確認と、あるいは１歳児園なのかゼロ歳児園なのかとかというのも、あわせてお伺いしたいと思います。","respondent":"若生保育支援課長","answer":"それから、こちらにつきましては、待機児童の中心となるのが現在ですと１歳児がかなり多くなっている状況があります。６０人以上の定員が必要であるという考え方があるので、６０人以上の定員を設定してくださいというような形で事業者のほうにはお伝えしています。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"年度途中で２園開設ということなのですけれども、来年度については、４月の８園とこの２園のほかにまだ進行中のものというのはあるのでしょうか。それ以降の年度で何か見通しがあれば説明を求めました。","respondent":"若生保育支援課長","answer":"今年度につきましては、今回の９月開設の２園で、今のところはそれ以外の開設の予定はございません。２園募集しているところですけれども、今後の地域ごとのニーズ等を把握し勘案しながら、適切な時期に募集等をかけていきたいと考えています。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"参考までに、例えば大井町などでは、ひろまち保育園がなくなって、あのあたりの受け皿がぐっと減ったかと思うのですけれども、地域的に今ちょっと入りにくいエリアというのは、どのあたりと認識されていますか尋ねました。","respondent":"立木保育課長","answer":"東大井地区、八潮地区は、待機児童ということで９名ほど出てございました。保育支援課のほうで新規開設を進めておりますし、また、そこら辺は地域バランスをとりながらやっていっているという認識です。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/418457?Template=document&Id=5020#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":40849,"voices":138}},{"id":"r02-20201201-5","meetingId":"r02-cm12","date":"2020年12月1日","dateIso":"2020-12-01","committee":"総務委員会","time":"午前１０時００分～午後 ０時０２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を39件整理しています。","topics":[{"id":"topic-01","title":"説明に入る前に、各所管委員会における審査結果","agenda":"説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"中塚委員","kind":"確認","question":"質問ですけれども、今回の補正予算ですが、今の第３波に対応するものなのかどうか伺いたいと思います。その本部では現状を第３波と認識されているのか、現状を危機的な状況だと認識されているのか、そこを伺いたいと思います。","respondent":"品川財政課長","answer":"コロナ対策については、一定の状況において対応ができるような考えで予算を編成していますので、一定の状況に対応できる形で予算を編成しています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"確認","question":"先ほど伺ったのですけれども、第３波と感染拡大状況や医療体制の逼迫、そこを改めて伺いたいと思います。検査の拡大で感染をしっかり抑制するという立場に立つことが必要だと思いますけれども、その点はどのようにお考えか尋ねました。","respondent":"品川財政課長","answer":"それから、ＰＣＲ検査については、区としてもＰＣＲ検査センターを設けて、必要な方については随時対応してきているところです。今回の補正予算でも東京都の補助もありますが、介護入所者等については対応していくなど、ＰＣＲ検査についても徐々にしっかり進めている状況です。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めて伺いたいと思います。感染が抑制できたということは統計的にも明らかになっておりますので、区もぜひ検討してほしいと求めましたが、いかがか尋ねました。","respondent":"品川財政課長","answer":"今、ＰＣＲ検査センターを設けて、必要な方については随時対応している状況があります。最近になって少し出始めているというところで、その情報をしっかりと把握して、対応できる部分については進めていきたいと考えております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"長期化しているわけですから、この支援を拡充・継続していくべきだと思うのですが、その点を伺いたいと思います。私としてもつかんでいる実態としても明らかになっているわけですから、事業所と区民への直接支援を、それぞれいかがか尋ねました。","respondent":"品川財政課長","answer":"これはまた状況に応じて必要な部分があれば、今後も対応していきたいと考えています。区としても４月から融資枠を広げたり、補助金の免除といった部分で、中小企業に対して他区よりも大きく充実した形で支援をしていると考えております。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"持続化給付金を継続するように国に求める考えはないという答弁でしたけれども、必要な事業の継続をしっかり求めていくことが併せて必要かと思います。継続して、財源も含めて実施するよう求めてほしいと求めましたが、いかがか尋ねました。","respondent":"品川財政課長","answer":"中小企業もしっかりと事業が継続できる、それから、スピーティーに対応していくことを今後も進めていきたいと考えております。そういう中で、国や都がそれぞれ状況を判断しながら、適切な施策を進めている中で、区としてそこについて意見を求めることは考えてございません。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ国に対しても意見を求めていただきたいと改めて求めたいと思います。そういうお立場に立っていただくことを要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"吉田委員","kind":"質問・要望","question":"最初に、総務委員会の所管になると思うのですけれども、総務管理費の代替職員雇用経費、電話相談センター等対応経費です。こういう補正予算をつけられたのだと思うのですが、この中身についてもう少しご説明いただきたいのですけれども、いかがか尋ねました。","respondent":"黒田人事課長","answer":"そのときに医療体制を２３名体制というところで少し拡充してやってきており、また、感染拡大の状況に応じて時間外勤務にも従事させておりました。その他、保健所以外でも、そういった様々な年度末までの見込みでの人的経費というところで予算を計上させていただいているものです。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"何日か一緒に過ごした家の人を受け入れたら、そこから感染が広がるのではないかと思っても仕方ないようなところがあるではないですか。その辺のことについて、先ほどからのご答弁で出ているＰＣＲ検査が必要な人というのをどの辺まで考えていらっしゃるのか改めて伺いたいと思います。","respondent":"品川財政課長","answer":"ＰＣＲ検査の考えについては、ＰＣＲ検査等を、ＰＣＲ検査センターも含めて行っていくという体制をとっております。ですので、そこで検査体制をとるという体制は十分にとっておりますので、そういったところをご利用して対応していただきたいと考えております。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"もう一つ、１８ページの児童保育費の保育関係事務費で感染拡大防止対策物品購入が計上されていて、これは一般財源ですか。さっきこれも新型コロナウイルス感染症対策指定寄附金と聞こえたのですけれども、その辺を確認させてください。","respondent":"品川財政課長","answer":"これは、基本的に寄附をもとにして対応していくという趣旨のものですが、金額的に寄附の額等で対応できない部分もあったところもありますので。ですので、寄附と一般財源をあわせた形で予算計上しています。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問","question":"ということは、児童保育費については、ここだけは一般財源が充てられたと理解してよろしいか尋ねました。","respondent":"品川財政課長","answer":"補足します。公立と私立でちょっと考え方を変えておりまして、４目の児童保育費については全て一般財源で対応していると、そのような考え方です。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"１７ページの子ども食堂への運営費補助ですが、申請が６カ所だけだと書いてありますが、実際にはもっとたくさんありますよね。なぜこうなっているのか、それとも補助金が使いにくいのか、その辺について説明を求めました。","respondent":"品川財政課長","answer":"この都の補助につきましては、一定の条件がありまして、子どもの食の確保を広げていこうというところが都の補助としての大きな趣旨です。ですので、現行、子ども食堂でやっている業務よりも拡大する部分について補助を出していこうという考え方の補助金です。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"現在大変な状況ですから、区の事業ではないのですが、ちょっとそれだけは異議を唱えたいと思います。そういうふうに思うと、財政や企画の部署のほうでは、区内産業の存続に対してどのようなことを政策的に考えられているのか説明を求めました。","respondent":"品川財政課長","answer":"今、そこに対して区として融資をしていくというところで対応策はとっていますが、例えば固定費を補う部分での融資という言い方もありますし。総合的に考えれば、融資をしていくという部分で前向きな形でやっていく融資だというふうに考えております。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですから、本当にこの１２月、大勢の人を救うのではないかと考えています。こんなことをしていたらだめだと思うので、皆さんが何とか乗り切れるようにやってほしいのですが、何かご見解をいただけますか。","respondent":"品川財政課長","answer":"ただ、経済も回していかないと、やはりここの部分についてはバランスをとりながら進めていくということは非常に大事なことだと考えています。こういう部分を区としてもしっかりと情報収集しながら適切な対策を随時打っていきたいと考えています。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですけど、やはり身近な自治体は品川区ではないですか。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"新妻副委員長","kind":"確認","question":"１点だけ、電話相談センター等対応経費の部分の補正予算、年度末までの人員確保のためと確認をします。９月に、この２３名は、自分が感染したかどうかＰＣＲ検査を受けたほうがいいのかどうかという相談員というところでの２３名でよろしいのか尋ねました。","respondent":"黒田人事課長","answer":"この２３名の内訳ですが、帰国者・接触者電話相談センターの電話相談を６名体制で行っておりまして、保健所のバックアップというところの相談業務を行っているです。","id":"exchange-015"},{"speaker":"新妻副委員長","kind":"質問","question":"爆発的に感染が拡大をした第１波のときに、また電話がつながらない、そういう中での区民の不安が多くありました。東京都がやっていただいておりますけれども、土日の品川区の相談体制の考え方もぜひ柔軟にご検討ほしいと求めましたが、いかがか尋ねました。","respondent":"黒田人事課長","answer":"相談業務体制につきましては保健所のほうで体制を組んでおりますので、また、今日いただいたご意見につきましては保健所のほうに伝えてまいりたいと考えております。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"危機的な第３波に対して対応をするために、事業者や区民に対する支援の継続と強化、医療機関や保健所への支援を直ちに行ってほしいと求めました。次の第１回定例会は大分時期が離れていますので、第１回定例会を待たずに臨時で補正予算を組むことも含めて早急な対応を要望して、賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"}]},{"id":"topic-02","title":"品川区教育大綱の改定","agenda":"品川区教育大綱の改定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"これは要望したいと思います。その中身について１点伺いたいのですけれども、性の多様性について、どのような取り扱いになっているのか伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"その目標や施策の根本となる方針を定めるものとして、その辺に対して、長期基本計画の改訂部分を反映しています。委員がご指摘の点に関しましても、今後品川区総合教育会議の中でさまざま議論しながら、追加を検討してまいりたいと考えております。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"長期基本計画全体の議論の中でも多様性というのが１つのテーマになりまして、ぜひそこを踏まえていただきたいと要望したいと思います。そこにも関わって、首長との関係、教育委員会の独立性について、区長部局としてはどのように認識されているのか、併せて伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"そちらに関しまして区長の認識といいますか、こちらの２点に関する趣旨、ご発言がありました。２点目といたしまして、独立性に対する認識ですが、基本的に自治体の教育行政はその自治体の教育委員会が執行すると法令で定められているところです。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"この会議については、そうではなかったようなのですが、その辺についてはいかがか尋ねました。","respondent":"立川総務課長","answer":"総合教育会議については、総務課が所管しておりますので、私からお答えいたします。資料につきましては、後日議事録とともに公開することになっておりますので、その場での配付はしなかったです。","id":"exchange-020"},{"speaker":"吉田委員","kind":"質問","question":"特にこの会議について資料の配付が困難とか、何か差し障りがあるとか、そういうことなのでしょうか。せっかくの公開の場も、効果が半分ぐらいに減ってしまうのではないかと思うのですけれども、その辺について改めて伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"須貝委員","kind":"意見","question":"お答えはできにくいのかもしれないのですけれども、教育制度の充実も図ることが今後必要ですという一文を入れるべきではないかと思います。意見だけ述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"松澤委員","kind":"質問・要望","question":"私も要望だけになってしまうのですけれども、現在、関係機関と連携しているというのは認識しています。やはり子どもと保護者、先生がちゃんとした連携をとれる時間を見つけるとか、そういった充実の強化を強く要望したいと考えています。","respondent":"佐藤企画調整課長","answer":"私の説明がちょっと不足だったと思うので、２ページをご覧いただきまして、品川区の教育大綱の総務的な方針を定めるものというところです。他区の大綱は１枚、２枚だけで品川区の場合は、やらないということではございません。","id":"exchange-023"},{"speaker":"湯澤委員","kind":"質問","question":"こちらにもシルバー大学の充実とか、この状況下でシルバー大学が開催できるのかどうかというところもあるかと思います。高齢者だけではなく、今後大綱においてはどのようにしていく方針なのかを教えてほしいと求めました。","respondent":"佐藤企画調整課長","answer":"品川区総合教育会議でもご意見がありました高齢者等の生涯学習の重要性です。今後実施計画のほうでも改めて定めまして、着実に進めていくというところで、今回大綱に載せているところです。","id":"exchange-024"},{"speaker":"湯澤委員","kind":"質問・要望","question":"新型コロナウイルス感染症はだれもが初めて経験するものなので、本当に探り、探りというところもあるかと思います。子どもたちはもちろん、大人、高齢者といった方々それぞれが品川区で学び続けられるようなものになればということを要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-03","title":"品川区庁舎機能検討委員会の実施状況","agenda":"品川区庁舎機能検討委員会の実施状況","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"品川区庁舎機能検討委員会の実施状況が説明されたわけですが、この間私はＤ案を撤回してほしいと述べてきましたが、区はＤ案を予定している。ならば、新庁舎は延べ床面積が何平米なのか、何階になるのか、改めて建設費用は幾らを見込んでいるのか、そこを伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"現在利便性の向上を中心に延べ床面積を大きくすることを検討しておりまして、今現在これぐらいだというものは、まだ検討している段階です。建設費用につきましても、規模や構造に関わってきますので、今現在では検討している段階です。","id":"exchange-026"},{"speaker":"中塚委員","kind":"質問","question":"私は、正直どうしたものかと思っているのですけれども、これまで延べ床面積については７万平米ぐらい必要だとご答弁されているわけです。なので、Ｄ案でいくというのであれば、何平米なのか、何階なのか、建設費用は幾らなのか、改めて伺いたいと思います。","respondent":"濱中庁舎計画担当課長","answer":"延べ床面積につきましては、大きくすることを想定して検討を進めている段階です。建設費用につきましても、規模や構造が決まってきた段階で、概算を出していくことになっておりますので、まだ今は検討中です。","id":"exchange-027"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこで、品川区庁舎機能検討委員会を第５回で終了とするのではなくて、ぜひ延長して議論を深めてほしいと求めましたが、いかがでしょうか。少なからず数百億円の公共事業になるわけですから、着工は延期していくべきだと思いますが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"２回目で議論したことを３回目で、そこについてもご意見を賜っているところですので、５回目で機能のまとめを作っていく予定です。庁舎機能の検討をしっかり進めまして、整備計画を着実に進めていくことが必要だと考えております。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"第５回で終わらせるのではなくて、期間を延長して審議を深めていくべきだと思うのですが、改めていかがでしょうか。パブリックコメントは実施すべきだと思いますが、それぞれいかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"２回目で防災・環境、またセキュリティーやＩＣＴといったことをもしっかりと検討していきましたので、第５回で庁舎機能検討委員会を終えまして。まず、庁舎機能の検討をしっかり進めまして、基本構想を作っていきたいと考えています。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"１つのテーマを実質１回しか審議しないというのはあまりにも乱暴だと思います。ぜひ庁舎機能検討委員会の会期は延長していただきたいと強く求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"この機能検討委員会のまとめが出た段階で、そこから抽出されたもっと具体的な事について検討されてはどうかと思うのですが、いかがでしょうか。だから、そういうことを深めていくような機能検討の場がその次の段階として考えられるのではないかと思うのですが、その点についてお考えを伺います。","respondent":"濱中庁舎計画担当課長","answer":"まさに庁舎機能検討委員会であるべき姿や具体的な項目を検討していますが、これで検討が終わりではなくて、機能検討を深めて。そういったさまざまな特徴を分析しまして、品川区役所に合ったワンストップ窓口の在り方はどういったものかを今後考えていくところです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"提案","question":"今日のところは、今ご提案したようなことはここで決めるようなことではありませんので、あくまで意見として申し述べました。ここで検討が始まったのであれば、丁寧に議論を進めるほうに重点を置いてやっていただきたいと要望して、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"意見を出し合って、新しい形のトイレも検討されておりますので、ぜひそういうのも視野に品川区において検討を深めていただきたい。バリアフリーについては羽田空港国際線での視点もぜひ十分踏まえてほしいと求めましたが、いかがか尋ねました。","respondent":"濱中庁舎計画担当課長","answer":"トイレについてです。さまざまな先進自治体の事例や民間施設の事例を研究しながら、快適で使いやすい、またバリアフリーに配慮した庁舎を検討していきたいと考えています。","id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"せっかく本体が１００年もっても、何も改修工事ができないと困るので、それはちょっと考えてほしいと求めました。品川区の４０万人の人、いい庁舎ができて、区民がいつも安心して暮らせるような場所があるといいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-04","title":"その他のうち、(1)所管質問","agenda":"その他のうち、(1)所管質問","exchanges":[{"speaker":"吉田委員","kind":"質問・要望","question":"１日目の高橋しんじ議員の区政運営についてのご質問の中で、会計事故に関しての監査委員のご見解、たしか２つ見解を求められたと認識しております。もう一つのほうがよく理解できなかったので、本来使うべきでないお金について処理したことについてのご見解を改めて伺いたいと思います。","respondent":"今井監査委員事務局長","answer":"高橋しんじ議員に対する代表監査委員の答弁のうち、歳入歳出外現金による事故対応について申し上げたいと思います。答弁の中では、限られた時間の中で会計処理の方法を検討し、適用したものと理解していますと答弁いたしたものです。","id":"exchange-035"},{"speaker":"吉田委員","kind":"質問","question":"代表監査委員としては、そういう状況であれば、今回の場合は限られた時間の中でやむを得なかったというのがご見解というご答弁だったのでしょうか。その辺がちょっと理解できなかったので、改めて伺います。","respondent":"今井監査委員事務局長","answer":"既に決算特別委員会の決算審査意見書の中で監査委員合議の上で決算審査意見書をまとめる際に、このような限られた時間の中で適用したものと理解したということで、そのようにまとめております。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"つまり、見解としては、会計事故については、こういうことが起きたことは大変遺憾だというご答弁をなさっていますが、その後の処理については理解したというところまでで、それが妥当であったとか、不適切であったという見解は出しておられないということでよろしいのか尋ねました。","respondent":"今井監査委員事務局長","answer":"代表監査委員の答弁のとおり、会計管理室が限られた時間の中で会計処理の方法を十分検討して、監査委員としてはそれを適用したものと理解しているということで答弁したものです。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問","question":"つまり、それがいいとか悪いとか、代表監査委員としては、そういう発言をする立場にはないという趣旨で理解してよろしいのか尋ねました。","respondent":"今井監査委員事務局長","answer":"適用というお示ししている言葉の使い方としては、限られた時間の中でこのような方法をとったものも対応の一つということで理解しているということで、そのように受け止めていただければと思います。","id":"exchange-038"},{"speaker":"中塚委員","kind":"質問","question":"今のやりとりの前提となっている会計事故が何なのかが分からなくて、限られた時間の中で対応したというのは、何があったのですか。そこだけちょっと教えていただけますか。","respondent":"立川総務課長","answer":"ただいまいただいた質問につきましては、現在会計管理室で再発防止策を進めているところですが、指定金融機関の協力が必要な再発防止策について現在協議を進めておりますので、協議が整い次第、改めて所管のほうから報告します。","id":"exchange-039"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/346628?Template=document&Id=2186#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":35057,"voices":109}},{"id":"r02-20201203-14","meetingId":"r02-cm12","date":"2020年12月3日","dateIso":"2020-12-03","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 １時２５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/988746?Template=document&Id=6100#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2020-01-01&TermEnd=2020-12-31"}],"sourceMeta":{"pages":0,"characters":1118,"voices":7}}]);
